INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (98, '你们已经毁掉了自己的土地，别想再毁掉我的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (548, '一切都完了！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1200, '天气太热吗？在猪和哨声旅店喝点东西凉快一下吧！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1201, '在猪和哨声旅店享受夜晚的喧闹和最好的啤酒！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1202, '猪和哨声旅店有免费的啤酒供应！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1203, '要想得到猪和哨声旅店的免费啤酒券的话，就赶快来找我！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1205, '比精灵更聪慧！比兽人更强壮！暴风城没有比这更好的酒了！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1206, '你厌倦了那些娘娘腔的法师才喜欢喝的水了？来猪和哨声旅店享受一下真正的男人该喝的酒！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1207, '刚刚长途旅行归来？在猪和哨声旅店休息放松一下吧！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1208, '这里有暴风城最好的酒！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (1285, '%s柔和的声音在薄雾中轻轻回响，“我永远爱你……”') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2030, '《不可思议的魔法流动及它是如何影响这个世界的》，玛吉诺·仲马著。我在一直寻找这本书。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2032, '《卡德加的魔法日记，第八卷》，我要的是这一本。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2033, '哈，《达拉然大法师的神秘咒术》，太棒了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2034, '不知道我能不能找到《魔法和能量的守则》这本书。啊哈，在这里，它怎么会在这里？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2035, '《魔法致病学》，不对不对。《魔法矩阵》，也不对。啊，就是这个，《魔法神秘学》。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2053, '这种恶魔被称为虚空行者。它的力量和耐力都非常惊人，可以出色地胜任防御任务。首先控制它来攻击你的敌人，这样就能保证你在有肉盾保护的情况下安全地使用法术和技能。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2463, '看看，风险投资公司的新伐木机比我的要好多啦，从可拆换的机械臂到控制把手，都是那么棒！我的老板给我下了死命令，但我们却拿不出任何东西。$b$b现在我们自己的设计研制工作已经完全停止了，所以我决定向他们“借”一个。我派维兹克兰克去淤泥沼泽偷一个回来，但他到现在还没音讯！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2703, '转动钥匙，启动了机器。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2750, '暴风城银行坐落在贸易区，就在城门的西北面。来，让我在地图上指给你看。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2843, '你好，$c，很高兴认识你。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2844, '我的陆行鸟需要接受训练。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2878, '狮鹫？你是要使用空中旅行服务吧，到贸易区的城墙上去找到杜加尔·朗德瑞克就可以了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2880, '你想要成立一个公会，对吗？祝你好运！\n和暴风城接待中心的奥德文·拉弗林谈谈吧。你从英雄谷进入贸易区之后就可以看到暴风城接待中心了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2912, '想要接受训练？我可以把你训练成暴风城最好的战士，但是守卫是不能这么做的。我想你得去兵营或者猪和哨声旅店，找些合适的人来对你进行训练。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2913, '去兵营或者猪和哨声旅店逛逛吧。如果你去旅店的话，别忘了尝尝那里的好酒，那些酒绝对能让矮人的酒相形见拙。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2927, '什么？我不认为暴风城里有术士训练师。\n不过……在法师区的那家名叫“已宰的羔羊”的旅店中有一些与恶魔有关的活动，我想你应该去那里看看。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2953, '如果你要学习炼金术，暴风城只有一个地方值得你去……那就是炼金材料店。你可以沿着法师区的外围找到这家店铺。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2954, '你应该去找瑟鲁姆·深炉谈谈，他是我见过的最好的矮人铁匠。你可以在矮人区的中心地带找到他。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2955, '如果你想要成为一名好厨师，那就去旧城区的猪和哨声旅店，找斯蒂芬·雷百克谈谈。那家伙知道怎样才能做出与众不同的肋排大餐来。\n啊……说到他那著名的肋骨大餐，我都感到有些饿了。你可不要指望他会把那道菜的做法传授给你！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2959, '你想要学习制皮？西蒙·坦纳尔可以教你。你可以在旧城区的“护体皮甲”店里找到他。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2960, '不知道你为什么要学习这样的技巧？只有不诚实的家伙才会去学习如何开锁。\n如果你真的想要学习这种伎俩，那最好到旧城区那边去，可能就在那些小巷里面。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2979, '森林里到处都是奇怪的野兽和被污染的空气。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2980, '塞尤娜，你好。我要需要接受训练。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3003, '如果我们要成为这块新地区的主人，那么我们就必须要找个地方好好休息。把你的斧子放在火边，让大家分享你英勇战斗的故事吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3008, '生存技能是一项很有用的技能。\n去找凯尔布鲁斯吧，他在花园区的月亮井附近。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3009, '没有什么能比在水晶湖钓一天的鱼更惬意的事情了。阿诺德·利兰教我学会了钓鱼。你可以在运河区的码头找到他。\n哦，不要相信他告诉你的任何关于运河里有怪物之类的故事。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3010, '鲁坎·考迪尔在监狱附近的运河边上有一家小店。我相信他可以教你附魔的技巧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3013, '你能告诉我布瑞恩在哪里？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3189, '什么是“地下生物母体”？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3190, '你所说的变化是什么？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3191, '什么是“弹性构造基础”？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3192, '难道……土灵是用石头做出来的？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3241, '嗨这是我的文书。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3261, '没人可以窃取造物者的秘密！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3262, '你怎敢亵渎这个神圣的地方？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3263, '%s裂成了碎片！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3404, '欢迎来到猪和哨声旅店！和朋友在这里举杯畅饮，不亦乐乎！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3483, '在雷霆崖，你肯定找不到比阿丝卡·迷雾行者更好的厨师。嗯……我在这里都可以闻到他正在烹制的美味佳肴。你可以在中部高地的厨房里找到她。\n呃……我又饿了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3484, '到中部高地的附魔店去看看吧。泰戈会很乐意帮助你的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (3486, '我不会因为你想学钓鱼而责怪你的。莫高雷有卡利姆多大陆上最好的钓鱼胜地，而在山顶渔具店中，你可以找到钓鱼所需的一切装备。\n告诉卡尔·迷雾行者是我让你去的！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4003, '获取更高等级的数据卡。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4010, '获得：自动净化装置') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4014, '新鲜的面包，今天早上刚刚出炉的啊。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4058, '什么？我们的世界“被安排了新的探访计划”？这是什么意思？！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4083, '感谢圣光！现在情况十分紧急，即使有一个双头食人魔愿意施以援手，我也会欣然接受的。\n这座城市里到处都是穴居人！为了把它们赶出这里，我们采取了一些行动，但是却导致这一地区遭受了大面积的污染。幸好我们还有希望！\n我们疏散到铁炉堡的科学家正在研究对付辐射疾病的方法。同时，如果你能帮我阻止穴居人的入侵，那也许我们就能够夺回我们的城市！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4084, '我准备好了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4163, '保持阵形——入侵者正在靠近。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4227, '关于绿荫旅店，你都听说过些什么？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4254, '洛拉姆斯，无论你是否帮忙，我都会去做的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4261, '寻找帕瓦尔·雷瑟。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4309, '当你待在旅店里的时候，你就可以好好地休息。因此,你可以比留在野外更快地恢复到精力充沛的状态，这样就可以获得更多的经验值。$B$B另外你还可以通过和旅店老板交谈来获得一块炉石，以后就可以使用这块炉石快速回到你绑定的旅店里了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4325, '全部准备就绪。后退！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4629, '即使在和平时期仍然会有战争，而许多氏族仍在酋长的领导下奋勇作战。你是来为奥格瑞玛而战的吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4630, '即使在和平时期仍然会有战争，而许多部落仍在酋长的领导下并肩奋战。你是来为奥格瑞玛而战的吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4993, '很抱歉，普瑞斯托女士。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4996, '当然不是，亲爱的$g小伙子:姑娘;。你这种“冒险者”类型的$c经常成为政治的牺牲品，被政治家玩弄于股掌之间而毫无察觉。$B$B我给你的建议，就是去做一些更加具体的事情：找份新工作。$B$B这个世界已经有太多的英雄了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5015, '反对者？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5017, '真有趣……继续。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5034, '啊……反对者。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5077, '你想去哪里？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5079, '你有需要保管的财宝吗？去找铁炉堡银行的石衣兄弟吧。\n从铁炉堡的入口往东北方向走，银行就在那边。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5083, '想要乘坐狮鹫，是吗？你得去找格莱斯·瑟登。\n你可以在铁炉堡中心的大锻炉东边找到他。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5085, '啊，没有什么比狮鹫更好的坐骑了。暗夜精灵偏爱可笑的角鹰兽，而我只需一头狮鹫就可以穿梭在云端！\n好吧，我不跟你唠叨了，到大锻炉东边的格莱斯·瑟登那儿去吧，他会向你出租狮鹫的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5098, '秘法大厅的法师彬克也许能帮忙解决你的一些魔法需求。\n秘法大厅就在铁炉堡的北部。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5101, '啊，布莱纳·火崖。她能使用魔法。她主管牧师事务。\n你要穿过铁炉堡大门，向北走，前往神秘大厅。她就在那里。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5107, '所有的潜行者都居住在铁炉堡以北的荒弃的洞穴。我敢打赌芬斯维克也在那儿，正在数着偷来的钱包中的硬币呢。我总有一天会抓住他的！\n同时，我也会好好看着你的，$g小伙子:姑娘;。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5116, '你在寻找一个炼金术老师是不是？我也刚从那里回来。你会在侏儒集会的工匠区找到浆泡小姐的。\n：：叹气：：……为什么我没有服下蓝色药剂呢。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5122, '啊，要是你想成为一名附魔师的话，我想你需要找吉布·草须。他在 大熔炉狮鹫管理人右边的商店草须魔法用品店里。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5124, '你想学习工匠的手艺吗？那你就得去工匠区找宾斯匹德。\n从铁炉堡大门一直往正东方向走，或者朝着传来爆炸声的方向走。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5132, '哦，你想学习采摘雏菊是吧？哈哈！我只是开个玩笑，$g小伙子:姑娘;。\n这是个很好的职业，雷纳·石枝会教你的。她在大熔炉南边的 铁炉堡医师协会工作。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5143, '特瑞莎·远山同样碰上了严峻的气候，但是她运用生存技能，以顽强的意志度过危机。\n如果你想找她谈谈，就去铁炉堡以南的军事区吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5147, '追踪？那么你得去拜访丹穆尔·远山。只有他能教你追踪的诀窍。\n出了铁炉堡大门往南走，去军事区找他吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5206, '“牛头人语？”$B$B牛头人德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向南面的道路指了几下。$B$B或许她是在说那里有能跟你进行交谈的德鲁伊？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5209, '“达纳苏斯语？”$B$B暗夜精灵德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向北面的道路指了几下。$B$B或许她是在说那边有能跟你进行交谈的德鲁伊？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5346, '月神的力量支配着你！月神的力量支配着你！\n出发吧！去达纳苏斯东部的月神殿中央大厅找贾德莉亚！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5358, '阿雷贡做的食物很受欢迎。他总是在工匠区忙于制作新的美食。要是有 塞纳里奥绿色烹饪的话，你一定要尝尝。\n如果你不介意的话，我必须先去调查一下接二连三的鹿群失踪事件。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5365, '哦！$g小伙子:姑娘;，当你选择附魔时，你得非常小心。我让自己的杯子附魔，使杯中的水不洒出一滴，但是我也不能喝到里面的水了！这真是个悲剧。\n当你看到格瑞姆比时，必须记得我的叮嘱。他在大熔炉狮鹫管理人右边的商店中。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5373, '我们种植蔬菜。野兔吃我们的蔬菜。狼群以野兔为食。我们捕杀狼群，从它们身上获得肉和兽皮。这就是神奇的生物链，或许你用别的什么词语来描述它。\n去塞纳里奥区找泰龙尼斯吧，我得继续执行自己的职责了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5375, '“一门可以让你度过重重难关的技能。”菲琳萨就是这样描述她的那套本事的。\n如果你相信她所说的，那么就到达纳苏斯北部的塞纳里奥区去吧，她在那里传授她的课程。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5383, '科兰德善于追踪，森林中的任何生物都没法从他手中逃脱。如果你想达到他的一半能耐，最好认真他教学。\n我会解除你费力寻找他的麻烦，为你标识出他的位置，他就在塞纳里奥区。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5481, '附魔体现了毁灭和新生的循环，这正是自然界的基本准则。晨行者附魔师将为你展示这一切。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5512, '你认为达丹加如何？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5573, '不，维埃兰，我不清楚。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5695, '你在附近见过皮塔斯或达丹加吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5707, '那不是我所说的“和平地护卫”。我会想办法绕开这些东西。我们朝南移动，向那块岩石走去。或许我们能从中穿过去并同时避开兽人。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (5996, '壁炉谷？？但是……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6079, '你究竟是怎么进去的？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6111, '我有很多要做的……在瘟疫来之前有很多……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6112, '约翰，亲爱的，你在哪里？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6113, '每个人都是怎么了？我感到……很冷……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6114, '精灵用一种从前没有过的审视感觉看着你。$B$B“我感到一个大负担从我的灵魂中消除。很快我就可以永远平静的休息了。我现在知道这一点，而且我耐心的等待着这一时刻。$B$B谢谢你，陌生人。”') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6161, '关于暗影之皮的章节。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241, '你一定要原谅我，罗拉克斯，我没有“疯狂”地说什么。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6243, '很抱歉，我没有意识到你可以理解我说的话。你在这儿做什么？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6299, '它位于贸易区的西边，就在喷泉的北边。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6309, '有一名优秀的厨师在旧城区的猪与哨声旅店工作。我曾在他身旁看他在烹饪时使用刀具，但是我可不认为他只是一名厨师。别误会我的意思……如果你想学厨艺的话，他会是你最好的老师。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6312, '嗨，提醒我啦，我需要修理一下火箭靴。聪明人一点就通啦，不要把火箭靴和狮鹫混淆的。\n哦，让我为你指明方向……穿过矮人区，你就会找到利廉姆·火轴啦。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6313, '要学急救的话，没有比光明大教堂的安吉拉·雷菲德更好的老师了。\n去找她吧，你只寻找黄色的屋顶或者教堂本身的尖顶就行了，在城中的任何角落都能看到这些标志。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6319, '一个猎人？好的，那么你会想跟矮人区的索尔芬·石盾谈谈。\n哦，你一定要告诉他如果我再次介入他的宠物生意，他就可以去培训那些监牢里的猎人了！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6324, '你知道，我可以刺穿一个兽人或是把一个巨魔切成碎片。我甚至可以把我名字的大写字母刻在食人魔的肚子上，但我就是不能忍受给动物剥皮。想一下都让我觉得恶心。\n好的，如果你有这种兴趣，那就到老城的护体皮甲找马瑞斯·格兰治。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6334, '哦，地铁，地铁……每个人都想乘坐地铁。那些乘坐狮鹫的好时光，那种在高空中飞翔时紧握缰绳的情景，它们到哪儿去了？\n啊！你还是坐地铁去吧……地铁就在侏儒区，那儿还有侏儒的其他精妙设计呢。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6335, '你是问我铁匠在哪儿？你没听说过大熔炉吗？所有最好的铁匠都聚集在那儿铸造武器和护甲！\n在铁炉堡中心都是敲打铁器的声音，你能在那儿找到最出色的铁匠本古斯·深炉。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6337, '哦，你是在找宾斯匹德吧。为什么那个小侏儒和他的装备……让我告诉你吧，如果你想去他在侏儒区的商店，管好你的手，别去抚摸他的机械绵羊！\n爆炸绵羊……为什么你要做这样的事情！？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6343, '呸！邮箱……最近我收到的全都是垃圾邮件！\n增加这个的尺寸……减少那个的尺寸……现在是免费的屠龙剑。我得每隔一个月就要更改邮箱号码才行！\n嗯，你可别说我没警告过你。邮箱就在石火旅店外面。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6344, '嗯！说到学习采矿的话，你来对地方啦，$g小伙子:姑娘;！吉尔弗拉姆·石趾居住在深山珠宝矿业协会。没有比他更好的老师了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6347, '你或许不知道，除了是一个娴熟的裁缝之外，约莫德还是一个巨人杀手！为什么说当他大喊他一拳打死了七个的时候可以断定他一定偷听到我们在一起讲的东西！\n你应该到大熔炉北面他的店铺去拜访他一下，并看看他是否会在跟你讲他的传奇故事！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6349, '一个术士，嗯……好吧，如果你想在附近继续做那种事情，你最好管好你的恶魔，$g小伙子:姑娘;。我不喜欢恶魔，但是我喜欢杀死他们。你明白我的话了吗？\n现在你不要再烦我了，马上消失去荒弃的洞穴。你会在那里找到那个术士，瑟斯哈特。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6350, '克斯塔姆是个大嗓门、爱吹嘘的人……他也是你所能见到的技艺最为纯熟的战士之一！\n我告诉你，如果你想成为一名战士的话，就去找他谈谈吧。他肯定在铁炉堡大门以东的军事区中。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6361, '不随意浪费东西是我们的传统文化。当我们不得不杀死某种生物时，我们会加以利用，不让它白白丧命。\n要是你想学习剥皮的话，就去工匠区找艾拉迪尔吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6368, '又一个想要靠倒买倒卖发家的？拍卖所就在贸易区，离银行不远的地方。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6370, '贸易区拍卖行') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6374, '你敢玷污这片圣地吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6380, '血色十字军不会就此灭亡的！你不会冲破我们的战线的！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6382, '关于多彩龙鳞的信息。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6383, '关于魔光多彩鳞片的信息。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6384, '关于英雄之血的信息。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6392, '在暴风城，有很多地方可供饮水休息，但是只有一处可以过夜。去贸易区的镶金玫瑰吧。我听说客房的费用相当合理，被单也很整洁。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6394, '在暴风城银行和贸易区的镶金玫瑰旅店之间设有邮箱，非常便利。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6529, '我们胜利了！Ash\'ari Crystal 已经修复！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6661, '我感到有些恶心。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6740, '马里恩·考尔和黑暗牧师贝里尔一起在布瑞尔镇东南角恐惧之末旅店楼上的阅览室中。我只是想看看谁是这场对抗的胜利者。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6919, '到闪金镇的狮王之傲旅店去吧。那儿有啤酒和柔软的床铺供你尽情享用，没有比那里更好的休息场所了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6920, '闪金镇的狮王之傲旅店是这个地区中最好的旅店了。在那儿歇一歇吧，旅店老板法雷会让你感受到家的温暖。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6927, '洁塞塔经常帮助镇子里的守卫，她是圣光赐予我们的礼物。如果你想学习牧师技能的话，可以去狮王之傲旅店找她。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6928, '我敢打赌洁塞塔会很乐意教你学习新法术的。她就在狮王之傲旅店的房间内。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6930, '扎尔迪玛可能会教你一些新的法术。他最近喜欢待在狮王之傲旅店，你可以去那里的房间看看他在不在。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6931, '我对魔法知之甚少，但是在狮王之傲有一个名叫扎尔迪玛的法师，他也许能帮助你。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6937, '我打赌科瑞恩·塞尔留斯知道你在寻找什么东西。她通常在狮王之傲旅店里。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6942, '哦……好吧，玛克西米利安是这附近唯一一个了解黑暗魔法的人。你也许可以在狮王之傲旅店那阴暗的地下室里找到他。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6943, '一个术士？好吧，如果我是一个术士，我可能会待在这附近最黑暗的地方……那就是狮王之傲旅店的地下室。你应该先到那里去看看。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6944, '我知道有些人在这附近练习某些专业。你想要打听哪项专业技能的训练师？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6961, '托马斯也许不是最好的厨师，但是他确实能做一些精美的菜肴。如果你想学习厨艺的话，就去狮王之傲旅店找他吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6962, '你为什么不到狮王之傲看看呢？那里的厨师可能会教你几道好菜。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6967, '我最近在这里附近遭遇过一些迪菲亚盗贼，但米歇尔·贝利帮我进行了治疗。到狮王之傲与她商量一下，看看她能否教你。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6968, '米歇尔·贝利对病患的态度令人钦佩！她也许无法教你如何对待病人，但是她可以教你一些急救技巧。她现在居住在狮王之傲旅店。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6970, '李·布朗在水晶湖中抓到过很多奇怪的东西。他说他数月前钓起过一个神秘的面具。但是照实说，我想他那晚一定在狮王之傲喝多了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7000, '你需要找哪个职业的训练师？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7202, '我的腿现在感觉好多了，治疗肯定起作用了。请原谅我，我必须去向我的上级汇报这里发生的事情。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7204, '我刚刚射了一支箭。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7205, '结束我们的痛苦吧！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7206, '你必须救他！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7393, 'Enu thora\'serador。这是一片神圣之地。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7394, '我们会给你看……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7434, '谢谢你的帮助，$n。祝你探险顺利。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7435, '我想呆在这儿，思考一下所见的事情。找到艾瑞拉斯并告诉他我们学到的东西。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7439, '你代表什么，灵魂？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7572, '你不是德鲁伊!') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7644, '我不能训练你，年轻人。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7675, '你向我们发出挑战而我们来了。你所说的大师在哪里？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (7743, '第一次看见亡灵时，我哭了，我无法想象他们的恐惧和孤寂。大地之母在我耳边吟唱，她告诉我：“拯救他们吧。”') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8230, '你能告诉我关于夜刃豹——猎影的情况吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8314, '恕我直言，统帅大人--为什么不消灭他们？难道这不会巩固我们的地位吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8370, '你为何来此，$c?') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8532, '好心的旅店老板艾玛，她现在已经照顾当地的动物好些年了。我敢肯定她会很高兴照顾你给的任何动物。你可以在狮王之傲旅店的外面找到她。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8533, '旅店老板艾玛照料着这周围的所有动物。要是你需要跟她交谈的话，就去狮王之傲旅店外面找她。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8678, '我想重新学习制皮的技能。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8814, '谁控制着雷矛墓地？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8870, '骑兵们，冲锋！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8972, '医生，请告诉我制作符文布绷带的方法。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8973, '医生，请告诉我制作厚符文布绷带的方法。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9142, '这都是我说的闲话。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9143, '这都是我说的闲话。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9210, '我没什么可以教你的了。我听说藏宝海湾有个名叫海明威的老头，他在出售《鲈鱼与你》这本书，它对你提高钓鱼技能大有帮助。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9219, '我没什么可以教你的了。我听说藏宝海湾有个名叫海明威的老头，他在出售《鲈鱼与你》这本书，它对你提高钓鱼技能大有帮助。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9332, '<点头>。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9342, '告诉我关于丹巴达尔的事情。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9343, '告诉我关于霜狼要塞的事情。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9378, '绘制戈多克战争之画！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9379, '陌生人，离开这儿吧，免得送命，它会吃掉它接触到的一切东西的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9380, '精灵，这儿发生了什么事？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9401, '叫我“国王”。你为我带来了什么！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9510, '基尔达斯总是过分夸大。比如，“迦罗娜：潜行与诡计研究”已经被偷过400多次啦。$B$B神殿的标志保护着这本卷轴，防止任何人偷看。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9538, '丰饶之果？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9608, '戴奥，我是来学习的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9610, '我要牺牲什么？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9612, '要怎么召唤恶魔？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9677, '在守护者之周中成为一名孤儿的导师！哈哈！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9678, '在守护者之周中成为一名孤儿的导师！为了部落！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9684, '去银风避难所找珊蒂瑞亚吧。她可以卖给你“中级烹饪教材”。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9685, '烹饪是我一生的追求，我觉得我们俩有共同的爱好！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9686, '加基森的迪尔格·奎克里弗对厨艺非常精通。要想提高自己的能力，你就去找他吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9687, '葬影村的乌兰可以卖给你“中级烹饪教材”。如果你想要提高烹饪技能的话，就需要这本书。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9688, '我可以教你如何烹饪！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9757, '突然之间，你成为了“联盟的保卫者”，是吗？！嗯，我猜你一定是想去勇士大厅。大厅就在旧城区。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9884, '在第三次大战中，肯瑞托的法师和亡灵天灾进行了殊死的战斗。大法师阿鲁高召唤了异世界中的狼人来增强达拉然守备部队的力量。这些狂暴的狼型生物踏平了来犯的亡灵天灾，然后迅速将目标转向达拉然的法师，并开始围攻席瓦莱恩男爵的城堡。这座位于焚木村的城堡不久之后就变成了黑暗势力的聚集地，并从此荒废。因为对于自己罪过的愧疚，阿鲁高将那些狼人当作自己的孩子并隐居在“影牙城堡”中。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (9904, '你已经失去理智了，奈法里奥斯。你在胡言乱语。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10049, '我按照命令把他杀掉，反正他不过是个小偷和骗子而已。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10050, '我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10051, '我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10052, '我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10054, '去死吧，渣滓！联盟会获得胜利的！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10179, '给我饮料！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10477, '战斗将在1分钟后开始。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10478, '战斗将在30秒后开始。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10479, '战斗开始了！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10571, '钓鱼大师巴斯贝特已经在这片水域中放入了美味的可口鱼，钓鱼比赛可以开始啦。\n一旦决出了获胜者，我就会按五条可口鱼换一银币的价格收购其余的可口鱼！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10769, '这个大炮怎么用？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10770, '嗯，很简单的!这东西的使用方法和你以前用过的那些东西没什么两样。别担心，我会负责点火。当你升空之后，你会发现自己正「飘浮」在空中，但是这种情况不会持续很久。你将被发射到湖边的一个目标那里去。只要记得在适当的时候将你的「翅膀」分离，就可以安全地掉入湖中了!不然的话，嗯，我不负责出售人身保险。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10775, '暗月马戏团奖券？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10780, '另外还有一些事情值得注意。我强烈推荐你去塞格那里预测一下你的财富在哪里。我知道，我知道……他是一个豺狼人。但是他是一个拥有特别力量的豺狼人，他可以预知你的财富在哪里！\n另外我们在不断扩展我们的马戏团。最近我们增加了一门大炮，你可以试图用它把自己发射到水晶湖！你可以和马戏团东面的玛克希玛谈谈，了解更多细节！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10782, '另外还有一些事情值得注意。我强烈推荐你去塞格那里预测一下你的财富在哪里。我知道，我知道……他是一个豺狼人。但是他是一个拥有特别力量的豺狼人，他可以预知你的财富在哪里！\n另外我们在不断扩展我们的马戏团。最近我们增加了一门大炮，你可以试图用它把自己发射到水晶湖！你可以和马戏团东面的玛克希玛谈谈，了解更多细节！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10796, '上古的力量被数千年来从未活动过的虫子所震撼。世界在哭泣，$r。也许一次新的灾变正在开始。其中孕育的是痛苦……$B$B那些可恶的家伙开始渗透入我们的土地。噩梦来自于睡眠。噩梦开始在我们醒着的时候纠缠我们……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10831, '千年来，它在地底休眠，苟延残喘，等待时机发动反击。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10840, '泰坦们离开艾泽拉斯世界已经很久了。惟有曾经居住在这片土地上的暗夜精灵还在守卫着他们的家园。天哪！接下来这一段真令人着迷！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10851, '太神奇了，这与卡利姆多的泰坦以安戈洛环形山为家的说法不谋而合。或许阿曼苏尔在亲自守护着这块“神的土地”。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (10955, '你的行为让我们蒙羞，$c。我感到深深的耻辱，所以你死定了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11061, '当心点，凡人。那些强大的生物就是在此地葬生的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11310, '伊兰尼库斯，寻求赦免吧。一切都会得到宽恕的……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11311, '伊兰尼库斯，你的罪行会被赦免的。艾露恩永远爱着你。挣脱禁锢着你的束缚吧！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11312, '上古之神的束缚没有丝毫减弱的迹象。他完全被他们黑暗的思想所控制……我……我不能……不能引导……帮帮我，艾露恩……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11313, '梦境之暴君伊兰尼库斯被月神之光吞噬了。月光林地恢复了往日的宁静。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11317, '姐妹们，照顾那些受伤的士兵！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11350, '你自由了，梅森。坏格林奇再也不能伤害你了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11388, '拿取你的礼物！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11402, '敢耍诈？去死吧！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11415, '你好，$C——我是达纳苏斯的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在达纳苏斯的声望也会因此提高。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11416, '你好，$C——我是诺莫瑞根流亡者的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在诺莫瑞根流亡者中的声望也会因此提高。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11418, '你好，$C——我是暴风城的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在暴风城的声望也会因此提高。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11419, '你好，$C——我是奥格瑞玛的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在奥格瑞玛的声望也会因此提高。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11420, '你好，$C——我是暗矛部族的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在暗矛部族的声望也会因此提高。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11421, '你好，$C——我是雷霆崖的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在雷霆崖的声望也会因此提高。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11422, '你好，$C——我是幽暗城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在幽暗城的声望也会因此提高。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11611, '其拉军队出现了！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11633, '为荣誉而战！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11634, '为了国王！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11635, '为麦格尼而战！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11659, '我，就像我的哥哥一样，以那些尊重祖先的人为荣。对我来说，与欢度春节的人们一起分享我的秘密手艺是极大的快乐。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11899, '我不能教你元素制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11901, '我不能教你部族制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (11939, '%s目睹$n在战斗中丧命后变得狂暴起来！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12030, '在卡拉赞陷落之后，肯瑞托议会派遣了一队法师搜索了整座塔，收集到了所有重要的东西……目的？或许是研究吧。总之不知道是否真的，据说这根法杖被带到了达拉然。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12124, '是，长官！谢谢您，长官！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12227, '当然，$n。你只需要先告诉我你想知道关于哪个声望等级的信息。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12228, '米兰达，你能告诉我，在尊敬声望级别的情况下，你所提供的物品需要多少徽记吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12229, '当然，$n。$B$B在银色黎明组织中拥有尊敬级别声望的冒险者需要上缴40个徽记以获得优秀品质的物品。若想获得更加强大的物品，他们需要上缴150个徽记。$B$B我承认，这个价格即便是对尊敬级别的冒险者来说，也确实有些高了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12231, '米兰达，你能告诉我，在崇敬声望级别的情况下，你所提供的物品需要多少徽记吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12232, '当然，$n。$B$B在银色黎明组织中拥有崇敬级别声望的冒险者需要上缴14个徽记以获得优秀品质的物品。若想获得更加强大的物品，他们需要上缴90个徽记。$B$B这个价格对崇敬级别的冒险者来说，可是说是完全合理的！但最强大的物品仍然是高价的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12234, '米兰达，你能告诉我，在崇拜声望级别的情况下，你所提供的物品需要多少徽记吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12235, '当然，$n。$B$B在银色黎明组织中拥有崇拜级别声望的冒险者需要上缴12个徽记以获得优秀的物品。若想获得更加强大的物品，他们需要上缴54个徽记。$B$B只有在银色黎明眼中被崇拜的人，才能获得最大的折扣。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12236, '当然，$n。$B$B在银色黎明组织中拥有友善级别声望的冒险者需要上缴60个徽记以获得优秀的物品。若想获得更加强大的物品，他们需要上缴220个徽记。$B$B对于那些银色黎明尚不眷顾的冒险者来说，这个价格是非常之高的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12237, '友善。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12238, '尊敬。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
