INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12240, '崇拜。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12251, '我是一个大师级裁缝，奥玛里恩。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12253, '冰川外衣。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12254, '冰川披风。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12255, '冰川手套。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12256, '冰川护腕。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12257, '我是一个大师级制皮师，奥玛里恩。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12259, '寒鳞胸甲。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12260, '寒鳞护手。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12261, '寒鳞护腕。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12262, '北极外套。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12263, '北极手套。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12264, '北极护腕。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12285, '你到底做了什么可怕的事？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (12287, '我还是不理解。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (17907, '独角兽是高贵的生物。 请确保始终善待你的独角兽；很少有什么比愤怒的独角兽更危险的了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (18925, '在证明您的价值和对我们人民的奉献之前，您不能在这里购买任何坐骑。$b\n除非你被认为在高等精灵中是崇高的，否则不要再回来！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (41028, '我敢打赌，你绝不会预料到在这片荒凉的沼泽中会找到新鲜的食材和饮料。你几乎无法受到责备。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (47024, '投资贝壳币可以改变您的生活。 它改变了我的。 我曾经是一个被社会抛弃的人，因为我是混血儿而被社会排斥。 没有人会给我机会证明我的价值。 我作为一名简单的金矿苦工，一直辛苦工作，直到有一天我遇到了马洛斯·卡托斯并成为他的同事。\n\n您也可以通过投资自己的未来来掌控自己的命运。 你准备好了吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (47025, '你好，未来的合作伙伴！ 在奥格瑞玛看到侏儒感到惊讶吗？\n\n好吧，别这样！ 我们都是贝壳币公司的朋友。你看，世界分为两种人。\n\n不，我不是指联盟和部落。 这是人为的划分。 我说的是我们，有远见的企业家，还有可怜无知的老百姓。\n\n你是我们中的一员，对吧？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (51239, '他们夺走了一切。我的朋友们都进了牢房。我们究竟做了什么，才该受到这样的对待？\n\n克朗·塔斯克是想帮人们。我们本要消灭贫穷，让所有人都富起来。\n\n你自己想想，什么样的酋长会反对这种事？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (60316, '咕噜咕噜……叫斯纳尔斯·影爪。 如果你需要杀戮，工作是好的。 浑水公司接受合同去做别人不喜欢做的工作。 你想要杀死一些东西，那么你来对地方了。 拿着一袋金子去问...') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (60473, '我们必须始终对来自外部的危险保持警惕，也要警惕来自内部的威胁。最近，泰达希尔发生了越来越多的国内骚乱，需要我派遣更多的部队进行巡逻，并在整个森林开展调查。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (60701, '你找到了一根看起来很有趣的羽毛。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (60903, '欢迎来到壳牌贸易公司！\n\n我是天才！ 我发明了一种全新的货币，它将席卷艾泽拉斯！ 神奇的贝壳币将永远改变我们交换商品的方式，每一枚贝壳币都是独一无二且不可替代的。\n\n你的运气不佳吗？ 现在是投资贝壳币的时候了！ 观察市场并大赚一笔！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (62994, '这些畜生到处都是。真希望酋长能早点拿个办法出来。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (65025, '\n如果这样发生的话，梦境中诺达希尔的映像将会变得容易受到攻击，而梦境之路也会关闭，困住那些没有天生梦行能力的人。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (65026, '在我给予祝福之前，必须先杀死拉兰尼库斯。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (65027, '伊瑟拉女士，他们正在逼近。 我们必须走了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (65028, '拉拉休斯，我忠实的仆人。 翡翠梦境的命运掌握在你的手中。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (65029, '不好了…') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (65030, '%s中断了施法。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (100002, '这种健康的鞭根植物与费伍德森林中盛行的腐败腐败截然相反。 柔嫩健康的根部会长出美味的块茎，长在植物旁边的地上。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (100402, '“灵魂总是在呼唤，人们只需要倾听就能听到它们。”') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (100403, '叫医生来!') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (100404, '但不适合我！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (100500, '寻找休息的地方，$c？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (249901, '那些地精人呢？！按说他们把金子看得比什么都重才对。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (2947901, '征兆已经很清楚了，旅行者。日月更替之间，大地母亲的双目与泪水仍在庇佑我们的天空。可它们彼此已渐渐远离，正如我们族人。一个手足相争的时代已经来临，那曾让我们血脉相连的血，将洒在我们海岸的蓝草之上。代价沉重，负担更沉。这个未来我们本不必知晓，却终将知晓。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4184502, '＜火焰炽热发光，迸裂着古老的魔法。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4188101, '＜一颗破碎的珍珠躺在祭坛上，表面布满裂痕。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (4190401, '＜火焰不祥地燃烧着。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6210701, '＜这个矮人一言不发地盯着你。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6210801, '你不属于这里。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6210901, '你不属于这里。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6214101, '快来看看我的货物！它们可是我直接从大海彼岸进口来的！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6214201, '这鬼天气热死我了！真想灌下一大杯冰镇琥珀麦酒。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6214301, '我那个没出息的儿子整天做当骑士的白日梦，还整日围着女人转。他要是把这份劲头用在继承我的手艺上该多好……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6214401, '想钓好鱼，最好的办法就是变老。老到不怎么动得了，鱼就不怕你了，哈哈！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6214502, '欢迎来到蜜滴旅店！找个位子坐下，享用北风镇最上等的菜肴吧！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6214602, '你好！住店有什么需要吗？我们还有几张空床，很乐意留你过夜！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6214701, '我健壮的狮鹫能载你去哪里？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215001, '你去向蒂芬王后致过敬了吗？还没有的话，何不买一束我的花，到那边的蒂芬公园献上呢？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215101, '只有最上等的面粉才能做出这些绝妙的点心！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215201, '整个暴风城也找不到比这更好的货色；只有铁炉堡的宗师铁匠才配跟我的武器比一比！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215302, '你找我有什么事？我实在没那个工夫、也没那个兴致去管一个冒险者的鸡毛蒜皮。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215402, '这些叶子总也落不完。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215501, '前路是黑暗的日子，冒险者。北风仅剩的安宁与平静，正随着每一个时辰的流逝而消散。这片土地正在崩坏，可似乎没人在意——领主大人不在意，国王也不在意。收拾这场落到我们头上的惨剧，就只能靠我——靠百姓自己。失踪的人、入侵的迪菲亚、黑石与黑铁、四处横行的豺狼人、整个比尔克哈文镇成了一片废墟。我满手都是问题，却腾不出一只手去抓解决办法。我以你的善念与道义相求：请帮帮北风的百姓。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215601, '你听过埃德林·维拉斯爵士的故事吗？一个普通农民，后来成了暴风城最伟大的骑士之一。他是本地的传奇，没人不知道他的名字和事迹。我希望有朝一日也能像他那样——做一个真正的骑士，走遍世界，追寻冒险，保护无辜的人！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215701, '亨利真是个会讨人喜欢的。他还带我来胖南瓜这儿吃饭呢，尽管他正忙得脚不沾地，要像他父亲那样当个铁匠。我很感激他为我抽出时间；他父亲并不反对我们俩见面，只是更希望亨利多待在锻炉边。$B$B<瑟雷萨轻笑。>$B$B马丁确实已经尽力了，可我怀疑他管不住儿子那副爱冒险的性子。连我都管不住。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215801, '真够乱的。胖南瓜酒馆平时挤满了客人，可自打东边那些入侵者来了之后，我这儿就只剩那边那个闷头闷脑的老家伙，问题问得没完。不管怎么说——欢迎来到胖南瓜！请问是饿了还是渴了？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6215901, '索普先生今天忙得脚不沾地，想喝什么好酒尽管叫我，我给你端过去！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6216201, '该死的下等人！我绝不容忍在我的领地上如此放肆。这场闹剧般的比武大会一结束，我就要立刻对他们施以裁决！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6216302, '国王的荣耀，朋友。走过这些厅堂时请务必守规矩。我们实在经不起更多麻烦了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6216402, '别考验我的耐心，乡巴佬。我可不像我兄弟那么好说话。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6216501, '欢迎来到北风。让你看到它这副凄惨模样，我很抱歉。这些麻烦好像一股脑儿全砸到了我头上。更糟的是，我连足够的士兵都没有，护不住我的子民。百姓或许觉得我和我兄弟都不怎么上心，可事实恰恰相反。然而我剩下用来收拾这场乱局的力量，全都被国王的命令捆住了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6218301, '我们家族侍奉米尔登霍尔家已经好几代了。我们精心照料的马匹体格上乘、速度出众，耐力也配得上这份本事。你要是有钱，我可以教你在北风这边怎么骑马。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6218401, '我和丈夫忙着照看路那头比武用的马，实在脱不开身。它们当中有许多需要特别的照料和饲料，而额外帮手只有乔格一个，这儿常常忙得团团转。不过还是请看看我们这边其他的马；它们是整个王国最上等的坐骑！米尔登霍尔女士的马在首都那些最显赫的骑士与贵族中间都很有名。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6218501, '这可不是我想象中的假期。因为比武大会，格林特家缺人手，这儿又没有别人，眼下清理马厩的只有我一个。老实跟你说……我一个人在这儿一点都不觉得安全。格林特先生让我值最后一班，可外面到处都在传有人被掳走之类的，我宁愿缩在家里不出来！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6218601, '来一盒美味的琥珀釉甜甜圈吧，用的是当地琥珀汁做的！趁还酥脆热乎，赶紧买！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6218701, '别被我旁边这个大嗓门分了神；你需要的是来一杯冰镇饮料，一边补水一边欣赏选手们的运动精神！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6219701, '空气中回荡着怨怼之气。不管是什么惹恼了风之领主，都不是好兆头。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6219801, '祖灵在低语，说有大乱。元素在哭泣，我们看到的就是它结出的果。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6219901, '哦，这不可能发生！我到底做了什么才遭此报应？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6227301, '嗯？你不是卫葛斯——那该死的食尸鬼偏偏在我最需要他的时候跑掉了。卫葛斯，回来，小子！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6227501, '我其实不太适合干这种行伍的活儿，但只要能保住家园，让我做什么都行。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6227601, '北风内部有腐坏的东西。内里的病症，起初哪怕再小，也会很快滋长蔓延。绝不能让这种事发生。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6227701, '狮望岗以前作为商贾大道的一环，守备森严，如今只有我们这些民兵还守在这儿。真让人琢磨贵族们到底在打什么主意。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6227801, '我做了这么多年商人，还没见过这么糟糕的场面。真是丢尽了暴风城的脸。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6227901, '哀悼是所有人共通的事。无论我们年少年长，最终都要为逝者哀悼。不管他们是不是走得太早，这都无关紧要。我们的心就是承受不住那份痛。我从没想过自己会活得比女儿还久——可如今我就在这里，盯着一尊几乎不像她的雕像。$B$B我的蒂芬不是战士，可她心地善良、性情温柔。还有人记得他们那位命短的皇后，会来致意。为此我感激，也知足。我多想再看一眼她的脸，她那傻气的笑容，她那一头金发。$B$B<伊恩格维尔德眼圈红了。>$B$B我本来还能见到她——只要他们肯放我进暴风城。我本可以在孙儿的脸上看到我的蒂芬，那个我天天都想见的孩子。可他们不让我进。那可怜的孩子，孤零零地活在世上，母亲死了，父亲不知所踪。他要是知道我爱他有多深就好了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6228001, '参观教堂时请保持安静，尊重逝者永恒的安息。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6228301, '要做的事太多，时间却太少。拜托，在这里别弄乱东西！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6228501, '注意礼数，排队等候。插队可不会让你更快见到琥珀木领主！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6228601, '哎呀，有访客……！请在这附近保持安静，别打扰这些花……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6228801, '你能感受到这片山谷的精魂吗？绯红的树木、起伏的青翠原野，还有清透如水晶的微风在空气里穿行？只要深吸一口气，我的灵魂就被灵感灌满，哪个缪斯都做不到！我跟你说，整个东部王国再没有第二个像北风这样的地方。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229001, '那个蠢丫头！这已经是第十一场我不得不替她收拾的烂摊子了。她再这么下去，我早晚被这些事愁成个老太婆！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229101, '我又搞砸了。师傅起码得念叨我一个月。谁让我不自量力，自己跑去试那些难的咒语……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229201, '琥珀木爵士是北风卫队的耻辱。他的前任绝不会让北风变成这副破败样子。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229301, '如此残忍。这一定是圣光降下的试炼。越是艰难，我们的信仰越要坚定。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229401, '爸爸怎么去了这么久？他答应给我买比武场那边好吃的甜甜圈呢！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229501, '对东部王国各地的最新出版物感兴趣吗？从侏儒工程学论文到关于人类贵族世家的详尽研究，你一定能找到合自己口味的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229601, '孩子们今天格外活泼，他们最好在课上专心些。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229701, '我本该专心帮阿尔金特修女处理教务，可那座被烧毁的修道院的样子总在我脑子里挥之不去。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229802, '别碰我的战利品，小子！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6229901, '迷路了，亲爱的？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230001, '等我长大了，我要当守卫；保护大家，就像我哥哥一样！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230002, '我记不清当初是谁跟海盗打的了……希望阿尔金特修女没生我的气……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230101, '你知道吗，我爷爷以前是镇长。我很爱他，每个星期三我都跟妈妈去看他！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230102, '打扰一下，你知道他们在那座岛上找到了什么吗？跟那个……呃，叫什么来着？比洛尔？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230201, '上学太无聊了。我宁可跟布里克去练几拳，至少他知道怎么玩！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230202, '别人总笑我记不住暴风城第二任国王的名字。越来越丢人了……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230301, '神父说我该多和教堂里的其他人说话，但我有点害羞……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230302, '上周上课时我打了个小盹，错过了讲谁跟巴罗公爵和暴风城关系密切——你能提醒我吗？我不想让阿尔金特修女失望。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230401, '妈妈躺在这里。爸爸说她现在去了一个更好的地方，可我不懂。最好的地方不就是跟我们在一起吗？我希望她快点回来，好再跟我和约书亚一起玩！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230501, '＜男孩一言不发，表情相当呆滞。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230601, '我的妻子莉娜就长眠在这里。她走得太早了，而我对主上的职责又让我抽不出足够的时间陪伴孩子——埃斯特尔和约书亚。等这片土地恢复常态、和平重归，我就辞去职务，好好尽一个父亲的本分。这是他们最起码该得的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230701, '准备好测试你的箭术了吗？我的箭可是全北风镇最好的。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230801, '这里的酒气和苦难让我觉得自己都被玷污了。暴风城的人就是这样敬奉圣光的吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6230901, '那些可恶的兽人就是一群害虫。他们竟敢那样毁了我家的房子和地？还有我那几个没出息的儿子，怎么就这么窝囊？！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6231001, '为了交足贵族的产量指标，父亲早就被压垮了。家又被这些肮脏的兽人占据，对他而言实在太重了——我看他这回是彻底撑不住了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6231101, '母亲尽力维系着这个家，可在我们失去家园之前，这份亲情就已经在散了。我能做的就是帮着她。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6231201, '出了这种事，我们全家都很悲痛，父母肯定比我们更甚。几百年的家业刚立起来，就这么被人洗劫一空？我几乎无法想象那种痛苦。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6231301, '我丈夫的状态糟透了，孩子们也为我们的处境心神不宁。但我不会再让这种沉闷压着我们。这地方是我们用自己的双手和血汗建起来的，我们就要用这双手把它夺回来！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6236701, '我们从洛克莫丹带着货物来的。带着货从湿地坐船到暴风城，真是件苦差事。幸好矮人区的一个朋友借了这辆吉普赛大车给我，好把货运到琥珀郡。可惜他没告诉我这车破成这样，如今我只能等加尔迪姆把它修好，一边还得提防路上的危险。看来做买卖就是这么起起落落吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6236801, '哎哟！给索姆利当保镖还不够——现在还得兼他的杂役。这混账最好一到琥珀郡就请我喝一杯！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6236901, '<这头可怜的牲口不习惯这里的土地；它大汗淋漓，显得又累又沉重。>') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237001, '我和妹妹刚帮完黑海岸的族人，就遇上了这位云游女祭司。自从搭上前往暴风城的船，我们三人就一直同行。她挺爱冒险的，在我们那场命中注定的相遇之前刚去过阿拉萨拉斯。可惜她跟不上我们的脚力——这也可以理解。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237101, '奥尔加是我见过最有趣的人——跟我那个乏味的双胞胎哥哥完全不同。旅途中遇到她是艾露恩的恩赐。我觉得自己交到了一位一生的朋友。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237201, '唉，圣光在上，这些精灵还有他们那两条长腿！唉，我得站起来活动活动——我是来看那家酒庄的！我得亲眼瞧瞧，究竟是什么让阿拉萨拉斯的那些精灵那么高兴。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237301, '这些信可不会自己送出去！这些守卫最好早点放我去办事，对吧？我答应过我亲爱的妻子蒂娜，要在纪念日之前赶回家。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237401, '要是我能打开这把该死的锁就好了！这简直就是我父亲的作风——唉！他把他的「奥特兰克遗产」藏在这口破箱子里，我的耐心快磨光了。一个老顽固能犟到什么地步，连唯一的传家宝都不肯留给自己的儿子……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237501, '这些书架上几乎没什么值得读的。要是我没把每一本都至少读过两遍，它们本来或许还值得一看……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237601, '我本以为这里是养老最好的去处，可我又一次得不到安宁。你看，我特别容易忧心——一定是因为当年我们只能把自己锁在铁炉堡里，祈祷兽人别来洗劫我们的家。我是个普通的人，这辈子从没举起过武器，我害怕接下来的日子会带来什么。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237701, '新来的吧？希望你别惹麻烦。不然你就得对上我。大家都叫我布里克——我瞧着一副不起眼的样子，可我这脑袋跟黑曜石一样硬。所以除非你的下巴想会会我的额头，我劝你别沾麻烦。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237801, '＜大声打着呼噜。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6237901, '我喜欢坐在椅子上看这座镇子。从前每天都能看见孩子们在落叶堆里玩耍，高高兴兴地围着转。如今这样的安宁被人夺走了。孩子不是失踪，就是被疑神疑鬼的父母关在家里。要是我年轻五岁，我就提上剑，让这一代人看看这种时候该做什么！可我偏偏腿脚不中用，还养了个懒骨头儿子——这会儿多半还在睡。好在圣光给了我几个更争气的女儿。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238001, '我父亲以前常在这小池塘里钓鱼，可他从不把鱼带回家。我想他是为那些鱼感到难过——说到底，它们是在囚禁中被养大的，能游的范围就那么小。我有时想，他决定加入迪菲亚的时候，是不是也这样看待我们的家。嗯，结果他在监狱里得到了跟期望相反的东西。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238101, '我这辈子注定要堆干草，而我哥哥却离家出走，躲在暴风城安全的城墙后面当起了了不起的猎人。我倒想知道他到底在猎什么——老鼠，还是下水道里爬的那些东西？我还真想念那个傻瓜。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238201, '抱歉，比武期间，旅店、酒馆和比武场之外的地方一律停售酒类——琥珀木领主不想让醉汉四处游荡，在这类场合惹出争执。你要是想买我酿的酒，只能改天再来。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238301, 'Anu belore dela\'na。王国之内，气氛日益紧张。人们恐惧、不安、疑虑重重。这些疑虑蒙住了他们的心，也为不信任敞开了大门。在这样的时刻，昔日的英雄能给我们慰藉——不正是他们对世人的信念，为我们族人的兴旺打下了根基？$B$B守护这座祭坛、向那些堪为众人楷模的英雄致敬，是我庄严的职责。无论付出什么代价，我都不会背弃它。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238401, '嘘！小声点！我正躲着布里克呢，你跟一堆树叶说话可帮不上我藏好的忙。快走开，别等他那核桃脑袋想明白！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238601, '守住道路畅通一天比一天难。龙喉兽人眼下或许是被打退了，可他们卷土重来只是时间问题。$B$B我祈祷到时候我们还有力气再把他们打回去。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238801, '什么风把你吹到阴森之地来了？要是来看风景的，那我有个坏消息。你唯一能看到的，就是遍布乡野的龙喉兽人。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6238901, '我的职责就是留意治下的人口，稳稳当当记清我们地界内住着多少人。谁住在这儿、住在哪儿，我都一一登记。$B$B作为丹基塔斯的书记官，我也负责记录并整理针对议会本身的陈情。你要是对丹基塔斯有什么顾虑或建议，告诉我，我可以转呈议会。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239001, '这一带的历史浸透着传统、冲突与繁荣。阴森之地曾是肥沃宜居的土地，许多家族与贵族就住在格瑞姆巴托本身的宏伟厅堂之中！$B$B我们的故事饱经风霜，满是艰辛。我们挺了过来，也学会了应变，去面对那些一再想要毁灭我们的威胁。其中许多威胁早已消失，而我们还在这里——这正是阴森之地矮人意志力的明证。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239103, '或许也是位同行史家？你是来了解伟大的巴戈斯·铁袍的吗？阴森之地那位声名显赫的将军与缔造者？你知道正是巴戈斯亲自筹划了对龙喉第一次入侵的防御吗？$B$B……还是说，你对几年前斯托尔加兹要塞的陷落更感兴趣？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239201, '欢迎，请随意些。丹基萨斯向来以好客闻名！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239301, '我是黑炉看守，负责保管丹基塔斯的档案。记录何人、何时、何地发生了何事，是我的职责。谁要是偷窃、或是说别人坏话，都会由我记下来……$B$B我劝你安分些，你最不想要的就是自己的名字出现在丹基塔斯的档案里。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239401, '你有什么事？没看见我们正忙要紧事吗？我可没工夫应付从境外跑来的多事冒险者。还有更急的事等着处理。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239501, '欢迎来到丹基塔斯，我是地方法官胡尔达姆·硬手。我在此地被选为执政之长，与同僚议员们一同裁定哪些事该做、哪些事不该做。这些决断分量极重，从琐碎小事到要紧大事都涉及。你若有待办的事宜，或有该呈给议会的顾虑，请上楼去找书记官砾冠。他会给你相应的文书，好把任何陈情、顾虑或建议提交到我们下次会议上。$B$B哦，还有，别在意丹德格，他脾气有点急，也不太待见外人的看法。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239601, '要想让我们的人民得到和平，行动就必须果断！兽人在阴森之地盘踞得太久了，是时候把他们赶出去。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239701, '黑暗正悄然渗入阴森之地。我的守军已捉襟见肘，四面受敌。我在指挥巴戈斯之墙的防御时，这片土地本身也开始被鬼魂与杂种占据。我很希望你是来相助的——什么样的援手我们都用得着。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6239901, '有什么我能帮上忙的吗，外乡人？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6240001, '你好，欢迎你，冒险者！我的职责就是把世上最新的消息带给丹基塔斯的市民，并宣告我们伟大议会的意旨。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6240501, '那些该死的……那么多心血，一瞬间就没了$B$B<格罗尔丹还在含糊不清地嘟囔着。>') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6240601, '我们本已快要发掘出某些了不起的奇观。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6240701, '我来这儿是为了发掘古代遗物，结果现在困在这儿，等着探险者协会的消息。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241101, '我早就警告过他们，穴居人迟早是个麻烦，可就是没人愿意听老克格这套疯话。$B$B<克格发出一阵癫狂的大笑。>') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241201, '我大老远从铁炉堡赶来，家族对丹基塔斯这边的一些地方习俗很感兴趣。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241401, '阴森之地是艾泽拉斯资源最丰富的地方之一。我大半辈子都在寻找一种稀有的宝石，我想它也许就埋在这儿这些丘陵底下。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241601, '这世上还有太多谜团等着揭开。不把每一块石头都翻过来，我们决不罢休。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241701, '如果你需要锻造的活儿，可以去找玛格拉……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241801, '如果你需要锻造的活儿，可以去找拉格丹……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6241901, '如果你需要锻造的活儿，可以去找法利格……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6242101, '一个凡人？在这里，在阴森谷？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6242201, '哎呀你好啊，冒险者。我们俩挺像的，都在外头忙着把世界从那些黑暗、邪恶又吓人的东西手里救出来，对吧？也许我是在自作猜测，可你看着就像那种会向需要帮助的人伸手的人。$B$B我得承认，这是种令人敬佩的品质——我们俩都有。我们可真是好人啊。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6242301, '多萨斯出了名的爱唠叨，我只要点头直到他说到重点就行。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6242501, '在这里小心点，我可不容忍任何人惹是生非。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6242601, '这片土地被战火蹂躏，因纷争而虚弱。或许现在正是部落宣示主权的时候。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6242801, '一个强壮的兽人能扭转任何一场战斗的胜负，而一位强大战士的武力足以改写历史。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6242901, '想找块好肉？眼下我只有这些，但包你满意。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6243101, '该死，这活儿做得太糙了。我们的攻城器械又笨又过时，这种投石机的设计还有很大的改进余地。要想在阴森之地站稳脚跟，我们需要好得多的装备和机械，才能支撑起像样的攻势。$B$B他们要是指望我干出点名堂，我就得加班。我看没法再回到老部落那套口诀了——「往问题上再扔几个兽人」。我们的兵力本来就不够。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6243201, '你能感受到这里的力量吗？它飘荡在空气中，等待被人攫取。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6243301, '欢迎你，冒险者。很高兴看到又有一个热血的人远赴边陲来寻荣耀。我是这座基地的指挥官，在这片土地上执行酋长的意志。若真要把这儿变成我们的土地，就必须为眼前的冲突做好准备。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6243401, '我是拉娜格，阿格娜什的顾问。能有人相助总是好事，哪怕是在这样的异乡。$B$B你带来了奥格瑞玛的消息吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6243501, '就算在这种陌生的地方，战士也得有个地方歇脚、恢复力气。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6244302, '＜乳酪巫师茫然地盯着玛姬露，审视着她的一举一动。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6244402, '＜鲍比·乔在树荫下舒服地睡着。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6244502, '＜米丝蒂深深地凝视着你的双眼。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6244602, '＜猴子绕着一堆堆东西飞快地转圈。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6244701, '我是辅祭！格雷厄姆修士说这可是份重大的责任。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6244801, '我和贝蒂在玩捉迷藏。不过她从来赶不上晚饭前来找我。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6244901, '杰瑞米是个大坏蛋。他那个破藏身点我永远也找不到，可他还老要玩这个。我只想玩过家家……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6245501, '对我而言，巴罗不过是父母用来开玩笑吓唬我的一头母马——好让我对暴风城外的凶险有个准备。后来我还照着讲给我孩子听，我丈夫对此很是不以为然。如今我到了这儿，反倒希望那些吓人的故事才是现实。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6245601, '＜这位暗夜精灵用近乎轻蔑的目光打量着你。真是令人心寒的性情。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6245701, '新来的？这地方独一份，就算对我这种见多识广的人来说也一样。机灵点，别放松警惕——你永远不知道下一个转角等着什么！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6245801, '你好！我叫诺普西·斯皮克斯潘，负责归档这次行动期间发生的一切。巴罗的历史十分丰厚，自从第一次大战中暴风城失去它之后，还有许多谜团悬而未决。你要是发现什么文件或类似的记录，尽管拿来给我。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6245901, '<矮人从酒杯里啜了一口。>$B$B啊！跟你说，要是没带上我心爱的雷酒陈酿，我就只能跟诺普西和他那套无聊的研究，或者他别的什么勾当混在一块儿了。这酒给我提劲，没别的东西能比；我能放倒任何一个兽人！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246001, '我来自戴文堡，那是设在暴风城港口的库尔提拉斯使馆。包括我在内的同胞们，正竭力与联盟重修旧好。因此协助军情七处完成这次任务是我的本分。再者，这座岛上肆虐的风暴极为反常，本身就值得一查。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246201, '这么邪门的地方我很少见到。这座岛上处处是死亡与痛苦的气息。最好什么都多做点准备。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246301, '这潮湿的空气对我的宝贝武器来说简直是毒药！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246401, '我们的床也许不算舒适，但足以让你恢复体力。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246501, '这座岛把我的狮鹫都吓着了，我很难让它们安静下来。你要是想飞回暴风城，知道上哪儿找我。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246601, '仆人都跑哪儿去了？我的草莓芭菲已经等了三个多小时。谁要是敢在我的甜点上磨磨蹭蹭，那就是他在我哥哥手下干的最后一天！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246701, '废墟。毁灭。死亡。这座昔日葱郁的岛上，再也找不到别的了。我记得那些青翠的树木与丘陵，记得夹着甜咸味的微风越过山峦，记得阳光温暖地落在皮肤上。这些全都消失了。你能看到的只有悔恨与苦难。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246801, '这些姑娘到底在想什么？在这种只有地精桑拿房里才有的连绵阴雨和湿气里修飞艇？我不知道这算是对我本事的信任，还是她们脑子坏掉了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6246901, '想来块泡软的牛排？还是来点湿透的弹药？保证几乎有一半的时候能管用！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247001, '没错，这地方遍地都是历史，等着人去挖！等我带着惊天发现回去，探险者协会那帮老家伙的表情一定精彩极了！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247101, '这座岛在生病，病灶在里面滋长，急着要破出来。我的萨恩多到底在这鬼地方找什么？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247201, '我和哥哥上次待在暴风城已是许久以前。自从离开洛丹伦，我们就没离开过塞拉摩，所以这次重聚让我又喜又涩。不过我不能让这些影响我在比武中的表现。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247301, '阿勒萨努力装出坚强的样子，可我看得出她撑得很吃力。我们家族出身暴风城，第一次大战后逃到洛丹伦，所以我只能想象她心里翻涌着什么。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247401, '普罗德摩尔女士选了我与远风兄妹作为我们这座港口城的代表。她希望不仅与暴风城、也与其他人类王国增进往来。这目标令人敬佩，我绝不会让她的抱负落空。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247501, '这种时候还要办比武大会，实在让人费解。这些暴风城人到底在想什么？难道他们看不见自家门前的光景吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247601, '我家在激流堡郊外有个不起眼的小农场，可我如今站在了这里。能被选为王国的代表，我深感荣幸；无论如何，我都要让他们以我为傲！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247701, '光是站在这儿我就直打哆嗦。我宁可回激流堡帮我的弟兄们，可外交事务要我参与……这个。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247801, '被迫参加这种白痴比武大会，对任何一个正直的库尔提拉斯人都是耻辱。那些叛徒混账以为这样能成什么事？！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6247901, '请务必原谅马勒维勒的态度。他在第二次大战中失去了许多好友和战友，也亲身经历过其中的种种惨状。我保证会管着他，别让他失礼，也别让他伤到人，这话我给你担保。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248001, '听说海军部为我们库尔提拉斯人参加这场比武争论得很激烈。看来在对暴风城的关系上，他们分歧不小。就暴风城跟部落的外交走向来说，我也不好怪他们这么想。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248101, '这些小年轻太容易小看我这把年纪的人了。等着瞧，我让他们看看达拉尼人的脑子是怎么长的！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248201, '我主人是个热血的人，我很少见到谁像他这样以达拉然为傲！有他参加比武，我们绝不可能输掉比赛！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248301, '你看见那边那个从激流堡来的银发帅哥了吗？他是不是很迷人？$B$B<莫德拉一看到勒德尔指挥官，眼睛就亮了起来。她显然被他的相貌迷住了，一时忘了自己说到哪儿，随即又赶紧镇定下来。>$B$B哦，抱歉。真失礼。我是凯特琳·莫德拉，达拉然六人议会、大法师莫德拉的女儿。你可能已经听说了，母亲正忙着重建我们的伟大城市，所以由我代她前来代表达拉然。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248401, '先是赤脊山，现在又是北风镇？这些兽人难道不知道自己的分寸吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248501, '＜你迎上一道冰冷的目光，清楚地感到自己不受欢迎。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248801, '派我一个人来这儿，我拿不准肖尔大师是信任我的能力，还是在变着法儿罚我。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6248903, '＜这位女子浑身颤抖，痛苦不堪。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6249001, '年轻女子一动不动地躺在地上。她的皮肤摸上去冰凉，生命早已离开这具躯体。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6249202, '这具男尸伤得极重。刺伤和扭曲的四肢让他几乎面目全非。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6249301, '这只鸭子呼吸沉重，左翼似乎受了伤。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6249402, '我在这破地方多待的每一分钟，都让我为自己宝贵的时间感到懊悔！我和随从们从暴风城的宅邸一路赶来，穿过林子里那些可怕的凶险。我的目的是在领主大人那里取得影响力，在北风这片富庶之地挣个半正式的名分。可现在，我那只定制手袋连同纹章戒指都被人偷了——明明我一直贴身带着！一想到有人把那双恶心的手伸到我身上，我就恶心得想吐。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6249802, '＜拉兹贾尔投来充满敌意的目光。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6251301, '我和妻子把全部家当凑到一块儿，想在北风这边安家。早知这里的情况糟成这样就好了。我不怀疑琥珀木领主是个心善的人，可万一他不肯收下我们这点微薄的礼、不让我们在他的城堡里暂住，我真不敢想后果。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6251401, '我们族人中有许多加入了前往阿拉萨拉斯的远征，把那座古老遗存重建了起来。我们不是。我们没法忍受活在过去的阴影里，像拖着鼻涕的孩子求母亲原谅那样抓着不放。对我们来说，前方是一条新路……离我们不得不忍受的那些惨剧越远越好。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6251501, '圣光在上，我的耐心快耗光了。这王国是突然被一群彻头彻尾的蠢货给占了吗？！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6251601, '真是好极了。先是要我们一路穿过这些几乎没人看护的街道，现在还得等着领主接见？我们往北风跑了这么多年，从来没碰上这种事。简直不像话！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6251701, '从来没人来看望主人，你出现在这里已经够让人心烦了。求求你，不管要办什么事，快点办完吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6251802, '＜这头野猪鼾声如雷。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6251901, '你要是觉得这儿可怕——哈！那你进安德麦的贫民窟时才有得受。跟那个鬼地方比，这岛算什么。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6252001, '尤妮为我们困在这儿而自责。她该把力气花在找维里克斯算账、把指南针夺回来上。我更喜欢看她动手办事，而不是闷头生闷气。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6252101, '这本来该是又一次例行的运货，跟以往没什么两样。可不行——那个自以为聪明的地精维里克斯非得改道，说什么「近路」能省下大把燃料。结果这条近路正好从一座被永不停歇的雷暴诅咒的岛上空经过，闪电当即劈中了我们的飞艇，把我们困在这儿！我们已经为活命拼了两星期，士气都开始消磨了。不过你站到我面前，一定是幸运女神对我们这份坚持的奖赏。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6255401, '有肉吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6255601, '我还活着简直是奇迹。这些怪物残忍得无法形容！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6255702, '这似乎是德瑞尔特工的同袍。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6255802, '这似乎是德瑞尔特工的同袍。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6255902, '你面前是一滩绿色的污泥。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6256101, '＜这位女子已奄奄一息。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6256801, '在人迹罕至的路上要多留个心眼。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6256901, '复杂的图纸往往要用复杂的材料。有时候，老老实实用更可靠、更简单的做法，反而能推进得更快。除非你想造的是真正开天辟地的东西，否则别浪费时间把一个小玩意儿设计得过分精巧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6257001, '这座岛上的风暴不合常理，透着一股阴冷的诅咒。它们带来的风毫无生气，雨里写着注定败亡的未来。踏足这片水域时务必当心。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6257101, '这是我最后一次欠内尔特人情。把我跟这群兽人凑一块儿，简直是我这门手艺的浪费！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6257201, '在这儿想睡个够大概只能算奢望，不过能睡多少，我尽量让你睡多少。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6257301, '小奥金若想有朝一日继承父业，还有许多要学。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6257401, '想回格罗姆高营地的话不用担心。我的双足飞龙轻轻松松就能穿过这场风暴。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6258004, '<年轻的贵族懊恼地叹了口气。>$B$B哦，你好啊，善良的平民。守卫居然放你进了琥珀木城堡，真叫人好奇——毕竟北风眼下……就说「岌岌可危」吧。你是塞了钱，还是天生就这么有魅力？唉，既然你都站在这儿了，不如来陪我解闷。约瑟芬姑妈连城墙都不许我上，我一遍遍读着同样几本旧书，快被闷死了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6258301, '你想参加我们在巴罗的行动吗？我那匹忠实的狮鹫钢翼可以送你过去。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6258601, '总有一天，我的肩膀要挑起更重的担子。但今天，我只是个部落之子——为部落而战。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6258701, '暗影议会。暴掠氏族。古尔丹的傀儡——我也曾有过同样的命运。别把我和你们那些被遗忘者盟友混为一谈，也别把我看成一个误入歧途的普通术士。我统御着扭曲虚空最深、最冷的角落。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6258801, '在这座岛上，我感受不到大地母亲的注视。这里的天色始终阴沉，看不见安舍，看不见穆莎，连洛舍也见不到。有邪恶的魔法在作祟，必须以怒火相迎。最初指引我来到这里的，不过是我们的主母要我来表一份善意这样简单的事。$B$B然而，我离安舍的温暖越久，怒火就越是灌满我全身。我对你、对我们眼下的盟友既无爱也无恨，部落之子。但我不会坐视不理。这些浸透了邪能的跳蚤，不能再让这片闹鬼之地失去太阳。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6258901, '听着。倾盆大雨里夹着天空的轰鸣。就像有位雄伟的存在挥舞着长鞭，把云层抽打得俯首帖耳，好让它们的煎熬永无止境——雨也永不停歇。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6259001, '有个问题一直在我脑后作痛：这个世界真的把我忘了吗？我曾经的种种——不论出于选择还是命运——都失去了。$B$B无论我把目光投向何处，都什么也看不见。什么也看不见。这个新部落，我们族人的未来，抛下了我。可我绝不会抛下它。$B$B许多人唱诵我的死，好把过去就此埋葬。可我仍站在这里，准备终结古尔丹留下的那点残喘的苦难。我感到的是责任，却也有嫉妒。是什么让我与格罗玛什·地狱咆哮不同？难道他最后的举动就那么伟大，足以抹去他的过去？$B$B我记得他的名号被当作英雄来歌颂时，我却被人当作老朽打发。或许我这般心思并不体面，但我不会就此湮灭。我的名字终将立在传奇之中——不是靠死，而是靠赎罪。$B$B暗影议会将面对我的氏族、我的先祖，以及我的力量的怒火。$B$Lok-tar ogar！$B$B为了部落！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262001, '快进来吧，可怜虫；咬一口我们专利的「香肠奶酪面包」，你这辈子就再也看不上别的吃食了！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262101, '切罗克斯和我琢磨出了艾泽拉斯前所未见、最具创意的烹饪杰作！这样搭配的口味与口感，从来没人做过。它能把你直接掀个跟头，让你爬着回来再要一份！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262301, '跟你说，风险投资公司那帮蠢货就是会惹麻烦。像我这么个老实本分的地精，在这种条件下还怎么好好偷懒？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262401, '嘿，老兄，我知道你想尽快离开这儿，怪不着你。可你得先掏点钱出来，懂吗？老板给的工钱是不错，可姑娘家总得为自己的将来打算，对吧？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262501, '在滚烫的沙漠里走了一路，想喝点解渴的？那你可来对地方了，$C。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262601, '你闻到了吗？那股刚抽上来的油，浓烈又油腻的味道？啊，睡前狠狠吸上一口，做梦都能做出最离奇的点子。你自己也该试试，老兄！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262701, '在这种沙地里维护机器简直是场噩梦！沙子到处都是，把每个角落缝隙都塞满了这些该死的砂粒。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6262801, '你想要的东西我这儿都有。除了「保证不自燃」这一条。抱歉了，老兄。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6263401, '什么风把你吹到阿祖拉之塔来了？是为求知识，还是为那更宏大的奥术？$B$B不管是哪一样，我想我们都能帮上忙。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6263601, '孤峰才不是苔皮族的首领！从来都不是！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6263701, '别害怕，凡人。我不会加害于你。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6268101, '欢迎来到滑芯石油钻井，小子。拿上你的扳手、油桶和工装裤，地下有大把液体黄金等着我们挖出来！$B$B……当然，得先收拾掉风险投资公司那群蠢货。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6268201, '你要是找老板有事，先跟我谈。她忙得不可开交，任何打扰都可能严重拖累我们的产量。还有，这儿的东西你连碰都别想碰，否则我们就把你扔进火花港的地牢里去。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6268301, '我能囫囵个儿走到这儿简直是奇迹，老兄。跟你说，这片沙漠时时刻刻都想要你的命！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6268401, '<一道冰冷的目光让你脊背发凉。>$B$B你最好趁早滚蛋，老兄。我今天不想弄脏手。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6269701, '生意从前可比现在好，小子。你要是走了一路又饿又没力气，我这儿有整个北风最上等的野味！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6269801, '没有什么比钓鱼这种简单的日子更好了。抛出鱼线，剩下的交给自然。我能想象在另一种人生里，我也许会做些稍微复杂的事……比如用双手雕刻建筑或器物。$B$B<渔夫努德雷瓦顿了一下，然后耸了耸肩。>$B$B算了，别管这些了。有什么我能帮你的吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6269901, '喵。$B$B＜这只猫注视着渔夫的一举一动，期待着有鱼上钩。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6270601, '朋友，要不要看看收藏爱好者圈子里最新鲜的玩意儿？宠物石头正是眼下风靡全艾泽拉斯的宝贝，而你呢，善良的$c，正好来到了源头！我这些独一无二、限量发售的宠物石头，能给你带来好运、令人艳羡的情场生活，还有足以轻松击败任何敢挡你去路的蠢货的力量！怎么样，我勾起你的兴趣了吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6271001, '我以前逃离过黑暗。出于羞耻。出于愧疚。出于厌恶。过去的我沉溺于古尔丹那些卑劣的算计，我们膜拜的暗影迷人而强大。在偶遇那位守望者之后，我做出了选择：要么在自己煎熬中死去、被深渊巨口吞噬，要么直面过去，确保自己不再被它那摧毁性的掌控锁住。$B$B说话吧，陌生人。你愿意帮我成为暴掠氏族的最后一人吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6272701, '自然之美必须受到保护，并不惜一切代价加以维护。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6272901, '哦，风啊，吹过我迷人的鬈发！……迷人的胡须卷。$B$B你飞过吗？那感觉美得很。你要是想体验一回自由落体的优雅，又有只有我这儿才有的保障，那就跟我说一声。这么绝妙的感受，几个铜板就卖你，行吧？！只是落地前记得把伞打开。已经有好几个人因为太心急而摔了个嘴啃泥……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6273001, '厅堂寒冷空旷，毫无生机。只剩下压抑的黑暗。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6273201, '我已经开始想念阿拉萨拉斯了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6273301, '阴森之地或许悦目，但别被它的美景迷惑。这片土地之下盘踞着沉睡的黑暗。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6273401, '塞隆领主交给我们一项极其重要的任务。你若没有要紧的事要报告，我建议你别来打扰我们办事。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6273602, '＜这名俘虏浑身发抖，毫无反应。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6275201, '这片土地已不复往昔。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6275501, '走路小心点，朋友。阴影就潜伏在你的弱点旁，别让它们得逞。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6279501, '我已有些时日没从我们的隧道里出来了，很想再看看月语海岸……$B$B如今这片土地上只剩下支离破碎的盟约与敌意……可我仍旧渴望再看一眼它那独特而美丽的土壤。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6279601, '自然之中少有绝对之事。浅薄之人只当火是毁灭之物，可没有它，这世上的生命便无从繁盛。旅途中牢记这一点，否则你真正的潜能便无从舒展。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6279801, '大地之环在艾泽拉斯各处总是需要协助。你若遇到我们教团的成员，不必犹豫，尽管支持他们——我们正致力于修复大地母亲的平衡。作为回报，我们也不会吝于酬谢你的付出。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6279901, '你若为冥想而来，请去请教其中一位灵魂向导。否则，请不要打扰这片圣地的安宁。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6280101, '新来的学徒很有出息，可同时也天真得厉害。这让我想起自己在莫高雷受训的日子。故土的辽阔平原令人神往、令人敬畏。那时我并不知道大地母亲正受着何种病痛折磨。正因如此，把这些年轻人准备好去面对世界的真相，才更加重要。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6280301, '水总是沿着阻力最小的路流。它善于变通，柔韧而多谋。这听着温和，但只要有足够的时间和压力，那道瀑布会连沿途的一切一并侵蚀掉。永远别忘了这一点。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6280401, '与大地交流。听听它的心跳，庄重而沉稳。大地藏着无数秘密等着被倾听——只要你肯听。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6280501, '暗矛部族曾以古老的巫毒法术窥探我们之外的位面。这门传统我们已经失传大半。虽然我们从兽人那里学到了许多萨满之道，但把本族的学识传给后世，对我而言至关重要。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6283301, '我大半辈子都在这些山径上游荡，在千针石林的荒野里打猎。直到最近，危险才逼近我的土地。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6283401, '风角部族几乎被灭绝，家园被人夺走，我们如今只能流离失所，做难民、做游民。$B$B我回到这熟悉的地方，是为了复仇。可这件事我一个人办不到……你愿意做我怒火的这只手吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6283501, '马尔甘心里积了很深的怨。不管我怎么做，他看来都已打定了主意。我不怪他，我们几乎被夺走了一切。我留在这儿，只是别让他把命也搭进去。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6283601, '我小时候，一伙半人马在我们的商队行进途中杀了我全家。是风角部族救了我，收养了我。我永远欠他们的情，也把风角峡谷当成家。如今得知恐怖图腾盘踞在那里，我心里像烧着一把火。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6283702, '<年迈的牛头人站在你面前，目光枯瘦，带着几分惊讶>$B$B嗯，你显然不是恐怖图腾。你能登上这些峰顶，我得说声佩服——如今占据这里那些人，看着可不怎么欢迎外人。$B$B<斯克伊斯特尔伊德长长地呼出一口气，目光掠过风角峡谷的峭壁，眼里闪着微光>$B$B多美啊，不是吗？我的族人在这片崖壁上游荡了许多代，在石头里凿刻留下痕迹。那样的日子看来已经过去了。我这把老骨头，一年比一年更乏。我能感觉到，我的时辰快到了，就像风角一样，我也终将逝去。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6283801, '大自然赐予我们丰饶，让我们得以置办货物。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6283902, '我们家族世居千针石林。那是我们祖辈的家园，是我们走过不知多少代人的地方。如今我们的生活被彻底掀翻，落得个难民的下场。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6284001, '这片土地美得动人，也一样危险重重。这些日子就算是走大路，你也得时刻提着心。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6284201, '我来自辽阔的千针石林。我们这支被放逐的部族一直在寻找能称之为家的新地方。我们多半把月蹄的兄弟姐妹视作表亲，所以再没有比这儿更适合重建生活的地方了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6284401, '月蹄部族的名字来自古籍，那里面记载着我们的伟大母亲曾与双月同行。守护这片土地、让它保持神圣，是我们的传承。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6284501, '黑风部族该庆幸他们攻占我家乡时我不在场。得知他们闯进来杀害我的亲友时我却在外面打猎，这口气烧得我五脏俱焚。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6284601, '已经很久没有外人踏足月语海岸了。是什么风把你吹到这儿来的？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6284701, '我在风角峡谷的家里听过许多关于我们月蹄表亲的故事。都是些夸大的传说，说他们能在星辰间起舞，沐浴在蓝色之子的丰厚馈赠里。$B$B<塔加沙轻笑了一声>$B$B有意思的是，这些小小的传闻怎么就这么快变成了神话。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285001, 'Okhal-asha，陌生人。我是摩洛盖·克拉，我族的酋长，欢迎你来到我们这座简陋的村子。我们是个爱好和平的民族，多年前逃离了垂死的故乡世界，只为寻一处安身之所。可危险与不安仍困扰着我族人的心——邪恶的势力已开始侵犯，威胁着我们建立新家的梦想。若你对安宁的渴望与我们相同，那么请你相助，帮我和我的人民度过这些新的劫难。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285101, '你好，远方来的流浪者。我们德莱尼敬奉神圣的德拉诺水晶——那是由故乡德拉诺的血脉凝成的纯净晶体。当年我们的部族借古老的裂隙行走之术逃到此处，术法残留的能量渗入了你们这个世界的土地。日久天长，这些原本异乡的晶体便开始自行生成。$B$B随着黑暗在平原上蔓延得越来越快，我们已很难再采到多少珍贵的德拉诺水晶。村子全赖这些宝石——无论灵性上还是魔法上，它们都承载着巨大的力量。你在沿海一带游历时若发现了它们，尽管拿来给我。你若这么做，我会以我们最上等的宝物相酬。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285201, '像你这样的小崽子，根本不知道该怎么在我这把年纪的人面前待着！整天东跑西颠，空脑袋里连个念头都没有，再这么胡闹下去早晚把命送掉！我背上这筐里，莽撞年轻人的骨头已经够多了，不缺你这一副！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285301, '走近些，帕拉什卡。我的货精致无瑕，日常制作要用的东西应有尽有。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285401, '我们的鱼鲜嫩够味，香料放得不多不少。进来尝尝吧，帕拉什卡！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285501, '坠落者日日夜夜围攻我们。帕拉什卡，还望你在村里遵守规矩。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285601, '我在照看这片土地上的鸟，据说它们叫平原陆行鸟。这鸟脾气不小，还常常执拗，可对它们有耐心总有回报。它们的力气和韧性都让我想起故乡世界的那些鸟。我们叫它们「纳拉克拉」，用你们的话说就是「星翔者」。那是种难以捉摸的鸟，羽毛油亮，腿肉厚实，翱翔在德拉诺星光下的天空里。$B$B照料这些平原陆行鸟让我想起家乡；那通常是段痛苦的回忆，对我而言却是难得的一种慰藉。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285701, '我的货件件都是手艺精良的杰作，帕拉什卡。就算是你这样的外人也看得出有多上乘。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285801, '你看着就像是个对稀奇玩意儿有眼光的人。走近点，瞧瞧我这些你从没见过的珍禽异兽！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6285901, '今天湖面很平静，没什么鱼咬钩。怎么样，你自己想试试吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6286001, '我摆出的水果不多，但味道无可挑剔。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6286101, '德莱尼菜是要慢慢习惯的口味，牛头人可受不了我们厨房里那种典型的辣。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6286201, '交易') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6286202, '你好，$C。在这群德莱尼中间看到我，你一定很意外——我是不是显眼得像个肿块。我在世上闯荡多年，学到了不少秘密，最后在这片中了邪的海岸上安下身来。我干的是珠宝加工，师从的是最好的老师。你要是想采买些材料，我非常乐意跟你做笔生意。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6286301, '编织奥术能量需要极高的专注。在它的压力下轻易动摇的人，不是被撕碎，就是被逼疯。我在本族部族的那些天真学徒身上见过无数次。告诉我，你们这种人，承受得住扭曲虚空那种纯粹的能量吗？我好奇得很。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6286401, '德莱尼拥有万古流传的古老制皮技艺，一代代传下来。我们处理兽皮与皮革的精深手法，至今无人能及，哪怕在这个陌生新世界里也一样。你要是对自己的手艺有那份自信，那就让我用我们自己的试炼来考考你。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6289601, 'Ishnu-alah，旅行者。什么风把你吹到这片海岸的月光田野来了？我和同伴们走遍艾泽拉斯，追寻冒险、谜团，偶尔也顺手弄点财宝——至少理查德是这样。就在几个月前，我们在大海彼岸的悲伤沼泽里陷入了一个极其凶险的处境——说「被缠住」一点不夸张。就是在那里，我们结识了那些可敬的德莱尼。你可以想象，我在这儿、在月语海岸又见到他们时有多吃惊。我上次来这里，真可以说是年代久远了……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6289701, '这片土地在低语着神秘的词句。含糊，又蒙着雾。维努里斯把我们带到了这片海岸。那是她族人的故乡，她记忆里的故乡却不是这番模样。这片海岸笼在阴影中，底下沸腾着，急着吞掉粗心的蠢货。走这些路的时候你最好当心。谁知道暗处潜伏着什么。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6289801, '不得不说，这些德莱尼做起辣菜来真有一套。不过没有我们在避风港喝的那锅炖菜辣，大概是加了沼泽草药的缘故。我的同伴们肯定也这么想。除了奥尔格拉——那女人总想压我一头。可正是这点让她招人喜欢，虽然我绝不会当面跟她说。也希望你别去说。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6289901, '鬼魂！当然得是鬼魂。我居然还想过会是别的东西，而不是亡者的灵魂，真是蠢。我发誓，等这边的事一了，我就要理查德连着守三个晚上的夜哨。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290001, '大地在痛苦中呼号。浸透它的这片混乱，是无数觊觎其力量、又毫不顾及后果的势力滋养出来的。我们卡多雷弃守这片海岸，已经太久了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290101, '这支远征队是代表珊蒂斯·羽月指挥官前来的。我们的斥候报告说，沿海一带出了怪事——原本平和的熊怪在林中横冲直撞，本地的德鲁伊团体也断绝了联络。背叛者夷平南迪斯之后，我们对这片海岸的巡查确实松懈了，这点不假。但这里仍是卡多雷的土地，恢复秩序便是警惕的哨兵们的职责——必要时不惜以铁腕为之。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290201, '一位不速之客。我没什么能招待的，不过请让我尽量尽一尽地主之谊。我叫扎拉扎尔·贤风，来自魔法之都、令人敬重的达拉然。我知道这个名号听着有些夸张，可我们的建筑师正大步推进，要把那座伟大的城市恢复往日的荣光。$B$B我和苏里奥是跟着哨兵远征队一起来的。遗憾的是，一牵扯到精通奥术的人，他们就有些戒心。他们允许我同行，却不许我在他们的营地歇脚。要我说，这是有点短视，不过我自保的本事绰绰有余。$B$B那么，有什么我能帮你的吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290301, '海岸始终危机四伏。在外要保持警觉。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290401, '幕天席地也许不太寻常，但这可是个绝好的机会，让你夜里躺着看满天繁星。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290501, '很久以前——甚至在第三次大战之前——我住在南迪斯。从那以后许多事都变了，可有一件事至今让我费解：牛头人那种坚韧。就是很久以前在此定居的那两个部族。说实话，我本以为他们在这儿撑不了这么久，结果被事实打了脸。说来惭愧，我必须承认。如今我明白了，那样的傲慢不适合我。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290601, '跟我们同行的那个人类带着一把很有意思的剑。他也许是个法师，可只要看到那样的美被凝在剑刃的钢里，我就忍不住要赞叹。求你，这事一个字也别跟指挥官提。一牵扯到奥术的使用者，她就很少肯让步——哪怕只是嘴上提到。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290701, '一万两千年前，泰兰达斯岛对艾露恩姐妹会而言曾是一处灵性重地。许多最虔诚、最受敬重的女祭司都在岛上那座高耸的圣殿里完成了宗教修行。$B$B可如今它已成废墟，被姐妹会遗弃。剩下的只有它的秘密、悔恨，以及埋在厚厚阴影之下的谜团。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6290801, '说清楚些。我强壮的角鹰兽能载你去哪里？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6291001, '我们剩下的人不多了。这片林地曾满是与荒野和谐共处的德鲁伊，哪怕泰兰达斯早已被弃置。如今同样是这些德鲁伊，却在向自己的同类开战。究竟是什么把他们逼到了这般疯狂？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6291101, '在月语海岸的林地里，我们都是塞纳留斯的门徒，践行他的教诲，一同研习自然的壮美。无论是暗夜精灵还是牛头人，在玛洛恩之子的指引下，我们本为一体。想到这样的日子即将结束，我心里沉重得很。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6291201, '我哥哥阿查克和我在大陆的月之林有很多朋友。想到他们可能就在那些玷污泰兰达斯废墟的入侵者当中，既令人厌恶，也令人悲伤。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6291301, '可怕的日子来了。光是保住这片圣地不被恶徒侵扰，就要耗尽我们所有力气。你愿意帮我们吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6291401, '班达拉尔正倾尽全力守护每一个人。我们荒野姐妹完全信得过他——第三次大战时，不正是他护住了我们、挡下燃烧军团吗。树妖们会尽全力助他！自然的守护者们会团结一心，坚定地对抗这世间的邪恶。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6291701, '我们的同胞正在偏离正道。他们被艾露恩之子的月光蒙蔽，被一个虚假的预兆引着走。如果我们不尽快干预，恐怕就要永远失去他们了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6292001, '在德莱尼中间，再没有比裂隙行走这门古老技艺更神圣的了。它曾广为流传，如今可悲地只剩下一具空壳——往昔我们这些裂隙行者能施展出的那份壮丽，已随万古之前的岁月散去，那时德拉诺的夜空还能旋舞出星河。看你一脸茫然，我担心你这样的族类根本无法领会这门法术的份量。你不必费神去琢磨那些蠢念头。裂隙行走是神圣的仪式，就算落魄成如今这副样子，也不会被你们这些下等种族玷污。编织奥术之网本身、从神圣的德拉诺水晶中汲取力量——这份力量只该由我们德莱尼拥有，别人都不配。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6292101, '我在照看我们定居的这座岛上生长的植物。自从部族从扭曲虚空之外漂流到这里，这些草木便一天天坏下去。我和长者们推测，它们所苦的根源在于渗进土壤的德拉诺水晶残渣。这是个令人遗憾的后果。我们的到来损害了这片海岸，所以反过来照料它，是我们的义务。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6292201, '守住我们唯一这块农场越来越难了。不是本地的野兽，就是那些该死的仆从给我找麻烦！真想回到从前那些日子——安安静静种我的地，而不是时时把命提在手上。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6292301, '说吧，帕拉什卡。我有要事在身，没空闲扯。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295001, '卡多雷在卡利姆多的森林里生活了无数年，也驯服了那里的无情。这条路并不好走，但若你想见到明晚的月光，在荒野中自给自足、护住自己，至关重要。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295101, '林子里很危险，文明又常常远在天边。我可以教你怎么在严酷的荒野中活下来。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295201, '如果你旅途需要紧要物资，尽管看看我的货物。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295301, '我遇上艾辛是在一场大风雪里，当时我正在高处的山脊上乱走。认定自己快不行了，我缩在一块石头后面想保点暖。没多久我就昏了过去，等醒过来时，这个壮得吓人的姑娘已经把我从藏身处拖到了她的山间小屋。那一刻我就知道：这女人会成为我的妻子，就算要我移开山峦也得办成。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295401, '急着往野外跑，是吧？暖烘烘的炉火和一杯起沫的麦酒固然好，可在山间好好走一遭的畅快是无可替代的。走近些，我讲讲矮人在丹莫罗的严寒里活下来的法子。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295501, '进荒野之前一定要准备周全。别小看周密计划的重要性。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295601, '我们能在杜隆塔尔那要命的高温里活下来，绝不是靠运气。我们族人坚韧，但更重要的是机敏。你该磨炼自己的直觉和本事，否则在外头撑不了多久。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295701, '利用自然为自己所用，方法多得很。只要有点巧思和本事，哪怕最寻常的东西也能变得有用。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295801, '平原的馈赠十分丰厚，足以让我们受用大地母亲的恩泽，又不至于夺去她天生的美。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6295901, '多年来我们走遍卡利姆多的土地，一路被半人马劫掠者追逼。那些年里，我们从这片土地——它的凶险与它的顽固——身上学到了许多。想活下来，就得拼了命去争，因为外头对你没有半分仁慈。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6296301, '日子不好过吧，新手？我跟你说，这岛不是给软弱的人待的。想出人头地，就得往大了闯，也就意味着你得把手里捡到的一切都变成钱。想凑近点、学学我的门道？行啊行啊，不过是有代价的……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6296601, '我还记得自己躲在森林里，躲着那个自称是我母亲的卑劣怪物——那时我还没沦为此般诅咒的奴隶。一躲就是几个钟头，有时甚至好几天。当年练出来的本事我至今还在，那段凄惨日子里的经验，我也可以教给你——当然，得付钱。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6297301, '在双月的光辉下垂钓，说不定哪天就能钓上传闻中的白鳞鳗。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6297501, '歇息吧，疲惫的灵魂——你被冒险压着，必要时肩上还扛得起山峦的重量。让我旅店里点的熏香填满你的鼻腔，舒缓你僵硬紧绷的身体。让每一块肌肉都松开，让每一根骨头都舒坦得咔哒作响。歇息吧。明天又是新的一天。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6297601, '月语海岸上盘踞着好几个鬼魂，年轻人。我们有些先祖确实受到了惊扰，可这些饥饿、冰冷、满怀恨意的鬼魂，是精灵的魂灵。我感谢大地母亲取走了我的双眼——若非如此，我就不得不望着夜空，把视线从穆莎身上移开，正如她把视线从我们对援助的渴求上移开一样。她为何容许这些邪恶的鬼魂折磨我们，我不知道，因为她选择不作答。$B$B所幸，我倚靠的不止她一个。当苍白者把光移开时，蓝色者便越靠越近。你在我们的土地上遇到麻烦时，就抬头在天上找洛舍，年轻人。别人不肯听的时候，他会听。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6297701, '部族正处于极大的危难之中，可我父亲却视而不见。他变得固执，甚至可以说是执迷。他眼里只有安舍。他只看天上——不管是白日里光芒灼人的时候，还是夜里光芒透过穆莎洒下的时候。他信念太深，根本听不进道理。族人，我们的族人，那些离开村子的人，是因为恐惧和被忽视才走的。$B$B说自家亲人的不是，让我心里难受。大地母亲护着我吧，我再也做不到只是站在一旁看着。我不会为了一尊缺席神像的争执，让亲族的血白流。$B$B你在这儿算是外人，所以我求你，别只听我这一肚子怨气。在我需要的时候做我的朋友，这份情我永不会忘。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6297801, '走近些，冒险者。月蹄村的货物独一无二、品质无瑕。你心里想要的，这儿都有；还有更多！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6298001, '大地之环是来调查本地元素为何躁动不安的。它们在这儿实在太不安分了。赞美罗阿，这好歹能让我暂时离沙子和尘土远一些。身为沙地巨魔，自从我们的沙月村加入部落，逃离塔纳利斯就是我最大的愿望。你想不到我到杜隆塔尔时有多意外——不过是把沙子换成了灰土。连大地之环都把法阵设在石爪山。等这一切结束，我甚至可能会求月蹄部族让我留下来。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6298101, '别听那个蠢乌兹图克胡说。他偏爱风元素。哼。一个从前只会在沙子里瑟瑟发抖的软蛋。可真打起来他倒挺能扛，哪怕躲在暗影里也一样。他也许是我加入大地之环以来最好的同伴了——当然，泥偶除外。$B$B看好了，这才是真正的元素。它一动，大地就颤；它走过，岩石就碎。这正是兽人所求的力量与荣耀的化身。再没有哪种元素比你脚下的大地更坚实、更美丽。$B$B<洛特卡清了清嗓子。>$B$B我可能说得有些忘形了。你什么都没看见。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6298301, '这一带有人目击到几块古怪的水晶。一个月蹄部族的人把消息报到了雷霆崖，而皇家药剂师学会似乎对此颇感兴趣。研究这活就落到了我头上——说实话，这大概是能想出的最糟糕的主意。我不是打仗的料。我这辈子从没握过武器。虽说我有的是时间研究这些水晶，可我怕它们在我被练成一个像样的战士之前早就化成灰了。$B$B你看着像是爱冒险的那种人。何不来帮帮我？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6298401, '我还能闻到河角村飘来的烟味。它滞留在空气里，让我想起那场可怕的惨剧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6298601, '欢迎你来到摩洛盖村。我叫阿里亚，是酋长摩洛盖·克拉之子。我们这里少有来客，尤其在这样动荡的时局下；不过你尽可以把这儿当成自己的家。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6298701, '＜这名德莱尼人遭到殴打，一动不动地躺在地上。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6299301, '这世界满是奇景与惊喜。刚发现一件有趣的东西，转角又冒出一件！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6301601, '玛瓦吉尼和格拉姆为灵魂向导托尼兹说的那番关于大地本质的话，争了一上午。可听他们满嘴胡扯，我怀疑他们压根没听进去人家说了什么。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6301701, '格拉姆是个蠢货。大地是力量之元素！有了它，碾碎敌人易如反掌。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6301801, '玛瓦吉尼没那个本事成为真正的萨满。他以为大地元素是用来击溃敌人的，可它真正的用途是守护弱者。这谁都知道。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6301901, '岩鬃大师交给我解读这些石板的任务。它们属于古老的牛头人遗存，那时大地之环还很年轻。当年教团里的自然学者说的是卡利麦格语，也就是元素的语言。如今关于这门语言的知识早已失传，要把它译成兽人语得花上相当长的时间。但不管要多久，我都决心完成岩鬃大师的托付。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6302101, '学徒必须自己动手准备食物。这能磨炼自律，也让人懂得留意自己的饮食。强健的心智需要强健的体魄，而没有强健的心智，就无从与元素交流。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6304401, '坠落者围着摩洛盖村，像秃鹫盘旋在一头将死的牲口上方。想想他们当中有些人曾经是我们的朋友……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6304501, '我兄弟埃卡加尔跟着布罗比长者一起陷入了妄想。他一向容易轻信，可没想到他会这么轻易就抛下我们所有人……父亲要是还在，一定会深感羞耻。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6304601, '沿海一带打猎越来越难了。如今坠落者四处游荡，真正能狩猎的机会少之又少。可托鲁那个傻瓜偏要出去……那小子身上莽撞和天分一样多，说实话，带他真是件头疼事。我不知道纳尔兰是怎么做到的。对付年轻的托鲁，他好像天生就有一套。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6304701, '坠落者要为他们的亵渎之举付出代价。我绝不会袖手旁观，任由他们踏平摩洛盖村！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6304801, '我们驯服了几只这种大鸟，它们雄壮又令人敬畏，能驮很重的东西。可它们脾气倔，不肯让我们德莱尼骑上去。也许你运气好一些？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6304901, '妈妈说我们该先在旅店里躲着，可我更想跟阿里亚在外面玩。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6305401, '想不到月蹄酋长把我打发了，却肯接见那些愚蠢的风角。主母一定会大为不悦。好在不是所有耳朵都对我们的话充耳不闻。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6305601, '日子一天天过去，我越发想念弟弟。我选了挥舞锤子、为部族锻造的路，他走的是另一条。他离家去了血蹄村，要在那里成为一位伟大的战士。尽管想念他，我也盼着有一天他回来——一个目标得偿的男人。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6305701, '警报：有挑战者接近。$B$B处理中。$B$B已确认目标无害。继续执行。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6305901, '又一个外来人。来吧，到我屋檐下歇歇。希望你不介意有人作伴。这个地精和他那位古怪的同伴被拒之门外，他们也需要休息。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6306001, '我从火花港一路赶来，想给这个部族帮点忙，可他们就是不许我进村。幸好这位长者让我在他的小屋里歇脚。也许他是可怜我，毕竟他自己也觉得在这些族人中间像个外人。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6306901, '我的工具既实用又耐用！来见识一下德莱尼的工艺吧！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6307001, '这可不太像我想象中的退休之旅结局……') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6307101, '沼泽从不留情。一步失足、一根断枝，甚至沼泽的瘴气，都足以让身经百战的战士跪倒在地。你要是肯听、也肯付钱，我可以教更高级的生存技巧——说不定哪天能救你一命。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6307201, '凄凉之地的其他地方，原本也像你在尼耶尔前哨站看到的这片绿意。可到最后，土壤里的生机被抽干，只剩下荒芜的死寂。你要是肯听、也肯付钱，我可以教你更高级的生存技巧——说不定哪天能救你一命。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6307501, '小精灵在树间飘荡，洒下一串美妙的旋律，在森林里回荡。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6307601, '这匹雄壮的角鹰兽根本不理你。你连让它斜眼一瞧的资格都没有。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6307701, '耐普图隆领主正派我们作为使者前往你们的世界，压制火元素的日益猖狂。凡人，这警告你也该听进去；他的智慧既不会出错，也无穷无尽。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6307801, '<克拉尔特看着你，似乎来了兴致>$B$B外来者，我是克拉尔特，曾是木喉的一员，如今不幸是仍走在月语海岸上的最后一个同族。黑根让我们的人陷入疯狂之后，他们便弃守了这里。$B$B那已经是很久以前的事了，我习惯独来独往。你要是路过，尽可来坐坐。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6308301, '哎呀，你好啊，年轻人。我是星行者长者，负责照看我们最神圣的仪式与典礼，也受托守护我们的传统。$B$B已经有许多人迁居到这里，只为等待「蓝色之子」归来的庆典。据说蓝色之子的回归，将为我们部族引以为傲的历史揭开新的篇章。$B$B无论蓝色之子的归来意味着什么，这都是一个特别的时刻——值得庆祝，也值得以仪式向我们祖先致敬。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6308401, '自然本身的力量是一种令人振奋的伟力。在这样的黑暗时期，照看自然、弥合邪恶留下的伤痕，正是德鲁伊的责任。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6308601, '我敢说夜空中每过一天就会多出一颗新星。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6308701, '啊，又有一只羊要来加入我们的羊群了？为了即将到来的庆典，许多人已经聚集到这里，还有不少人是为了躲避门口那些恶狼而来寻个庇护。$B$B看来「蓝色之子」的归来，来得正是时候。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6309401, '看好了，我是布尔罗克，云蹄的一员。$B$B<布尔罗克注视着你，仿佛这个名字本该赢得敬意>$B$B哼，你竟没听过这个名字？你跟其他人一样，无知，对我们的历史视而不见。我的部族在很久以前曾掌控千针石林，对牛头人也颇有影响。$B$B<布尔罗克傲慢地嗤了一声，为这番冒犯抬起了下巴。>') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6309501, '愿大地母亲善待你，并看顾你前行的路。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6309601, '静下心来，年轻人。让各部族重归和睦、在这世间的邪恶中寻得正道，是我们的职责。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6309701, '我们必须做黑暗中的光，为找不到救赎之路的人指路。维系牛头人的团结，正是我们这些虔诚牧师的责任。$B$B这世上有许多凶险，投向黑暗的堕落往往来自最意想不到的地方。许多人指望我们指引方向，我们就得把他们引上那条熟悉的、我们先祖走过的路。$B$B灵性与传统，一对手挽手，紧紧相连。少了其一我们便无法存续，正如我们彼此之间也无法分离。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6309801, '你是来寻求指引、寻求智慧的？这些东西要在内省与认清自我中找到。你会惊讶于自己心底埋着多少坚韧与勇气。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6310601, '纳迦悄悄爬上陆地，四处扩张势力。他们的图谋一定阴险，我能感觉到。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6311801, '我受命保卫月蹄村，抵御那些逼近我们边境的威胁。可最近看来，我倒成了个维持和睦的保姆。$B$B已经出过几场争执，都得我去调解，所以请别再火上浇油了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6311901, '真是场灾难——我那个蠢表亲把我派到这儿来。那么多能去的地方，偏偏是这个——这么远，这么古怪。$B$B这片土地确实奇怪，但别把我的不悦当成软弱。我大老远跑来不是为了失败。不管前面有什么考验，我都会扛过去，把任务办成。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6312001, '我就是伟大的皮桑！$B$B在盟友口中，我远近闻名，人称「正义者」；在敌人嘴里，我是「复仇者」！我曾在山巅与巨龙搏斗，从高耸而险峻的塔楼里救出少女，斩杀的恶徒多到数不清！$B$B我曾面对可怕的多头蛇特里奥克，活下来把这段经历讲给人听；我深入过玛拉顿最幽暗的深处，把潜伏在剃刀高地里的恶人绳之以法！$B$B我的事迹传遍四方，每个酒馆和厅堂里的吟游诗人都在唱！$B$B然而……咳咳……尽管有这般荣耀，我还是得问一句——你有没有碰巧在哪儿见过我的剑？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6312101, '啊……在这么不友善的地方还能见到一张友善的脸。$B$B<泰萨妮娅笑了，笑意边缘却卷起一抹阴影。>$B$B你当真千里迢迢赶来，是为了协助我们那桩……事业？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6312201, '别信沼泽里潜伏的那些……东西。它们在雾中窥视，耐心而无声。$B$B它们只在你放松警惕时才动手。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6312501, '替我哥哥道歉……他还没能接受……这件事。饥饿啃噬着他，也啃噬着我们许多人。其实我们到这儿来正是为此。在阿拉萨拉斯，许多人相信这些水晶——对，就是那些水晶——或许能扭转枯萎，或许还能救我们所有人。$B$B<卡利昂歇斯底里地笑了起来>$B$B一个字都别信。他们不在乎像我们这样的枯萎同族。他们给的只是一线希望，刚好够让我们继续往前爬。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6312601, '怎么？没见过枯瘦者？哈……再盯着看，你会后悔的。$B$B快滚开——趁饥饿还没吞掉我，趁我还没决定拿你来当下一个补品。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6312701, '我从未感受过这样的魔法，如此陌生，却又如此强大。连空气都在为它嗡鸣。还有这些水晶……它们绝非寻常玩物。$B$B我不禁要想——它们会不会正是拯救我们族人的关键？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6316301, '我们的先祖受到了惊扰。这片墓地已经不再是能安心悼念逝者的地方了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6316801, '小心，霜鬃族似乎在侵入我们的边境，试探我们的耐心。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6317101, '德莱尼的历史被刻在石板上，把它们永远铸入时间的编年。我们的家园德拉诺毁灭后，许多故事与传说都失传了，所以把族人的历史刻录在这些石板上，对我而言就更加要紧。这副担子，我扛得无比自豪。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6317401, '月蹄部族曾在这片海岸举行神圣的狩猎。科多兽的皮用来制作典礼用的鼓，肉则能供我们果腹多日。可如今这些外来的寄生虫肆意横行，我们的传统再也维持不下去了。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6317501, '我很担忧，$C。幼血们是在动荡与不安中长大的。我们曾在这座简陋的村子里和睦相处了许多个月，不惹事、也多半不与人来往。可看着墙外游荡的危险，看着它们以如此惊人的速度蔓延整片海岸，我为部族的存续感到害怕。这样的命运，我们该怎么理解？大地母亲一定是在考验我们的意志，一定是。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6317601, '我从恶齿村一路赶来，那地方在遥远的东方，辛特兰深处。像你这样爱聊的冒险者告诉我，这片湛蓝的海岸上，鱼既漂亮又肥美。我自然急着向族人证明，伟大的格乌贾比什么鱼都能钓到——不管是在家乡，还是在天涯海角。等我回去，他们准会为我写歌！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6317701, '＜这名守卫痛苦地哼了一声。＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6317901, '朝圣之旅让你疲惫了吗？来歇一歇，让你的心神与自然合一。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6318001, '我和敏法在玩「塔哈姆·图拉」！你要一起来吗？这是我最爱玩的游戏，你只要拿上这张小网，尽量多捞些小鱼就行！想赢就得特别有耐心、还得沉得住气。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6318101, '泰瑞姆·卡兰给塔哈姆·图拉编了网，可我觉得他在使坏——他给自己编的网比我的结实多了！这不是很过分吗？') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6318301, '在这片海岸游荡的鬼魂，并没意识到自己已是不死之身。在他们破碎的头脑里，他们仍在侍奉艾萨拉女王，就像一万两千年前那样。听着像悲惨的命运，其实更像个麻烦——至少对我来说是。你想象不到他们有多烦人，日复一日讲着同样的事。能把人逼疯。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6318901, '哎，走路看着点。我见过不止一个脚步沉重的矮人撞翻补给箱，我可不需要你也来这么一出。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6319001, '哎哎，我们之间没必要敌对。保持冷静和平吧。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6319801, '洛卡塔尔。洒龙血的好日子，不是吗？你看上去有些犹豫、也不怎么起劲。别担心。我虽出身龙喉，但我打着部落的旗号，隶属裂鳞战团。捣乱与混乱也许看着像是我们的本性，可我告诉你，流浪者：到了该动手的时候，我们正是那些向艾泽拉斯更强的居者举起武器的人。') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (6320602, '卑鄙的联盟矮人已经侵入了我们在荆棘峡谷的圣地！快来参军，把这些害虫从大地母亲的土地上赶出去！') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc4`) VALUES (8016301, '＜看来狮鹫心里有事……＞') ON DUPLICATE KEY UPDATE `female_text_loc4` = VALUES(`female_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (84, '再来满饮一杯！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (85, '欢迎来到狮王之傲旅店。您会在这里找到家的感觉！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (86, '事情太多，时间太少！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (87, '我要找的关于暗夜精灵习俗的书在哪里……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (88, '哦，我的天啊！看看这一堆书！是谁把这些书没归类就胡乱地放回书架上的？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (89, '夜色镇的居民们，拿起你们的武器！一只亡灵憎恶正沿着大道走过来，妄图进犯我们的家园！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90, '那个憎恶已经毁灭了我们守夜人的营地！快点，我们必须在它到达城镇之前阻止它！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (98, '你们已经毁掉了自己的土地，别想再毁掉我的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (235, '哈！只要你一进入我的射程，包你马上粉身碎骨！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (239, '啊哈哈哈哈哈！我用枪指着他们鼻子的时候，那些家伙脸上的表情别提有多搞笑了！他们的锯子甚至都没能碰到我！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (248, '哈哈！看看这些在战斗中留下的伤痕！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (249, '没有什么声音能比双缸蒸汽坦克开动时的动静更大了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (384, '什么？有人说到麦酒了？没有托瑞恩在场，哪能喝得爽快！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (463, '去死吧，$n！只有死亡才是你的归宿。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (464, '这个没用$R到底是谁？愚蠢的入侵者。去死吧，蠢货！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (465, '愚蠢的$R！黑石氏族会在你的坟墓上跳舞！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (466, '愚蠢的$C！你根本无法与我对抗！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (528, '做好准备，我们马上就要对那些自称为被遗忘者的家伙发动一次进攻。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (529, '准备作战吧，我的孩子们。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (530, '我们是他的意志的实施者，我们会把他的敌人送入坟墓！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (531, '这些亡灵垃圾会和他们那死掉的精灵女王一起被毁灭！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (532, '我们要把敌人驱赶出银松森林，把战火烧到他们的首都！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (533, '为了巫妖王的荣耀而战！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (549, '让一让！让一让！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (551, '%s从第一台投石车跳到第二台上！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (583, '这并不是你生命的结束，而是新的开始。现在是由你来决定自己命运的时候了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (608, '不惜一切代价，保护工头邦德斯！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (609, '卫兵！卫兵！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (928, '这里没有那块神秘的化石……啊，但是有《荆棘谷的青山》的手抄本。多好的一本书啊！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (929, '我敢和你打赌，我把那个东西留在帐篷里了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1193, '在蓝色隐士有免费的饮料！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1194, '到蓝色隐士去，那里每个人都知道你的名字！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1195, '暴风城最好的饮料！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1196, '过来喝杯啤酒，享受一下这里的欢乐气氛！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1197, '繁重的魔法研究让你身心疲惫吗？到蓝色隐士放松一下！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1198, '到蓝色隐士来吧，暴风城唯一一个魔法和精神完美结合的地方！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1199, '感到忧郁了？来蓝色隐士放松一下吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1209, '%s饿了……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1255, '在唤醒仪式开始前我必须做好必要的准备。你要保护我！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1256, '这些洞穴曾经是一座神殿，是贫瘠之地万物生长的保证。现在那里简直就是个地狱。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1257, '过来，我们一定要继续下去。在我们把纳拉雷克斯从噩梦中拯救出来之前还有很多事情要做。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1258, '我必须在这个火焰法阵中使用法术来驱逐那些德鲁伊的灵魂。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1461, '%s吟唱道：“尽你所能地帮助他，这项任务绝不能失败。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1462, '%s被碾成了灰。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1463, '%s贪婪地呼吸着，空气中飘来新鲜的狮子肉香……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1464, '%s狼吞虎咽地吃着肉！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1465, '%s消失在茫茫大雪中。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1466, '新鲜的肉被放在尤基尔之焰上面。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1467, '%s四处查看……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1648, '去树荫旅店，然后沿着足迹追踪。看看它们是到哪里去的，然后回来向我报告。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1649, '明白。我马上就回来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1650, '%s消失在薄雾中。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1707, '和我们讲讲你对树荫旅店的事情有什么了解，放心，我不会打你的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1753, '泰索兰！我需要一些人，最好是法格兰·哈斯迪尔，到树荫旅店附近去调查一下$n发现的那些蹄印。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1754, '马上就去，长官。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2431, '尖端机器人都很敏感，刚才您说的那些话有些刺耳:( 请对我好点。\n我只是想要帮忙。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2433, '人们都认为我喜欢玉米热狗，但实际上玉米热狗让我消化不良！！！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2463, '看看，风险投资公司的新伐木机比我的要好多啦，从可拆换的机械臂到控制把手，都是那么棒！我的老板给我下了死命令，但我们却拿不出任何东西。$b$b现在我们自己的设计研制工作已经完全停止了，所以我决定向他们“借”一个。我派维兹克兰克去淤泥沼泽偷一个回来，但他到现在还没音讯！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2660, '纳拉雷克斯又陷入了沉睡！$b$b很久以前，纳拉雷克斯曾满怀着进入翡翠梦境、让贫瘠之地重新变成茂密森林的伟大理想而来到了这处洞穴中。但他的执着却逐渐消退了，而他的思想也被脑海蜿蜒的影象所侵染。$b$b现在，那些奇怪的爬虫正从他的梦境中爬到这片土地上来，我们必须把他从梦魇中唤醒过来，否则他就将永远失落于其中，并继续给这片大地带来邪恶的力量！$b$b不过，只有杀死他那些堕落的仆人——毒牙之王，我才能开始进行唤醒仪式。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2702, '机器转过来面对着你。$B$B它的背后有一个奇怪的凹槽，上面刻着一行字：“基尔卡克·旋杆的财产”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2703, '转动钥匙，启动了机器。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2705, '我是“勇敢的”约翰森，这是我默认见面打招呼的话。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2750, '暴风城银行坐落在贸易区，就在城门的西北面。来，让我在地图上指给你看。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2844, '我的陆行鸟需要接受训练。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2878, '狮鹫？你是要使用空中旅行服务吧，到贸易区的城墙上去找到杜加尔·朗德瑞克就可以了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2880, '你想要成立一个公会，对吗？祝你好运！\n和暴风城接待中心的奥德文·拉弗林谈谈吧。你从英雄谷进入贸易区之后就可以看到暴风城接待中心了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2912, '想要接受训练？我可以把你训练成暴风城最好的战士，但是守卫是不能这么做的。我想你得去兵营或者猪和哨声旅店，找些合适的人来对你进行训练。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2913, '去兵营或者猪和哨声旅店逛逛吧。如果你去旅店的话，别忘了尝尝那里的好酒，那些酒绝对能让矮人的酒相形见拙。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2927, '什么？我不认为暴风城里有术士训练师。\n不过……在法师区的那家名叫“已宰的羔羊”的旅店中有一些与恶魔有关的活动，我想你应该去那里看看。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2953, '如果你要学习炼金术，暴风城只有一个地方值得你去……那就是炼金材料店。你可以沿着法师区的外围找到这家店铺。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2954, '你应该去找瑟鲁姆·深炉谈谈，他是我见过的最好的矮人铁匠。你可以在矮人区的中心地带找到他。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2955, '如果你想要成为一名好厨师，那就去旧城区的猪和哨声旅店，找斯蒂芬·雷百克谈谈。那家伙知道怎样才能做出与众不同的肋排大餐来。\n啊……说到他那著名的肋骨大餐，我都感到有些饿了。你可不要指望他会把那道菜的做法传授给你！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2959, '你想要学习制皮？西蒙·坦纳尔可以教你。你可以在旧城区的“护体皮甲”店里找到他。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2960, '不知道你为什么要学习这样的技巧？只有不诚实的家伙才会去学习如何开锁。\n如果你真的想要学习这种伎俩，那最好到旧城区那边去，可能就在那些小巷里面。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2980, '塞尤娜，你好。我要需要接受训练。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2981, '我知道你在那里，潜行者。离开我的家，不然你就惨了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2982, '世界末日就要降临了！让大地吞噬我们的血肉吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2983, '我们活着只是为了效忠上古之神。去死吧，入侵者！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3001, '邪恶！到处都是邪恶的气息！这片森林必须得到清理！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3002, '我感到绝望。杀死一个，还会出现更多。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3003, '如果我们要成为这块新地区的主人，那么我们就必须要找个地方好好休息。把你的斧子放在火边，让大家分享你英勇战斗的故事吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3008, '生存技能是一项很有用的技能。\n去找凯尔布鲁斯吧，他在花园区的月亮井附近。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3009, '没有什么能比在水晶湖钓一天的鱼更惬意的事情了。阿诺德·利兰教我学会了钓鱼。你可以在运河区的码头找到他。\n哦，不要相信他告诉你的任何关于运河里有怪物之类的故事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3010, '鲁坎·考迪尔在监狱附近的运河边上有一家小店。我相信他可以教你附魔的技巧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3011, '我独自走在路上，为了捍卫荣誉和清除这片大陆上的敌人而战。$B$B我能为你做什么，$n？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3012, '*机械打手4100型做好了跟随你的准备*') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3013, '你能告诉我布瑞恩在哪里吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3167, '嗯……大量的化学变化……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3178, '以上这些内容是用来帮助你理解创世者的动机。他们创造出土灵这样一个物种是为了在他们离开之后，土灵可以成为这个世界中的一个重要部分，并保障创世者在艾泽拉斯世界的宏大计划得以继续实施。$B$B创世者对于“土灵”这个名字十分满意，因为它很好地体现了这个种族的基本特性。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3181, '当土灵的合成母体不稳定的时候，产生了两个变种。一号教程图像正在初始化。$B$B第一类变种被称为“穴居人”。这个变种保留了土灵的力量和耐力，但是它的感知力量完全丧失。欲望和狡诈成为了穴居人的本能。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3183, '二号教程图像正在初始化。$B$B土灵母体的第二个变种和标准的地下生物母体相比较而言，保留了很多必要的元素。这个种族被称作“矮人”。$B$B这个变种同样保留了土灵的力量和耐力。在某些方面，矮人甚至超过了土灵母体所具有的感知能力。但是，矮人这个变种的身体结构中已经完全没有了石质成分的踪迹。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3189, '什么是“地下生物母体”？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3190, '你所说的变化是什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3191, '什么是“弹性构造基础”？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3192, '难道……土灵是用石头做出来的？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3241, '嗨这是我的文书。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3263, '%s裂成了碎片！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3302, '接下来就是你看到的情况了：毒药发挥了预期的作用，喝下毒药的人都变成了被人控制的行尸走人，然而，这种毒药非常不稳定。$B$B加里维克斯，还有这座塔里里外外的人都已经感染了这种毒药。我们的意志和身体都在不断被侵袭。我们的器官变得越来越脆弱。$n，我已经无力去拯救这里的人了，而且我感觉自己马上要变成他们的一份子了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3404, '欢迎来到猪和哨声旅店！和朋友在这里举杯畅饮，不亦乐乎！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3483, '在雷霆崖，你肯定找不到比阿丝卡·迷雾行者更好的厨师。嗯……我在这里都可以闻到他正在烹制的美味佳肴。你可以在中部高地的厨房里找到她。\n呃……我又饿了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3484, '到中部高地的附魔店去看看吧。泰戈会很乐意帮助你的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3486, '我不会因为你想学钓鱼而责怪你的。莫高雷有卡利姆多大陆上最好的钓鱼胜地，而在山顶渔具店中，你可以找到钓鱼所需的一切装备。\n告诉卡尔·迷雾行者是我让你去的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3802, 'Zul\'Farrak——Weegli Blastfuse——默认问候语。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3810, 'Zul\'Farrak——Sergernt Bly——默认问候语。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3989, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-A，这是一台一级机密等级的终端。$B$B你必须拥有一张白色穿孔卡片才能够使用该终端的功能。\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3991, '白色穿孔卡片读取成功……$B$B正在分配二级机密等级权限。\n01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3992, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-B，这是一台二级机密等级的终端。$B$B你必须拥有一张黄色穿孔卡片才能够使用该终端的功能。\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3993, '黄色穿孔卡片读取成功……$B$B正在分配三级机密等级权限。\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3994, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-C，这是一台三级机密等级的终端。$B$B你必须拥有一张蓝色穿孔卡片才能够使用该终端的功能。\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3996, '蓝色穿孔卡片读取成功……$B$B正在分配四级机密等级权限。\n01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3997, '这里什么都没有！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3998, '一言不发……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (3999, '%s歇斯底里地笑着。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4002, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-D，这是一台四级机密等级级终端。$B$B你必须拥有一张红色穿孔卡片才能够使用该终端的功能。\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4003, '获取更高等级的数据卡。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4004, '红色穿孔卡片读取成功……$B$B正在分配四级机密等级权限。\n00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4009, '矩阵式科技知识检测器探测到了你所具备的工程学天赋。你可以从以下选项中进行选择：\n01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4010, '获得：自动净化装置') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4011, '访问中……\n工程学<#技能等级 == 菜鸟>\n \n01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\n拒绝访问！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4012, '数据访问授权。祝你开心！\n01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4040, '%s翻开书页。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4041, '太不可思议了！就是它了，$n！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4058, '什么？我们的世界“被安排了新的探访计划”？这是什么意思？！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4084, '我准备好了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4142, '警报！警报！入侵警报！入侵警报！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4163, '保持阵形——入侵者正在靠近。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4170, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-A，这是一台一级机密等级的终端。$B$B检测到白色穿孔卡片。权限开放。\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4171, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-B，这是一台二级机密等级的终端。$B$B检测到黄色穿孔卡片。权限开放。\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4172, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-C，这是一台三级机密等级的终端。$B$B检测到蓝色穿孔卡片。权限开放。\n01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4173, '吱吱！$B$B欢迎使用矩阵式打孔计算机3005-D，这是一台四级机密等级的终端。$B$B检测到红色穿孔卡片。权限开放。\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4175, '%s收集好材料，开始工作。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4179, '和我们战斗的那些生物的灵魂，或者说“灵魂精华”中存在着不可思议的力量。$B$B看清你的内心；学着驾驭你的灵魂之力吧，你将获得超乎想象的强大力量。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4180, '灵魂精华容器已经准备好了，$n。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4181, '%s开始进行仪式。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4226, '我们对于树荫旅店被焚烧以及詹姆斯·海厄尔的妻子和孩子没能及时逃脱这些事情了解得并不多。$B$B我们想要找到詹姆斯的尸体，但是他却根本不在那堆废墟中。$B$B我们有一些线索，但是证据仍然很缺乏。我们希望能通过卫兵和塞拉摩人民的帮助让这件惨案得以大白天下。$B$B如果你也想帮忙的话，可以到贫瘠之地的边境那里调查一下旅店的废墟。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4227, '关于绿荫旅店，你都听说过些什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4254, '洛拉姆斯，无论你是否帮忙，我都会去做的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4261, '寻找帕瓦尔·雷瑟。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4262, '如果雷瑟和树荫旅店被烧毁的事有某种联系的话，你就得找到他，问个清楚。$b$b我派了奥格隆去追他，应该是朝东南方向去了。去跟奥格隆会合，然后一起去找雷瑟吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4309, '当你待在旅店里的时候，你就可以好好地休息。因此,你可以比留在野外更快地恢复到精力充沛的状态，这样就可以获得更多的经验值。$B$B另外你还可以通过和旅店老板交谈来获得一块炉石，以后就可以使用这块炉石快速回到你绑定的旅店里了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4557, '宝贝，让我来教你一个简单的加法守则：“地精”+“工程学”=“万事通”。告诉你其它算法的家伙肯定数学不及格。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4629, '即使在和平时期仍然会有战争，而许多氏族仍在酋长的领导下奋勇作战。你是来为奥格瑞玛而战的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4630, '即使在和平时期仍然会有战争，而许多部落仍在酋长的领导下并肩奋战。你是来为奥格瑞玛而战的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4642, '%s发出了一声怒吼！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4645, '什么？我在干什么？你眼睛不好使吗？我是一个梦想家，亲爱的$g先生:女士;，我梦想我们的将来会更加美好。很明显，我是个梦想家。$B$B然而，有些人却在想尽办法把我们困在平庸的泥沼里。我告诉过他，我是一个梦想家，而范达尔却回答说，“哦，我们似乎还缺一些挖水沟的。”$B$B我会帮助塞纳里奥议会弄走周围的泥堆，直到平庸的枷锁从我们身上卸下的那一天。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4646, '你好，$r。我是弗兰克罗恩·铸铁。你是来了解黑石塔和黑铁矮人的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4940, '我在火山口游荡了许久，后来我想起曾有人告诉我……“继续往前，到山上去。”这个声音在我的脑海中出现。$B$B听了这话之后我就来到了这里，$n！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4941, '很久之前，在我的旅途之中，我遇到了一个人，他告诉我：“掌握它的使用方法，你就可以拥有它。”$B$B你觉得那是什么意思？那时我还不知道，而且现在我还是不知道，真的……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4961, '入侵者！！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4993, '很抱歉，普瑞斯托女士。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5015, '反对者？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5017, '真有趣……继续。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5032, '你的知识太缺乏了。当你熔炼技术更成熟些时再来找我！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5033, '你可以走了……我希望在我生命的最后一刻独自待着。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5034, '啊……反对者。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5077, '你想去哪里？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5079, '你有需要保管的财宝吗？去找铁炉堡银行的石衣兄弟吧。\n从铁炉堡的入口往东北方向走，银行就在那边。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5083, '想要乘坐狮鹫，是吗？你得去找格莱斯·瑟登。\n你可以在铁炉堡中心的大锻炉东边找到他。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5085, '啊，没有什么比狮鹫更好的坐骑了。暗夜精灵偏爱可笑的角鹰兽，而我只需一头狮鹫就可以穿梭在云端！\n好吧，我不跟你唠叨了，到大锻炉东边的格莱斯·瑟登那儿去吧，他会向你出租狮鹫的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5098, '秘法大厅的法师彬克也许能帮忙解决你的一些魔法需求。\n秘法大厅就在铁炉堡的北部。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5101, '啊，布莱纳·火崖。她能使用魔法。她主管牧师事务。\n你要穿过铁炉堡大门，向北走，前往神秘大厅。她就在那里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5107, '所有的潜行者都居住在铁炉堡以北的荒弃的洞穴。我敢打赌芬斯维克也在那儿，正在数着偷来的钱包中的硬币呢。我总有一天会抓住他的！\n同时，我也会好好看着你的，$g小伙子:姑娘;。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5116, '你在寻找一个炼金术老师是不是？我也刚从那里回来。你会在侏儒集会的工匠区找到浆泡小姐的。\n：：叹气：：……为什么我没有服下蓝色药剂呢。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5122, '啊，要是你想成为一名附魔师的话，我想你需要找吉布·草须。他在 大熔炉狮鹫管理人右边的商店草须魔法用品店里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5124, '你想学习工匠的手艺吗？那你就得去工匠区找宾斯匹德。\n从铁炉堡大门一直往正东方向走，或者朝着传来爆炸声的方向走。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5132, '哦，你想学习采摘雏菊是吧？哈哈！我只是开个玩笑，$g小伙子:姑娘;。\n这是个很好的职业，雷纳·石枝会教你的。她在大熔炉南边的 铁炉堡医师协会工作。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5143, '特瑞莎·远山同样碰上了严峻的气候，但是她运用生存技能，以顽强的意志度过危机。\n如果你想找她谈谈，就去铁炉堡以南的军事区吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5147, '追踪？那么你得去拜访丹穆尔·远山。只有他能教你追踪的诀窍。\n出了铁炉堡大门往南走，去军事区找他吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5148, '我要将我的精力集中在这把刀上。这样就能捕获与刀关联的更强的精神印象。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5250, '你最好抓牢我，否则$n就有苦头吃了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5251, '看招！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5346, '月神的力量支配着你！月神的力量支配着你！\n出发吧！去达纳苏斯东部的月神殿中央大厅找贾德莉亚！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5358, '阿雷贡做的食物很受欢迎。他总是在工匠区忙于制作新的美食。要是有 塞纳里奥绿色烹饪的话，你一定要尝尝。\n如果你不介意的话，我必须先去调查一下接二连三的鹿群失踪事件。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5365, '哦！$g小伙子:姑娘;，当你选择附魔时，你得非常小心。我让自己的杯子附魔，使杯中的水不洒出一滴，但是我也不能喝到里面的水了！这真是个悲剧。\n当你看到格瑞姆比时，必须记得我的叮嘱。他在大熔炉狮鹫管理人右边的商店中。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5373, '我们种植蔬菜。野兔吃我们的蔬菜。狼群以野兔为食。我们捕杀狼群，从它们身上获得肉和兽皮。这就是神奇的生物链，或许你用别的什么词语来描述它。\n去塞纳里奥区找泰龙尼斯吧，我得继续执行自己的职责了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5375, '“一门可以让你度过重重难关的技能。”菲琳萨就是这样描述她的那套本事的。\n如果你相信她所说的，那么就到达纳苏斯北部的塞纳里奥区去吧，她在那里传授她的课程。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5383, '科兰德善于追踪，森林中的任何生物都没法从他手中逃脱。如果你想达到他的一半能耐，最好认真他教学。\n我会解除你费力寻找他的麻烦，为你标识出他的位置，他就在塞纳里奥区。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5481, '附魔体现了毁灭和新生的循环，这正是自然界的基本准则。晨行者附魔师将为你展示这一切。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5512, '你认为达丹加如何？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5544, '他们都去了黑石塔，但是跟比修一样……没有人活着回来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5545, '基布雷尔正在接受地精工程学协会的调查。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5546, '龙控制着兽人！？不会吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5547, '我在这儿！可悲的渣滓，你们会为侵入这里付出代价的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5573, '不，维埃兰，我不清楚。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5606, '这不是个游戏，伙计。你想使用斧子，就必须说那句话。说什么？“跟我的小朋友打个招呼。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5665, '蠢货……杀死穿那件衣服的人！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5666, '难以想象！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5695, '你在附近见过皮塔斯或达丹加吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5989, '你好，年轻的$c。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (5996, '壁炉谷？？但是……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6046, '“……”$B$B牛头人德鲁伊的尸体静静地躺着，看起来他好像终于离开了这个世界。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6061, '没有人胆敢挑战兄弟会！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6062, '蹲下来！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6063, '你们都是些不值一提的渣滓！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6064, '蠢货！我们的事业是正义的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6065, '胜利属于兄弟会！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6079, '你究竟是怎么进去的？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6115, '你，也必将臣服在我的脚下！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6116, '又倒下了一个！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6160, '一本打开的日记放在你的面前，发黄的书页上写着如下的文字：$B$B“哈洛德变成了这个样子，我不知道接下来会发生什么事。把他拖进我能找到的唯一可以关住他的地方之后，我已经心力憔悴了。我把钥匙藏在身上，祈祷能渡过这个难关……$B$B我希望能离开这里，但我需要钱。我想我们的东西都在那个柜橱里……现在我想起来了，哈罗德是不是把柜橱的钥匙藏在自己身上了？$B$B我要先休息一下，现在我实在是太疲倦了。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6161, '关于暗影之皮的章节。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6162, '入侵者到达偏门了！赶快通知瑞文戴尔男爵！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241, '你一定要原谅我，罗拉克斯，我没有“疯狂”地说什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242, '咬住你的舌头，$r，以免我把它拽下来用来擦拭我的犄角。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6243, '很抱歉，我没有意识到你可以理解我说的话。你在这儿做什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6299, '它位于贸易区的西边，就在喷泉的北边。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6309, '有一名优秀的厨师在旧城区的猪与哨声旅店工作。我曾在他身旁看他在烹饪时使用刀具，但是我可不认为他只是一名厨师。别误会我的意思……如果你想学厨艺的话，他会是你最好的老师。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6312, '嗨，提醒我啦，我需要修理一下火箭靴。聪明人一点就通啦，不要把火箭靴和狮鹫混淆的。\n哦，让我为你指明方向……穿过矮人区，你就会找到利廉姆·火轴啦。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6313, '要学急救的话，没有比光明大教堂的安吉拉·雷菲德更好的老师了。\n去找她吧，你只寻找黄色的屋顶或者教堂本身的尖顶就行了，在城中的任何角落都能看到这些标志。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6314, '啊呀！把那东西从我这儿拿走！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6317, '你为什么要追我，机械雪人？！为什么？！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6319, '一个猎人？好的，那么你会想跟矮人区的索尔芬·石盾谈谈。\n哦，你一定要告诉他如果我再次介入他的宠物生意，他就可以去培训那些监牢里的猎人了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6322, '%s看上去很轻松。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6324, '你知道，我可以刺穿一个兽人或是把一个巨魔切成碎片。我甚至可以把我名字的大写字母刻在食人魔的肚子上，但我就是不能忍受给动物剥皮。想一下都让我觉得恶心。\n好的，如果你有这种兴趣，那就到老城的护体皮甲找马瑞斯·格兰治。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6327, '%s到处乱跑，大声喊叫，制造骚乱。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6329, '啊啊啊啊啊啊！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6334, '哦，地铁，地铁……每个人都想乘坐地铁。那些乘坐狮鹫的好时光，那种在高空中飞翔时紧握缰绳的情景，它们到哪儿去了？\n啊！你还是坐地铁去吧……地铁就在侏儒区，那儿还有侏儒的其他精妙设计呢。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6335, '你是问我铁匠在哪儿？你没听说过大熔炉吗？所有最好的铁匠都聚集在那儿铸造武器和护甲！\n在铁炉堡中心都是敲打铁器的声音，你能在那儿找到最出色的铁匠本古斯·深炉。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6337, '哦，你是在找宾斯匹德吧。为什么那个小侏儒和他的装备……让我告诉你吧，如果你想去他在侏儒区的商店，管好你的手，别去抚摸他的机械绵羊！\n爆炸绵羊……为什么你要做这样的事情！？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6343, '呸！邮箱……最近我收到的全都是垃圾邮件！\n增加这个的尺寸……减少那个的尺寸……现在是免费的屠龙剑。我得每隔一个月就要更改邮箱号码才行！\n嗯，你可别说我没警告过你。邮箱就在石火旅店外面。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6344, '嗯！说到学习采矿的话，你来对地方啦，$g小伙子:姑娘;！吉尔弗拉姆·石趾居住在深山珠宝矿业协会。没有比他更好的老师了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6347, '你或许不知道，除了是一个娴熟的裁缝之外，约莫德还是一个巨人杀手！为什么说当他大喊他一拳打死了七个的时候可以断定他一定偷听到我们在一起讲的东西！\n你应该到大熔炉北面他的店铺去拜访他一下，并看看他是否会在跟你讲他的传奇故事！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6349, '一个术士，嗯……好吧，如果你想在附近继续做那种事情，你最好管好你的恶魔，$g小伙子:姑娘;。我不喜欢恶魔，但是我喜欢杀死他们。你明白我的话了吗？\n现在你不要再烦我了，马上消失去荒弃的洞穴。你会在那里找到那个术士，瑟斯哈特。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6350, '克斯塔姆是个大嗓门、爱吹嘘的人……他也是你所能见到的技艺最为纯熟的战士之一！\n我告诉你，如果你想成为一名战士的话，就去找他谈谈吧。他肯定在铁炉堡大门以东的军事区中。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6361, '不随意浪费东西是我们的传统文化。当我们不得不杀死某种生物时，我们会加以利用，不让它白白丧命。\n要是你想学习剥皮的话，就去工匠区找艾拉迪尔吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6368, '又一个想要靠倒买倒卖发家的？拍卖所就在贸易区，离银行不远的地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6370, '贸易区拍卖行') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6372, '所有参与作战的人都各就各位！纳迦来了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6373, '%s爆裂，喷发出有毒的粘性物质！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6374, '你敢玷污这片圣地吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6380, '血色十字军不会就此灭亡的！你不会冲破我们的战线的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6381, '旅行者，你好。很少有人以这种方式找到我。$B$B我叫雷沃，我在冬泉谷驯化这些霜刃豹，使它们成为坐骑。$B$B这些猫科动物非常凶猛，极难驯服。只有那些最值得信赖和最受人尊敬的人才可能骑上它们。$B$B我是不会随意出售这样的坐骑的，你必须用行动来证明，让我和霜刃豹都接受你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6382, '关于多彩龙鳞的信息。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6383, '关于魔光多彩鳞片的信息。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6384, '关于英雄之血的信息。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6392, '在暴风城，有很多地方可供饮水休息，但是只有一处可以过夜。去贸易区的镶金玫瑰吧。我听说客房的费用相当合理，被单也很整洁。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6394, '在暴风城银行和贸易区的镶金玫瑰旅店之间设有邮箱，非常便利。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6404, '嗨！你喜欢沙司吗？沙司很美味，不是吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6406, '我来自底层社会……我们那儿的人民倍受折磨。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6661, '我感到有些恶心。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6740, '马里恩·考尔和黑暗牧师贝里尔一起在布瑞尔镇东南角恐惧之末旅店楼上的阅览室中。我只是想看看谁是这场对抗的胜利者。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6865, '也许你应该对着这些套在我愤怒的拳头上的扩音器讲话。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6866, '啊，我心爱的白兰地，我太思念她了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6867, '保持警惕！这一带有许多黑木熊怪……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6885, '啊，我在燃烧平原的仆从带来了龙……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6886, '马杜克，把箱子放在我面前！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6919, '到闪金镇的狮王之傲旅店去吧。那儿有啤酒和柔软的床铺供你尽情享用，没有比那里更好的休息场所了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6920, '闪金镇的狮王之傲旅店是这个地区中最好的旅店了。在那儿歇一歇吧，旅店老板法雷会让你感受到家的温暖。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6927, '洁塞塔经常帮助镇子里的守卫，她是圣光赐予我们的礼物。如果你想学习牧师技能的话，可以去狮王之傲旅店找她。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6928, '我敢打赌洁塞塔会很乐意教你学习新法术的。她就在狮王之傲旅店的房间内。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6930, '扎尔迪玛可能会教你一些新的法术。他最近喜欢待在狮王之傲旅店，你可以去那里的房间看看他在不在。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6931, '我对魔法知之甚少，但是在狮王之傲有一个名叫扎尔迪玛的法师，他也许能帮助你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6937, '我打赌科瑞恩·塞尔留斯知道你在寻找什么东西。她通常在狮王之傲旅店里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6942, '哦……好吧，玛克西米利安是这附近唯一一个了解黑暗魔法的人。你也许可以在狮王之傲旅店那阴暗的地下室里找到他。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6943, '一个术士？好吧，如果我是一个术士，我可能会待在这附近最黑暗的地方……那就是狮王之傲旅店的地下室。你应该先到那里去看看。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6944, '我知道有些人在这附近练习某些专业。你想要打听哪项专业技能的训练师？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6961, '托马斯也许不是最好的厨师，但是他确实能做一些精美的菜肴。如果你想学习厨艺的话，就去狮王之傲旅店找他吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6962, '你为什么不到狮王之傲看看呢？那里的厨师可能会教你几道好菜。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6967, '我最近在这里附近遭遇过一些迪菲亚盗贼，但米歇尔·贝利帮我进行了治疗。到狮王之傲与她商量一下，看看她能否教你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6968, '米歇尔·贝利对病患的态度令人钦佩！她也许无法教你如何对待病人，但是她可以教你一些急救技巧。她现在居住在狮王之傲旅店。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6970, '李·布朗在水晶湖中抓到过很多奇怪的东西。他说他数月前钓起过一个神秘的面具。但是照实说，我想他那晚一定在狮王之傲喝多了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7000, '你需要找哪个职业的训练师？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7203, '谁敢在我的领地里向我挑战？！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7205, '结束我们的痛苦吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7206, '你必须救他！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7433, '真悲哀。弗丁还活着……你来晚了，年老的隐士。回到你的洞穴吧，除非你想和在扭曲虚空的儿子一起。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7436, '来吧，隐士！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7438, '熊的灵魂平和的凝视着你。你听到了一个声音在对你讲话，好象是从熊那里传来，但是没有迹象表明这个动物在说话。$B$B“你好，我年轻的朋友。如果你是来找我寻求指引的，那么或许我能帮你找到你想要的东西。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7439, '你代表什么，灵魂？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7559, '嗨！?从来没有过深海潜水的经历吗？我告诉你一个小秘诀，嗯。在海洋深处有许多冒气泡的裂缝，当你在水下时可利用这些气泡进行呼吸。这个秘密只限于你我之间。对我来说，贝壳到处都是……如果你懂我的意思的话！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7561, '不……不可能！等一下……我投降！我投降！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7644, '我不能训练你，年轻人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7655, '你这个莽撞的家伙！你简直是自寻死路！看吧，你惊动了主人！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7672, '仅在三百年前，一个叫作索瑞森的鲁莽的矮人从他炽热的领地中召唤出了魔王。他重返这个卑微的世界吞噬了周围的田地并形成了这个火山之核。从那以后，强大的拉格纳罗斯就沉睡在了这座山下。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7675, '你向我们发出挑战而我们来了。你所说的大师在哪里？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7685, '现在轮到你们了！你们愚蠢地追寻拉格纳罗斯的力量，现在你们即将亲眼见到它！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7753, '我已经恢复了力量，愚蠢的人类，你浪费了一次机会。下次再会吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (7878, '向你问好，旅行者。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Greetings to you traveler.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8140, '都是些有用的东西。你的教导可以继续进行了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8141, '啊，这件达纳苏斯织品质量最好！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8176, '锻造是一门精细的技艺。被派到这里之前，我在落锤镇花了不少时间练习。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8230, '你能告诉我关于夜刃豹——猎影的情况吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8314, '恕我直言，统帅大人--为什么不消灭他们？难道这不会巩固我们的地位吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8481, '很高兴再次见到你，$n。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8482, '你好，$c。你找法拉德谈过了吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8483, '辛迪加工会的成员都是些平庸的家伙——缺乏组织性、技能拙劣、懒惰……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8484, '你真的变得狡猾多了，$n。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8490, '我不适合这次谈话，$G主人:女主人;。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8491, '能为你服务是我的梦想，$G主人:女主人;$n。换句话说，你认为我值得得到这些东西吗……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8532, '好心的旅店老板艾玛，她现在已经照顾当地的动物好些年了。我敢肯定她会很高兴照顾你给的任何动物。你可以在狮王之傲旅店的外面找到她。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8533, '旅店老板艾玛照料着这周围的所有动物。要是你需要跟她交谈的话，就去狮王之傲旅店外面找她。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8658, '你继续翻阅这本日志寻找任何可以帮你找到那个被盗箱子的消息。$B$B到书的最后几页, 你可以在书页的边上看到詹姆士用红色铅笔做的标记。上面写着, “石碑湖附近的老房子……豺狼人当保镖会很出色。”$B$B没理由这就是箱子的所在暗示, 但好象又没有任何其它的线索。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8677, '大地之母日夜监视着我们。让这火焰照亮我们的身体和灵魂吧，让我们想起尊敬的祖先，他们一直都在我们身边，指导我们前行。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8678, '我想重新学习制皮的技能。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8767, '当我的狮鹫坠落时，我听到了他们嘲弄的笑声，$c。$B$B“斯里多尔， 你太差劲了！”他们大声嚷道。$B$B没有人敢对斯里多尔那样说话！帮我离开这里，我会让他们知道我的厉害！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8814, '谁控制着雷矛墓地？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8817, '穿过丹巴达尔以东的桥梁，雷矛墓地就在群山之中。$B$B联盟控制着这片土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8818, '穿过丹巴达尔以东的桥梁，雷矛墓地就在群山之中。$B$B部落控制着这片土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8821, '雪落墓地就在冰斧要塞以东的征战平原的高山顶部。$B$B联盟控制着这片土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8823, '雪落墓地就在冰斧要塞以东的征战平原的高山顶部。$B$B部落控制着这片土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8825, '霜狼墓地就在离霜狼村北面不远的地方。$B$B联盟控制着这片土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8826, '霜狼墓地就在离霜狼村北面不远的地方。$B$B部落控制着这片土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8865, '$n！你在做什么？你应该出去为了部落而战！$B$B我需要一名值得信赖的人去征战平原，去找指挥官传达攻击命令。$B$B要是你的声望再高一点，我也许能派你去……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8868, '如果你想要进行更多训练，我可以告诉你该去哪里。你想要学习哪种武器呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8869, '卡尔·雷矛，死吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8870, '骑兵们，冲锋！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8871, '士兵，你做得棒极了！骑兵们已整装待发，就听你的指令了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8874, '如果你想要进行更多训练，我可以告诉你该去哪里。你想要学习哪种武器呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8947, '或许我们可以稍后再尝试尝试。等你想好的时候再跟我谈谈。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8972, '医生，请告诉我制作符文布绷带的方法。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8973, '医生，请告诉我制作厚符文布绷带的方法。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9094, '探险者报告！……棒极了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9095, '%s垂涎欲滴地盯着一只矿道鼠。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9099, '如你所愿……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9144, '%s放下木棒，开始狂野地摇摆！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9145, '你胆敢惹恼我，懦弱的家伙！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9148, '有什么事吗，$c？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9210, '我没什么可以教你的了。我听说藏宝海湾有个名叫海明威的老头，他在出售《鲈鱼与你》这本书，它对你提高钓鱼技能大有帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9211, '雷矛急救站被部落占领了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9219, '我没什么可以教你的了。我听说藏宝海湾有个名叫海明威的老头，他在出售《鲈鱼与你》这本书，它对你提高钓鱼技能大有帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9299, '很久以前，在篡位者称为创世之年代的时候，我的主人和他的同胞们统治着整个世界。是他们，是远古的神灵创造了一切。$B$B他们最终被那些称他们为缔造者的家伙推翻了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9301, '他们庞大的身躯在多年的战乱中渐渐衰弱，被禁锢在地下世界——他们自己创造的地下世界中——堕落的泰坦缔造者能渗透地表，污辱古老的神灵。$B$B兄弟反目。一场持续五千年的战争在世界的核心展开。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9331, '炎魔之王拉格纳罗斯在元素大灾变中想要杀死我的主人桑德兰，空气的王子。$B$B<德米提恩低下头，面部肌肉因愤怒而扭曲。>$B$B一旦你说出他的名字，我就会用你的内脏装点这座被破坏的营帐。保持安静，听好了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9332, '<点头>。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9337, '桑德兰的精华的些许残留物存储在元素绑定护符中。拉格纳罗斯将护符打碎成两块，分给了他的两名士官……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9338, '丹巴达尔是联盟在奥特兰克军力最强的地方。位于山谷北部的丹巴达尔是通往南部的军事要塞。$B$B丹巴达尔现在完好无损。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9339, '丹巴达尔是联盟在奥特兰克军力最强的地方。位于山谷北部的丹巴达尔是通往南部的军事要塞。$B$B丹巴达尔已经被夷为平地，正在重建。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9340, '霜狼要塞位于奥特兰克山谷的南部，是通往霜狼村的要塞，是名为霜狼的兽人氏族的家园。部落在奥特兰克山谷所有领土都从这儿衍生。$B$B霜狼要塞完好无损。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9341, '霜狼要塞位于奥特兰克山谷的南部，是通往霜狼村的要塞，是名为霜狼的兽人氏族的家园。部落在奥特兰克山谷所有领土都从这儿衍生。$B$B霜狼要塞被夷为平地，需要重建。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9342, '告诉我关于丹巴达尔的事情。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9343, '告诉我关于霜狼要塞的事情。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9374, '%s开始生长啦！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9375, '%s继续生长着！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9376, '%s已经完全长大了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9377, '好吧老大，当你想要下属为你上贡的时候，就告诉我！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9378, '绘制戈多克战争之画！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9380, '精灵，这儿发生了什么事？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9401, '叫我“国王”。你为我带来了什么！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9463, '哦，亲爱的，“防御圣典”在哪儿？莱德罗斯会勃然大怒的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9465, '“奥术学家的食谱”也不见啦！这真是一场灾难！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9475, '“迦罗娜：潜行与诡计研究”在哪儿？必须找到它！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9518, '在仪式中，必须使用守护者的后代来锻造这柄剑。真是少见啊……龙不得不锻造并为这柄剑附魔，还得牺牲自己的后代做为附魔的调和剂。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9538, '丰饶之果？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9605, '“咔咔”是什么意思？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9606, '要是你的手套太大的话，还算是合手的手套吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9607, '你离家还远着呢，$r。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9608, '戴奥，我是来学习的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9609, '你来了。你是来学习镇压和控制之道的吧。$B$B我会教你更多的东西……你将学会牺牲。$B$B<戴奥咧嘴而笑。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9610, '我要牺牲什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9611, '你得选择自己要召唤和驱使的恶魔。我们运用黑暗力量并为此付出巨大的代价。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9612, '要怎么召唤恶魔？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9613, '要是你还想继续前进的话，我们必须首先找人对付野兽。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9641, '我愿意用萨弗隆战锤的设计图换取一块萨弗隆铁锭。$B$B现在，你大概正在暗自盘算吧，“我要那种战锤来做什么，我现有的装备比这东西高级多了！”$B$B嗯，让我告诉你吧，$g先生:女士;，没有什么武器比萨弗隆战锤更高级了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9679, '狂风骤起，%s愤怒的吼叫声从西北方传来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9684, '去银风避难所找珊蒂瑞亚吧。她可以卖给你“中级烹饪教材”。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9685, '烹饪是我一生的追求，我觉得我们俩有共同的爱好！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9686, '加基森的迪尔格·奎克里弗对厨艺非常精通。要想提高自己的能力，你就去找他吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9687, '葬影村的乌兰可以卖给你“中级烹饪教材”。如果你想要提高烹饪技能的话，就需要这本书。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9688, '我可以教你如何烹饪！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9757, '突然之间，你成为了“联盟的保卫者”，是吗？！嗯，我猜你一定是想去勇士大厅。大厅就在旧城区。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9774, '%s在公正的审判降临时痛苦地后退！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9775, '%s在正义的审判降临时痛苦地后退！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9844, '醒来吧，小红龙……毁灭他们！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9845, '比赛现在开始！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9884, '在第三次大战中，肯瑞托的法师和亡灵天灾进行了殊死的战斗。大法师阿鲁高召唤了异世界中的狼人来增强达拉然守备部队的力量。这些狂暴的狼型生物踏平了来犯的亡灵天灾，然后迅速将目标转向达拉然的法师，并开始围攻席瓦莱恩男爵的城堡。这座位于焚木村的城堡不久之后就变成了黑暗势力的聚集地，并从此荒废。因为对于自己罪过的愧疚，阿鲁高将那些狼人当作自己的孩子并隐居在“影牙城堡”中。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9903, '在你匆忙追寻荣耀的过程中，你有没有想过你的行动对于这场竞赛的节奏有什么影响？你有没有想过你们的行为对我来说是多么可笑而荒谬？我对你来说是个难以理解的存在，这让你那花生大小的脑子感到十分迷茫。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9904, '你已经失去理智了，奈法里奥斯。你在胡言乱语。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9995, '这个机器所依据的理论就是通过一次大爆破将你完全摧毁，然后把你的粒子通过空间裂隙传送到某个地点，再通过反爆破模块将你在目的地重组。这是即时的传送！它并不是百分之百有效的，但是你是个杰出的地精技师！如果你把性命看得比发明创造更重要，那么你永远都无法成为一个真正的地精技师！\n这是制作空间撕裂器所需的图纸，你一定要试试看！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (9998, '一旦你建造了这个装置，你就将被传送到可爱的加基森！几乎使用这个装置的人都发现在其立即到达了这里！$B$B有报告说，有别人试图用一种坏的版本来替换我们的产品，但是我相信我们不久之后就可以解决这个问题……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10048, '好吧……$B$B假设你从你的主人那里接受了保护玉米田并清除小偷的任务。一天晚上，在你巡逻的时候发现了一个穿着破烂布衣的人正在田里偷窃玉米。你马上上前，而他立即跪在你的面前求你不要杀他。他说他偷玉米是为了养活他一家，因为这块土地的主人——也就是你的主人向他们征收重税。你的主人一向以此而闻名。$B$B你该怎么办？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10049, '我按照命令把他杀掉，反正他不过是个小偷和骗子而已。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10050, '我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10051, '我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10052, '我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10053, '你的下一个选择在等着你。$B$B你是一个效忠于主人的刽子手。有一个背叛了你的主人和人民的人被送到你这里来受刑。可你以前认识他，他曾是你非常要好的朋友，并且非常善良，但是有一天他突然消失了。你还知道他所犯下的罪行导致很多无辜的平民的死亡。当你看到他的时候，他求你饶命，并且说他是被一个高官所陷害的。$B$B你该怎么办？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10092, '$n，这是你的塔罗牌。愿你能好好利用它。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10179, '给我饮料！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10180, '呱呱。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10210, '$962w个雷矛指挥官和$950w个雷矛上尉。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10211, '$n突袭了铁匠铺！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10212, '$n突袭了铁匠铺！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10320, '我们不会让这种事发生的……我们以前曾经放逐过他，我们会再次放逐他的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10475, '欢迎参加藏宝海湾钓鱼比赛，每周我们都会选出一位最好的渔夫，授予他钓鱼大师的称号!$B$B在下午2点到4点之间，大群的可口鱼会出现在荆棘谷海岸。如果你的浮标落在可口鱼鱼群中，你肯定能钓上一些的，这比在荆棘谷一般的海域垂钓要有效得多。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10476, '你好，$c。我是拉斯塔哈的仆从伊克萨尔。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10477, '战斗将在1分钟后开始。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10478, '战斗将在30秒后开始。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10479, '战斗开始了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10493, '*吱吱**叮当*\n我奉命收购肥美的稀有鱼类，用纳特·帕格的钓鱼用品来交换哦。收购鱼类啦。\n*砰**嗡嗡*') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10547, '嘿嘿嘿！我在这里是为了推广荆棘谷的超级无敌钓鱼锦标赛的。不过你首先得有足够的生存能力在这里活下去，然后还需要足够在这里钓鱼的精湛技巧。$B$B当你更符合以上条件的时候再回到这里来吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10548, '嗨！嗨！嗨！如果你想要试试自己的钓鱼技能，那么你来对地方啦！本周日荆棘谷将举办一场钓鱼大赛！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10549, '%s迅速逃窜至另一只老虎处寻求庇护。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10594, '你胆敢踏足哈卡的圣地？哈卡的属下们，摧毁这些异教徒！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10595, '很高兴遇到你，渔夫！如果你想要在钓鱼比赛中一展自己的钓鱼技能，那么就听好了！在本周日，荆棘谷将举办一场钓鱼大赛，选出一名真正的钓鱼大师！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10596, '你好！我在这里是为了推广荆棘谷的超级无敌钓鱼锦标赛的。不过你首先得有足够的生存能力在这里活下去，然后还需要足够在这里钓鱼的精湛技巧。$B$B当你更符合以上条件的时候再回到这里来吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10600, '钓鱼大赛的赢家已经出炉了，但是贾恩愿意收购你们钓到的可口鱼!$B$B每周日都会有一场钓鱼大赛，你尽可展示自己的钓鱼技能!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10601, '嘿！恭喜你，朋友！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10602, '哈哈！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10603, '嘿嘿！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10673, '你！你看起来身体强健……南海镇需要你的帮助！$B$B万圣节到了，那些受诅咒的被遗忘者蠢蠢欲动。他们把所谓的庆典开到我们家门口来了。如果你有时间的话，我们真的需要你的帮助！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10674, '啊……真冷……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10717, '我们把她交给了指挥官，希望议会的德鲁伊能医好她。我们相信德鲁伊们能让她清醒过来。我们跟议会之间已经两清，该回去做自己的事情了。$B$B过了好几周，一切看来进展顺利。布莱恩仍然四处奔波，我们也正常地工作着。有一天，她突然出现在我们的营地里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10732, '那还用说！布莱恩、鲁特加尔、猴子和我都对此感到陌生，我们懂38种语言，还略懂一点泰坦语——连瓦尼尔和艾斯尔都不例外。$B$B总之，她嘴里叽里咕噜说的话没人能懂。“礼物”？她点点头，就开始攻击我们！直接攻击我们！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10769, '这个大炮怎么用？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10770, '嗯，很简单的!这东西的使用方法和你以前用过的那些东西没什么两样。别担心，我会负责点火。当你升空之后，你会发现自己正「飘浮」在空中，但是这种情况不会持续很久。你将被发射到湖边的一个目标那里去。只要记得在适当的时候将你的「翅膀」分离，就可以安全地掉入湖中了!不然的话，嗯，我不负责出售人身保险。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10775, '暗月马戏团奖券？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10781, '在希利苏斯，我们的敌人不止一个，$n。$B$B虽然每个人的注意力都集中到异种虫类身上，但是我和我的兄弟密切注视着暮光之锤的一举一动。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10851, '太神奇了，这与卡利姆多的泰坦以安戈洛环形山为家的说法不谋而合。或许阿曼苏尔在亲自守护着这块“神的土地”。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10931, '鹿盔，你要去哪儿？为了自尊和高傲，你就要切断我们的联系？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (10955, '你的行为让我们蒙羞，$c。我感到深深的耻辱，所以你死定了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11064, '<纳瑞安将一封未打开的信贴到他的前额。>$B$B这是什么……嗯……天鹅绒！$B$B是吗？$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11065, '别说话！让我猜猜！你是为灰烬使者而来的吗？！对……呃……不对！不好意思。$B$B我能帮你什么忙吗，$R？$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11066, '纳瑞安为您效劳！退隐的工程学专家和占卜大师！我敢打包票！$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11067, '你真烦人，$n。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11074, '%s凝视着$n！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11154, '伙计，欢迎来到藏宝海湾。希望你在这儿度过一段快乐而……嗯，平静的日子。如果你口渴的话，我们这儿有很多饮料；如果你担惊受怕的话，我们这儿还有很多保镖。$B$B现在，我这个卑微的地精仆从能为你做些什么呢？呃，你又能为我做些什么呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11217, '即使是我的父亲也未曾预料到这样的悲剧……这可怕的混乱。你们是不可能成功的！没时间了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11218, '啊，保护屏障就要消失了。英雄，你们听见了吗？那……那就是不可避免的宿命。你的希望和梦想在我面前是那么不堪一击。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11219, '节杖碎片已经不复存在了！你心爱的卡利姆多将很快成为一片荒芜的大地。当然，我会负责让东部王国也变成一片废墟的……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11295, '你算错了一招，野兽。你不曾料到我们会在玛法里奥的身边召唤你吧？伊兰尼库斯，你的救赎就要来临了。你将得到净化——堕落之源将被清除。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11296, '%s露出阴险的笑容。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11297, '救赎？大胆！只有我的神能救赎我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11298, '%s疯狂地咆哮起来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11299, '出来吧，梦魇的仆从们！摧毁这世界！不留活口……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11300, '快，$n！我们必须尽快找地方躲起来！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11301, '勇士，请保护我们的人民吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11313, '梦境之暴君伊兰尼库斯被月神之光吞噬了。月光林地恢复了往日的宁静。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11314, '燃烧起来了！疼痛……灼热……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11315, '为什么？为什么……会发生这种事？泰兰德，你在哪儿？当我在月神面前倒下时，你在哪儿？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11316, '我……我感到……我再次感受到月神的触摸……她在对我微笑……是的……我……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11332, '流沙节杖终于得以复原，$n。$B$B只能你能使用这把节杖，只有你能带领你的同胞走向新的纪元。$B$B你必须等待部落和联盟的军队抵达希利苏斯，然后你就可以敲响甲虫之台的铜锣了。战争即将拉开序幕。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11349, '在这头驯鹿的脖子上挂着一个小牌子，牌子上印着烟林牧场的标志和一个名字：“梅森”。$B$B梅森用悲哀而孤独的眼神看着你，它似乎被某种无形的力量困住无法动弹了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11350, '你自由了，梅森。坏格林奇再也不能伤害你了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11387, '这件礼物的卡片上写着：“40岁以上适用。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11388, '拿取你的礼物！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11389, '你好啊。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11390, '整个世界都感激你和你的同伴们所做的一切，$n。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11395, '这件礼物的卡片上写着：“20岁以上适用。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11396, '这件礼物的卡片上写着：“10岁以上适用。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11402, '敢耍诈？去死吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11415, '你好，$C——我是达纳苏斯的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在达纳苏斯的声望也会因此提高。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11416, '你好，$C——我是诺莫瑞根流亡者的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在诺莫瑞根流亡者中的声望也会因此提高。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11418, '你好，$C——我是暴风城的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在暴风城的声望也会因此提高。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11419, '你好，$C——我是奥格瑞玛的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在奥格瑞玛的声望也会因此提高。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11420, '你好，$C——我是暗矛部族的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在暗矛部族的声望也会因此提高。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11421, '你好，$C——我是雷霆崖的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在雷霆崖的声望也会因此提高。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11422, '你好，$C——我是幽暗城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在幽暗城的声望也会因此提高。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11423, '%s展开了猛烈的攻势。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11436, '范达尔！你的死期到了！藏到翡翠梦境里去吧，祈祷我们永远都找不到你！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11437, '鹿盔将会呜咽着哀求我饶他一命，就像他那懦弱的儿子一样！一千年来的屈辱会在今天洗清！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11438, '让敌人胆战心惊吧！让他们在恐惧中死去！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11439, '我们不用再呆在这座石墙里面了！我们很快就能报仇了！在我们的怒火面前，就连那些龙也会战栗！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11440, '我们复仇的时刻到了！让敌人的内心被黑暗吞噬吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11441, '%s察觉到了你的恐惧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11442, '你们玷污了这片神圣的土地，会因此受到惩罚的！上古之神的律法不容藐视！入侵者要付出生命的代价！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11443, '我宣判你死刑！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11444, '我战斗到了最后一刻！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11445, '你这么想死吗？我很乐意满足你的愿望……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11446, '就用你的死做个警示吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11447, '你是在逃避必然的命运！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11448, '感觉到了你的恐惧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11449, '沙漠，扬起你的沙砾，遮蔽太阳的光芒吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11450, '你被终结了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11451, '我……败……了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11452, '不！哥哥！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11453, '你逃不掉死亡的命运！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11610, '尊重你的长辈同样也是尊重你的文化与人民，$c。而先祖硬币则是对遵循这样一条古老礼仪之道的人的赞许。$B$B在春节期间，你可以拜访许多长者，对他们表达你的尊敬。如果你这样做了，你将会得到先祖硬币。将这些硬币带回来，我会因你的勤奋而允许你从一些特殊的物品中选择一个作为奖励。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11611, '其拉军队出现了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11621, '我是布洛克斯的兄弟，萨鲁法尔。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11622, '我是卡利姆多联军的最高指挥官，你们都知道这一点。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11623, '%s停顿了一下，环顾着站在他面前的那些神情紧张的士兵。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11624, '一个兽人，一个真正的兽人战士，他一生的追求只有一个：在与敌人的决战中光荣地战死沙场。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11625, '你们当中的许多人没有参加过真正的战斗。和平，和平已经伴随了我们许多年。这些年来，我们无所事事，但我们也曾奋战过许多年。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11626, '在那段战斗的岁月里，硝烟弥漫着天空和大地，燃烧军团和亡灵天灾肆虐在我们的家园，杀戮着我们的亲人。在那时，这些虫子潜伏在我们脚下，潜伏在我们的家园下面，等待着。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11627, '等待着把我们全都杀死，从我们的孩子开始。这就是它们为自己的神所做的事情。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11628, '我们会为自己的神明做些什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11629, '我们誓死抵抗。我们誓不言败。我们是一个整体，一个团结起来的整体。我们将获得胜利，而它们的神必将失败。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11630, '今天，如果我们战死，死在这片战场上，我们虽死犹荣。今天，如果我们战死，那是为了保卫我们的孩子，我们的父母，我们的……爱人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11631, '你们当中有谁会惧怕这样的死亡？有谁会拒绝获得这样伟大的荣耀？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11633, '为荣誉而战！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11634, '为了国王！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11635, '为麦格尼而战！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11658, '“在为战争采集资源这方面，你做得太棒了！”他们说，“你一定会得到晋升的！”然而他们真正的意思是，“你会和一群小不点的矮人一起被部署在希利苏斯的某个虫巢外面，卡恩斯！”$B$B多谢提携，中尉！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11660, '跑吧，胆小鬼！别自讨苦吃！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11710, '灵魂的盛宴即将开始……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11720, '城墙被攻陷了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11781, '好了，好了，冷静点，$c，没什么好担心的。既然我们有幸得到了它，我就做了防范。在你第一次给我左瓣的时候，我在它和自己之间建立起了连接，要是找不到它了，我可以把它召唤到我手里来。$B$B给，这次一定要小心，不要再弄丢。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11865, '想看看我出售的货物吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11880, '这么说，你想要重新学习那些被遗忘的技能？或是学习全新的知识？我倒是可以为你指条明路，$n。去热砂港以东纳瑞安的巢穴寻找一本名叫《傻瓜预言书》的魔法书。翻开看看吧。$B$B<尼克斯眨巴着眼睛。>$B$B你会发现书中记载了你想要了解的东西，甚至还有……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11894, '我不能教你龙鳞制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11895, '你这污秽的家伙，滚！回到你主人身边去！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11900, '我不能教你元素制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11902, '我不能教你部落制皮，$n。你得前往塔纳利斯寻找纳瑞安的老巢。那本名叫“Soothsaying for Dummies”的书会对你有所帮助的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11903, '索尔让我进入他领地中的圣域是对我释出相当大的善意。无论如何，我不求久留。给我们的领导者带来任何麻烦都是极大的侮辱。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11939, '%s目睹$n在战斗中丧命后变得狂暴起来！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11941, '当碰到危害这个世界的事物时，我们圣光兄弟会相较之下是不会手下留情的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11942, '巫妖王正试图要将他的存在传达给整个世界，让这个世界陷入恐慌与噩梦之中。绝对不能让这一切发生。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (11943, '什么是圣光兄弟会?嗯...我们都是银色黎明的核心成员，不受道德、罪恶感和没用的人类情感所操控。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12065, '是你当时的指挥最终使得沉痛在无尽悲伤之中的孩子如此执着于重铸此剑。如今，这个孩子已经成长成人，可却彻底被复仇的意志与愤恨的偏见占据了身心。这都是为了什么？而且，比起五年前，你与这把剑渐行渐远了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12066, '难道你还认为重铸灰烬使者能够对战争局势产生什么影响么？让我告诉你一个小秘密吧，指挥官。灰烬使者的力量来自于挥舞着它的那个人……当时我也在场，指挥官。我亲眼看着他在圣剑出鞘之前，就以正义之火烧尽了一个军团接一个军团的亡灵士兵。啊……你对历史……实在是了解不多。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12123, '报上你的名字，军阶，还有编号。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12124, '是，长官！谢谢您，长官！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12125, '<查博斯元帅咆哮着。>$B$B你们就是那群帮迪迪尔把这些补给运到这鬼地方来的家伙吗？这就是你们的全部人马？还有其他人吗？在哪儿？小鸡一般都是成群结队的。$B$B好吧好吧，给我该死的文件，我签了它，现在就签了它。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12126, '干得不错，士兵。解散！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12228, '米兰达，你能告诉我，在尊敬声望级别的情况下，你所提供的物品需要多少徽记吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12231, '米兰达，你能告诉我，在崇敬声望级别的情况下，你所提供的物品需要多少徽记吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12234, '米兰达，你能告诉我，在崇拜声望级别的情况下，你所提供的物品需要多少徽记吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12237, '友善。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12238, '尊敬。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12239, '崇敬。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12240, '崇拜。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12248, '真的吗？某个带着理想穿过这些大厅的$r？啊，正义之火正在你心中熊熊燃烧着。$B$B我的生命很快就要终结了，但我家世代传承下来的智慧必须延续下去。这就是我来这里的所有原因。$B$B你有精通任何制造技巧吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12249, '你的到来让我倍感觉欣慰，$r。哎，我的时间真的不多了，或许我马上就要离开这个世界了，可……我的智慧……我脑海中容纳了那么多东西。那么可以帮助你们击败隐藏在这座城堡中的邪恶堕落腐朽势力的智慧。$B$B智慧的火种绝对不能熄灭……你有精通任何制造技艺吗……对啊，或许你能继承这些知识，并用它拯救这个世界。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12251, '我是一个大师级裁缝，奥玛里恩。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12252, '一个裁缝，是吗？非常好，你想学些什么，裁缝？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12253, '冰川外衣。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12254, '冰川披风。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12255, '冰川手套。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12256, '冰川护腕。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12257, '我是一个大师级制皮师，奥玛里恩。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12258, '或许我能教你些什么……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12259, '寒鳞胸甲。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12260, '寒鳞护手。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12261, '寒鳞护腕。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12262, '北极外套。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12263, '北极手套。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12264, '北极护腕。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12284, '我所犯下的错误……多么可怕的错误……$B$B<塔希斯的声音呜咽了起来。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12285, '你到底做了什么可怕的事？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12286, '我是一名上层精灵，$r。虽然这个词语现在已经不能代表什么了，但很久以前，这个世界曾被上层精灵所统治。一万年过去了……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12287, '我还是不理解。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12288, '我一定会把它找回来的，凡人。埃提耶什……有了它，我就可以重建上层精灵社会。我一定会把它找到的。就算是女王……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12498, '这还不够。$B$B<法尔班克斯苦笑了一声，略微失神了片刻。>。一千个天灾军士兵而已，它们很快就都死了。圣光在上！莫格莱尼之力万岁！混乱中，他接连把那些亡灵一个个放倒，而小莫格莱尼却仍在一旁站着不动，维持着距离。我向他喊道：“帮帮我们，雷诺！帮帮你的父亲，孩子！”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12502, '我所能做的全部事情不过是继续装死，很快，天灾士兵的尸体就把我埋在了下面。我只能感觉到身体上的重负，以及耳边呼啸着的砍杀搏斗声，钢铁碰撞声，总之，可怕的声音。不知过了多久以后，一切都静默了下来，我听见他在叫我，“法尔班克斯！法尔班克斯，你在哪儿？听到了就说话，法尔班克斯！”接着，最无耻的背叛就发生了……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (12504, '那孩子捡起了灰烬使者，并从背后向他父亲砍了过去。老人最后的一句话现在仍在我耳边回转不去：“你！你干什么？！雷诺？为什么？！”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13022, '%s狂笑不止。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13023, '主人要吃了你！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13024, '费尔根……完了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13025, '费尔根要让主人高兴。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13026, '事业……未尽……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13027, '死亡是唯一的解脱方式！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13760, '乌瑞恩堡若不在我们手中，敌人随时都能打进来。\n\n要塞拿下来之后，再来找我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (13762, '我能感应到永恒龙军团的污痕。让我看看你学到了什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I can sense the taint of the Infinite Dragonflight. Show me what you have learned.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (16680, '我是法斯塔德，蛮锤氏族的领主。你能否闻到空气中的气味，巨魔的恶臭像瘴气一样萦绕在辛特兰上。\n\n巨魔已经越来越接近鹰巢峰，我们的工作就是抓住一切可能的机会来压制他们。\n\n那么，你在这里做什么，蛮锤能为你做什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30001, '你知道…你什么都不知道…我曾比你们所有人都更加强大。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30016, '起来死神已经宣告了我的离世，$r，我是索瓦提尔，埃尔德雷萨拉斯的奥术师和知识守护者。我将我的一部分灵魂和记忆放在了那本日志里，当你念出咒语时，你唤醒了它。不过我得提醒你，那可是会消耗你的生命力，不过并没有太多，我相信你会没事的。\n\n既然你现在是这本日志的主人，你也是我的主人，我的知识将与你分享，只要你让我感到有趣，并让我继续寻找更多的知识。请注意，其他人是看不到我的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30017, '这个箱子里好像有什么东西。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30018, '这里的码头？ 好吧，你可以搭上那艘曾经航行到暗夜精灵地方的船。 它叫什么名字？ 呃，我想是奥伯丁。\n\n是啊。 你最好试试暴风城港口。 至少我听说现在人们都从暴风城出发旅行。 我不太确定，我只是负责装卸货物。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30019, '当库奇还很小的时候，我就把他带上了船，一开始他充满敌意和怨恨，但通过那本书，你会发现我们已经建立了一种联系。 在某种程度上，库奇能够理解任何人，而无需真正知道他们在说什么。\n\n不知道该告诉你什么，伙计，库奇是我的朋友，我派你来结束他的生命，这可能是我迄今为止最大的遗憾。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30020, '我融合了猛虎的力量，我会获胜的，无论我在这个过程中获得多少新的伤痕！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30021, '看看我的货物吧。我是这个被圣光遗弃的小镇上最好的裁缝。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30030, '部落欢迎任何不适合其他地方的人。萨尔在考虑到巫毒部落与第二次部落的历史后欢迎了暗矛部族。我不能将他们，我的同类，留在沙漠中。\n\n我不是说他们现在就要加入部落，但我们会提供帮助。并且制止祖尔法拉克的疯狂。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30031, '我是沃金，森金的儿子。自从我们逃离暗矛岛的土地以来已经过了很长时间，在杜隆塔尔，我们在部落的陪伴下找到了新的家园和未来。\n\n我们部族坚韧不拔，无论河水如何流动，石头都不会变。远离巫毒，愿洛阿永远引领你的步伐，伙计。\n\n为了暗矛，为了部落！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30032, '这片沼泽里隐藏着很多秘密，只需要一双敏锐的眼睛就能寻找到。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30033, '这个鱼人小屋看起来已经被遗弃了，荒废不堪。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30034, '这个巢穴是空的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30036, '咳咳，我被告知要把这篇文章读给任何进一步询问的人听，有些可能没有意义，至少对我来说没有意义，所以我们开始吧……\n\n这里展示的艺术作品是由服务器上的玩家创作的，这是社区提供的一个平台，将来可以容纳更多，博物馆可能会根据作品的贡献而扩大或发展！我们要感谢每一个为此贡献或提交了如此出色艺术作品的人。\n~ 海龟工作人员”\n你看，这对我来说也没有多大意义。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30037, '北郡修道院确实是一个美好而安静的地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30038, '敌人已经临近，部落的兄弟姐妹们！响应战争的呼唤，击退那些胆敢挑战我们的敌人') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30039, '我们玛格兰人正陷入与敌人的战争中，我们以勇气闻名，不像居住在洞穴中的吉尔吉斯人…\n\n我是此地的可汗，你能为我做些什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30040, '<可汗用狂野的眼神盯着。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30041, '你有玛格兰的精神。喝。分享我们的血。变成玛格兰。变得强大。变成我们！\n\n<高大的可汗伸出一个装满凝结红色鲜血的骷髅酒杯。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30044, '我是沙卡，我统治着这里，我领导着吉尔吉斯部落，外来者，不要妄想傲慢，那是不明智的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30045, '你对吉尔吉斯的帮助比任何外人都多。 我们愿为您送上祝福，使你成为荣誉的吉尔基斯人！\n\n<高大的可汗伸出一只充满仪式感的碗，里面装着强大的香料。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30046, '可恶的部落败类！你们为世界带来了背叛和痛苦，你们将被从这个世界上消灭！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30047, '库尔提拉斯永远不会忘记你给艾泽拉斯带来的苦难……你永远不会知道和平……只要矛还矗立着……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30048, '你想要什么，小家伙？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30049, '你将受到永恒的诅咒！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30050, '要是他、他也爱我就好了……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30051, '\n一架看起来非常古老的古代锣。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30052, '一切都错了！伏击、袭击，甚至野生动植物也起来反抗了，那些该死的猴子从树上跳下来，攻击我的所有工人。\n\n我们在整个岛上建立了基地，进行可持续、有利可图的收获，但现在一切都变成了一团糟，都是因为一些猿猴和他们的国王名叫摩戈... 或者什么别的。\n\n我们人手不足，资源匮乏，急需帮助，所以别再问问题了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30063, '然而，莫尔森和伊斯顿这两个家庭之间存在着一些麻烦，比如可以追溯到上一代人的土地纠纷，他们之间的婚姻问题，谁拥有什么，哪些财产属于谁。\n\n莫尔森一家的想法是，他们将继承伊斯顿的遗产，尤其是一个年轻的孩子，名叫卡佛，是一个问题少年，给自己惹上了各种各样的麻烦。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30064, '就在这个时候，暴徒们开始出现，男孩卡弗很快也加入了他们的行列。 迪菲亚兄弟会以暴力和谋杀行为威胁家庭离开他们的土地。\n\n伊斯顿家族被冷血谋杀后不久，许多其他家庭就干脆离开了，因为他们不想面对类似的命运。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30065, '人数越来越少来参加我的教堂，我有一小群追随者，但迪菲亚兄弟会的存在变得越来越明显，他们威胁我离开，甚至因为我拒绝而将我打得半死。我很顽固，但不至于固执到要死。所以我前往了暴风城，我的故事现在在那里继续。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30066, '我...我应该解释一下。是的，我一直在欺骗你们。我和法拉德以及一些地精机器的帮助制造了这些魔像。多年前，我们就住在这里，月溪镇。\n\n我们只是想离开这个烂摊子。所以我们制造了收割魔像，帮助农民，还有，赚点他们的钱。但我们知道普通农民买一个太贵了。所以我们以很低的价格出售。我们在这上面亏了很多钱。\n\n\n\n\n') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30067, '你可能已经猜到了接下来会发生什么。我对这部分并不自豪。有个条件。当每个人的田地都被魔像保护时，我们会启动它们的真正本性。\n\n它们会变成杀人的机器。我们会把它归咎于某个邪恶的术士，或者其他人，不重要。唯一重要的是，我们是唯一能够以非常高的价格修复它们的人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30068, '至少，那是最初的想法。出于我的贪婪，我在法拉德在车间里与一些魔像一起工作时启动了杀人的开关。我希望他死了，这样所有的钱就会进我的口袋。\n\n后来我得知他活下来了，只是失去了视力。他对我充满了仇恨。但无论如何，我看到了我造成的破坏。我想让魔像再次变得温顺……但是我们的法术没有起作用。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30069, '在建造过程中我们犯了一些错误，或者只是技能不足，我永远不会知道。我不能修复它们。西部荒野变成了一片废墟。然后，达菲尔出现了，法拉德站在他们一边。\n\n你知道这个故事的其余部分。 你可能会评判我，认为我是一个怪物。 事实是，你可能是对的。 我是一个怪物。 但我已尽我所能来解决它。 以圣光之名，我只能希望这已经足够了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30071, '我会解释一下情况。我是卡莱德拉·黎明之风，曾在第二次战争期间担任远行者的游侠队长，但现在只是暴风城的一名市民。在失去奎尔萨拉斯之后，我们的人民因为对魔法的沉迷而遭受了深重的打击。\n\n我们中的一些人，由我们的前王子凯尔萨斯领导，被黑暗魔法所诱惑，据我听说，他们背叛了联盟，与被称为纳迦的生物结盟。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30075, '换句话说，这是我们应对魔法成瘾的一种方法。 水晶不会永远存在，但它可以为我们赢得时间来寻找治疗方法。\n\n我们的侦察员已经成功找到了该地点，并且他们确认该地点适合居住。 我们的人民已经开始在这个前哨基地定居，他们将其命名为阿拉萨拉斯（Alah\'Thalas），我们语言中的光之地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30076, '然而，这些建筑年代久远，没有得到妥善维护。 我们缺乏试剂和材料来维持保护前哨站的结界。\n\n同样，当地的矿井也充满了生物。 换句话说，我们将非常感谢您提供的任何帮助！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30077, '阿莉安娜？ 啊，我明白了。 她应该亲自来看看！ 我当然会帮忙。$B$B 告诉她这一切都与外表和举止有关：与初出茅庐的孩子说话，不是作为父母，不是作为主人，而是作为朋友和平等的人。 他们会尊重这种做法，只有赢得他们的尊重，她才有希望弥合他们之间的差距。$B$B记住，他们仍然是野生生物。 他们按照自己的意愿向我们提供力量和服务，而不是因为我们驯服了他们或要求他们这样做。$B$B请将此建议返回给艾莉，如果你也能告诉她...晚上我经常还会亲吻她的信，她真的应该有一天私下来看望我，接受私人辅导。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30078, '是的，几个月前阿莉安娜确实写信给我表达了她的担忧。 这些月羽族人受到了祝福，因为它们拥有与艾露恩最喜爱的生物交流的天赋，而艾露恩的生物也对他们充满敬意。 $B$B嗯...如果他们不承认她或她的话，也许她还没有赢得森林的尊重。 雏龙们会知道她是否是他们凭本能选择的人之一。 我已经很久没有去过我们出生的森林了，但我确信一定有一位森林之王或族长会判断她是否配得上这份尊荣。$B$B也许她应该去找一个这样的生物，赢得它们的青睐。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30079, '噢，我的天，太糟糕了！$B$B阿莉安娜是月羽族人，是吗？ 我完全相信她会找到最适合她的方法。 每个大师处理角鹰兽的方式都不同，因为这是一种非常个人化的做法。$B$B 也就是说，我听说我们神圣森林的东部地区正像北部一样遭到破坏。 我向她表示哀悼，并愿艾露恩赐予她力量。 也许休息一下放松心情会有所帮助。$B$B 毕竟，无法在内心不宁的情况下安抚一只野兽。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30114, '一个旧杠杆，底部刻有以下字母$B$B\'备用泵杆。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30136, '好的，好的！老大，随便你说什么！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30137, '求你了，不要！我有金币，我可以给……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30175, '珠宝加工') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Jewelcrafting
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30176, '你在那里做什么？你对格里兹比做了什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What are you doing there? What did you do to Grizzby?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30177, '没人能就这么离开风险投资公司！他们都是贸易联军的叛徒！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Nobody just simply leaves the Venture Co.! They are all traitors to the Trade Coalition!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30178, '小心这件物品所蕴含的危险。光是携带它就有风险。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Beware of the danger this item holds. Just carrying it is a risk.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30179, '你就是萨蕾莎吗？把大法师的聚焦宝珠给我，然后回塔里去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Are you Tharessa? Give me the archmage’s focus orb and return to the tower.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30181, '基座上散发着一股诱人的灵气。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The pedestal gives off an alluring aura.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30182, '把水晶和宝珠放到基座上。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Place the crystals and orb on the pedestal.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30184, '从地底渗出的原始力量强得惊人。要不是我知道底细，我会说这片土地里塞满了魔法，快要漫出来了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30186, '你其他的族人发生了什么事？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What happened to your other tribesmen?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30188, '你发现了什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What did you uncover?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30190, '然后呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- And then?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30192, '继续。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Continue.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30194, '裂隙行者，把你的故事讲给我听。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Riftwalker, share your story with me.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30195, '你上气不接下气，发生什么事了？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- You are out of breath, what has happened?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30196, '＜卡斯塔尔派我来的，他担心你族人的安危！＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Kas’tal sends me, he fears for the safety of your people!>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30227, '你想从我这里得到什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What is it that you want from me?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30250, '火焰燃烧出骇人的绿色，一股奇异的魔法在它周围徘徊不去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The fire burns an ominous green, a strange magic lingers in the air around it.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30257, '萨克戈斯能教你什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What lesson could Sakgoth teach you?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30261, '正确。克兰诺克能教你什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Correct. What lesson could Klannoc teach you?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30265, '正确。卡法伊能教你什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Correct. What lesson could Ka’fai teach you?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30269, '很好，看来你听得很仔细。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Excellent, it seems you listened well.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30270, '不对。我建议你下次听得更专心些。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Incorrect. I suggest you listen more intently next time.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (30277, '这咸腥的空气让我神清气爽。有什么能为你效劳的？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The salty air invigorates me everso. How can I help you?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (40049, '我只向最出色的冠军出售我的商品，你认为观众喜欢你到什么程度？\n\n如果是这样，请上前一步；如果不是，请离开，伙计！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (41028, '我敢打赌，你绝不会预料到在这片荒凉的沼泽中会找到新鲜的食材和饮料。你几乎无法受到责备。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (41084, '狂爪阿尔法注意到强大而令人恐惧的科拉克的鲜血从你身上滴落，并畏缩屈服。\n\n看来你已经成为这个阵营的新阿尔法了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (41085, '<低吼>\n\n这个豺狼人看起来不够聪明，无法理解你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (47024, '投资贝壳币可以改变您的生活。 它改变了我的。 我曾经是一个被社会抛弃的人，因为我是混血儿而被社会排斥。 没有人会给我机会证明我的价值。 我作为一名简单的金矿苦工，一直辛苦工作，直到有一天我遇到了马洛斯·卡托斯并成为他的同事。\n\n您也可以通过投资自己的未来来掌控自己的命运。 你准备好了吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (47025, '你好，未来的合作伙伴！ 在奥格瑞玛看到侏儒感到惊讶吗？\n\n好吧，别这样！ 我们都是贝壳币公司的朋友。你看，世界分为两种人。\n\n不，我不是指联盟和部落。 这是人为的划分。 我说的是我们，有远见的企业家，还有可怜无知的老百姓。\n\n你是我们中的一员，对吧？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (47030, '你呀，我看你是来壳牌贸易公司了！\n\n一种新的货币已经传入奥格瑞玛的耳朵，它正在席卷人类。 这是一枚将永远改变艾泽拉斯的神奇硬币。 是时候投资你的战利品了，年轻人。\n\n看看我，我曾经是一个可怜的德鲁伊，一无所有，现在我是贝壳币的最大股东之一。 尽早投资，您将获得意想不到的回报。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (47031, '嘿，$n！ 您考虑过投资贝壳币吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (50000, '我们是古老的树人：曾经守护这片伟大森林的存在。\n\n在一万年前，当阿克蒙德和燃烧军团进军海加尔山时，我们的肉体被摧毁。\n\n然而，我们的灵魂依然完整。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (50041, '没有什么比修复你们这些破烂的肉体更让人愉快的了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (50590, '时间就是金钱，而我们总是缺钱，因为有太多东西需要炸毁，而你的钱总是只有这么多。 至少我们因为炸毁东西而得到报酬，不像一些“发明家”。 哈哈！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (50591, '侏儒这个...侏儒那个...我们在开始学步之前就学会了如何炸东西，哈！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51670, '头发要剪，硬币要数。\n地精忙碌的生活。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51671, '你的长相可能只有母亲会喜欢，我有一个完美的解决办法！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51673, '欢迎来到时间之穴，$N。\n\n由于您已经做过或将要做的事情，您已被授予进入许可。\n\n时光之穴是我的人民青铜龙军团的家园。 我们是时间的守护者，我们的家也因此与时间流相连。\n\n别搞错了，凡人，这个地方不是用来度假的。 如果你走上邪路，就永远无法离开。 在洞穴中，您要严格遵守我们的规则和指示。\n\n如果你明白的话我会将你传送进去，但记住，我们可以在你做什么之前看到你打算做什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51674, '通往时光之穴的道路漫长二艰辛。也许我可以减轻你的负担，带你深入时光之穴。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51680, '看来这个矮人不仅被杀，而且还被肢解，下巴不见了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51681, '罐子是空的，里面的东西很可能被倒在似乎还在燃烧的东西上。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51682, '你现在可以确定，新兵们就是屠杀这些矮人的凶手。\n\n然而，失踪的下巴是令你怀疑的地方，你下一个想法可能是询问位于你所在地以南的交叉路口的那个地精，是否是他卖给他们这种油。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51684, '他们会对我做什么？对于我所做的一切，我感到非常抱歉，真的。\n\n我为所有这些都感到后悔，如果有机会，我肯定会弥补过错。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51685, '求你了，别杀我，求你了！\n\n其他的我就不知道了，请教！ 我只是想回家。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51690, '你就是瓦里玛萨斯勋爵为了这项重要使命而提到的那个人吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51691, '马弗里克似乎正处于沉睡之中，任何事情都无法唤醒他。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51692, '这里有人丢失了有价值的东西吗？我可以退货，但要付出一定的代价...') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51693, '对你来说可能是垃圾，但对我来说不是！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (51694, '哦，看看这个，是传说中的“垃圾使者”之剑。而且还是完好无损的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60010, '欢迎来到战歌前锋的家园。\n\n你一定很疲倦，为了荣耀部落和我们的战争努力是让人口渴的工作。\n\n稍作休息，让你的身体得以恢复。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60011, '并不是你的言辞赋予你分量，我的朋友，而是你的行动赋予你分量。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60012, '驻扎在这里?没有比这更大的荣誉了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60015, '你好！我是猎人阿姆罗·德·卢克斯，非凡的猎人，随时为您效劳。\n\n当老板四处奔波，从事更刺激的工作时，总得有人留下来处理工作中的乏味部分。\n\n那么，我是做什么的？当然是管理整个行动。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60016, '欢迎你，疲惫的旅行者！\n\n这次你会选择什么令你心安的享受？喝酒？闲聊？冒险？\n\n怎么了？\n\n我是法师，我负责提供饮料！ 不要告诉任何人，但这是我听说过的最轻松的赚钱方式。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60017, '什么？\n\n当然了，"莫吉"并不是我的真名... 只有老板知道。\n\n而且有很充分的理由。现在停止你的询问，在别的地方找点事做吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60305, '＜瑟格伦的目光凝视着你，仿佛要刺穿你的灵魂。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Thegren’s features stare toward you, piercing your soul.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60314, '如果你帮我净化月光井，报复食人魔，我们就可以喝点水。我会把你的案子交给女祭司本人。\n\n在姐妹会和哨兵的监督下，我不明白为什么我们不能尝试引导一些奎尔多雷回到女神温暖的怀抱中。即使他们选择拒绝女神，靠近水应该最终帮助他们摆脱他们的疾病。然而，这可能需要数千年的时间。\n\n记住，奎尔多雷和我们一起生活了两千多年，但这并不足以让他们停止使用魔法。然而，现代的奎尔多雷人与我们任性的亲戚是不同的人。不管怎样，这就是我的提议。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60315, '灿烂！ 然后在井边与我会合并做好准备，这不是一件容易的事。 如果你失败了，我们不得不撤退，我将准备再次尝试。 我会在井边放一碗圣水，你到了我就会到。\n\n净化会引起野兽的注意，所以不要犹豫，战斗吧！ 如果他们伤害了我，净化也会失败，保佑我！ 愿艾露恩指引我们。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60316, '咕噜咕噜……叫斯纳尔斯·影爪。 如果你需要杀戮，工作是好的。 浑水公司接受合同去做别人不喜欢做的工作。 你想要杀死一些东西，那么你来对地方了。 拿着一袋金子去问...') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60350, '你将在吉尔尼斯的力量面前死去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60446, '一股强大的力量潜藏其中，我打算与之抗衡。那些冤枉了我的人将付出最终代价，我会确保他们受到痛苦的折磨。你将是帮助我的人，或许我会为你的努力给予回报。\n\n好了，随意自在，有很多事情要做，也有很多事情要讨论。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60471, '森林的美丽是无与伦比的，风穿过树木，月光点缀着大地。然而，在这一切之下，有一种黑暗在潜伏，在这一切的面纱下隐藏着。这个地方曾经充满了生机和和谐，但现在有更多的掠食者，我们数不清，而我们在森林中的盟友已经变成了四处游荡的暴徒。\n\n你能感觉到吗，仿佛你随时可以从梦中醒来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60472, '灰谷正变得越来越危险。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60474, '欢迎来到达纳苏斯，泰达希尔的皇冠明珠。$B$B这座城市是卡多雷的心灵之地，理由很充分。它的优雅和美丽反映了我们的文化，我们的传承。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60476, '你怎么会来到这么远的地方，$R？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60477, '舒适点吧，这里的火坑很暖和，你也会感到温暖的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60478, '我们莫卢格族在这里已经待了很长时间，而且我们将继续留在这里！只因为其他人认为他们可以欺负我们，并不代表什么！在克鲁克祖格领主的带领下，我们可以在岛上做任何想做的事情。\n\n我们比所有人都更强大，我们很快就会把他们推到一边！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60503, '我感受到你身上有些不同寻常的东西。也许我们会再次相见，但在那之前，请让我专心工作，我有很多事情要做，不想被打扰。\n\n除非你是在找死，凡人，如果是这样的话，我可以满足你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60528, '我的家人曾经把洛丹伦称为家，呵呵，不管你信不信。 有价值的钱可以从矿石和珠宝加工中赚到，我们石怒多年前就已经知道了！ 众所周知，我家族的遗产只剩下闷烧的废墟、成堆的石头和烧焦的木头，更不用说尸体了！\n\n如果我要为什么而奋斗，那就在这里吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60529, '欢迎来到圣光之地，随意自在，只要你没有被亡灵的瘟疫或狂热的瘟疫所污染。\n\n占据这个地区的血色十字军对所有事物都充满了狂热的嗜血之情，无论是活着还是死去。他们把周围的世界视为敌对，一旦真正的光芒再次闪耀，他们就需要被镇压。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60530, '你好，这里的许多人都有充分的理由来到边境，我只是希望你的理由有意义。\n\n有趣的是，洛丹伦没有受到亡灵的控制，即使统治这片土地的人们像天灾一样邪恶。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60531, '嗯，你对我们更友好，甚至我们的战友也不愿意过来跟我们交谈。\n\n我以为我们会被奉为英雄，或者至少会受到欢迎，但在代表十字军远征北方后幸存下来的我们却被当作恶棍对待。 令我感到恶心的是，有多少人为了与亡灵战斗而牺牲，只是为了让事情像这里一样分崩离析。\n\n不管怎样，为我的无礼道歉。我是哈罗德森船长，来自血色舰队的“烈潮号”，或者至少是剩下的部分，经过那场注定要失败的远征后，一切都变成了这个样子。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60532, '在所有成功返回的船只中，我们是唯一的一艘，你相信运气吗？... 哈！\n\n有比我更好的人，说实话，在经历了北方发生的一切之后，我什至不想待在这里。 快把我扔到水里吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60538, '我是一位经验丰富的双足飞龙训练师，$c。 牛头人和兽人将他们从石爪鹰身女妖手中解放出来的感觉就像是昨天一样。 从那时起他们就一直是部落忠实的朋友。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60539, '鬃毛会咆哮，好像它会注视着你，但不会攻击。 这头野兽似乎在地面上很无聊，也许吃点零食就能说服鬃毛作为它的骑手与你一起飞行') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60540, '嗯，我们很少见到外人！ 来吧，躲起来吧，冬天肯定会很严酷！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60541, '哇，你是谁？你是因纳库克要去南部土地看望的人之一吗？！\n\n你来这里很幸运，许多人前来坎奎努恩看那个在天空飞舞的光辉灵魂，也许你也会看到它！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60607, '我走遍了很远的地方，寻找一种强大的噼啪声的伟大魔法。 我从奥格瑞玛一路就感受到了它的力量，而且我必须了解更多。\n\n  毫无疑问，它来自附近的卡拉赞塔，因为其中隐约可见的东西对所有必须揭开的谜团来说都是一个谜。 我需要你的帮助，也许你愿意提供帮助？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60624, '我和我兄弟特萨克经营着这条飞艇航线！我们肯定需要一些新零件来修理这艘飞艇，但穿越荒芜之地的旅程一直很紧张！这艘飞艇通往奥格瑞玛，返回部落的中心地带。\n\n齐柏林飞艇来的时候要小心，这可能是千钧一发!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60625, '嘿，这艘老旧的锈斑飞艇的操控性并不是最好的。该死，将它驾驶穿越荒芜之地那崎岖的地形真是够困难的，但迄今为止，它还算能应付得过来！如果你正在寻找通往卡加斯的快速船票，那么没有比乘坐这艘老女孩更好的路线了，这架飞艇绝对是个可靠的伙伴！\n\n哦，还有别在颠簸的旅途中介意，它需要一些新的零件，而且不能很好地停下来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60627, '杜隆塔尔是一个又热又闷热的地方，毫无疑问，我很高兴被派往雷霆崖，这里有凉爽的微风和美丽的景色！\n\n如果您想去奥格瑞玛，这艘飞艇将会在城市外停下。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60628, '哦，有什么我可以帮助你的吗？除非你正在寻求奥术知识，否则我可能无法提供帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60629, '我们矮人法师属于“蔚石教团”，很久以前，当铁炉堡的洞穴被开采时，我们发现了一块古老而具有强大魔力的石头。这块石头被达拉然的法师们研究过，自从那一天以来，就一直在我们手中保管着。\n\n正是因为这块石头，许多最早的矮人法师在奥术领域中获得了立足之地。如果你看到我们的同族天生具有魔法天赋，可以引导他们到这里来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60636, '欢迎来到南辉贸易公司，朋友!你是来谈生意的吗?如果你需要运输什么东西，我们一流的商队会为你提供服务。\n\n还是你带了太多的金币，担心有些无赖会追上你？没问题，我们有训练有素的猛男保护你!或者你在寻找来自南海的异域商品?只要有钱，我们都能帮你买到，我保证!\n\n南辉贸易公司-你有金币，我们需要它！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60640, '愤怒之手是一支由执行官罗赛特率领的军事部队。它是部落的铁腕，粉碎敌人。愤怒之手服侍着大酋长和部落各种族的领袖。\n\n它是在黑暗女王的命令下，由被遗忘者先锋队创建的，旨在通过战争的烈火中，为部落各个种族之间锻造兄弟情谊。如果你想加入或者与我们有些业务，我们的军官们就在隧道尽头。如果不是，那就别再浪费我的时间。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60643, '别碰我的货物，伙计！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60645, '欢迎来到金月马戏团，金月巡回剧团的家园。\n\n在我们的神奇表演和诡计中尽情享受，但要小心我们不对可能发生在你身上的燃烧、窒息、溺水、金钱损失、失去身体或失去理智负责。\n\n感谢您的光临，祝您度过愉快的一天。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60648, '你好。\n\n在这个世界中，我被称为奥隆（Olom），是在不同位面之间徘徊的旅行者。您似乎是一个新面孔……如果我没有弄错的话？\n\n在我作为一名年轻的兽人时，我成功摆脱了我的恶魔主人。在经过多年之后发现还有其他人同样反抗军团，让我感到非常高兴。看到新一代术士以不同的方式出现，拥有不同的观点，让我感到欣慰。\n皮普南向我们汇报了许多令人不安的事件。因此，我们必须为潜在的挑战做好准备，正如我们的名字所暗示的那样。\n\n我们是艾瑞达·毁灭者。 末日卫士。\n\n欢迎加入我们。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60656, '我所拥有的一切：愤怒、残忍、复仇、死亡和腐朽，我将赐予那些接受亡灵冰冷拥抱的人。\n\n现在注视眼前的土地。\n\n血色十字军急于破坏我所做的一切，而光之希望对抗我们，因为他们只是瘟疫之地上的瑕疵。\n\n他们必须付出反抗的代价。\n\n你所踏之处，荒芜将随之而来。\n\n现在前去，以耐奥祖和巫妖王的名义夺取这些土地。所有人，都必须死！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60660, '这所学院并不总是奎尔多雷的，它的起源比游侠领主龙行者所知的还要古老。 上古之战结束后，许多狼人不幸从艾露恩之镰中被释放，仍然在卡利姆多的森林中漫步。 恶魔和萨特也同样猖獗，无辜者不断被杀戮。 勇敢的哨兵和上层精灵巫师都抛开了分歧，创建了一个新的战士组织来消灭夜行的邪恶怪物。 “Thero\'anir”在你们的语言中称为“龙鹰”它们被注入了龙血，以匹配他们敌人的凶猛。\n\n可悲的是，最初的Thero\'anir只剩下赛达斯和我了。 或许随着游侠领主刀歌的复兴，学院将再次达到顶峰。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60661, '欢迎，朋友！\n\n这个神圣的地方是艾泽拉斯的大螯龟之家，他们是部落和联盟的守护者，元素的执行者，屠龙者和诸神的杀手。\n\n这是我们的家，家就是心所在。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60662, '什么？ 你不认识这些黑色横幅吗？ 连我活着的时候都害怕牙齿！ 咧嘴笑者服务于真正的大酋长黑手。 他派我们去开辟一条对抗暴风城的新战线。 鲁格大佬知道沼泽中需要每一把剑，甚至是黑暗部落的剑。 在杜隆塔尔，和平酋长的骄傲可能压倒一切，但你现在已经在艾泽拉斯的腋下了，混蛋。 而我们比泥沼还卑鄙。 你回家的时候别再提我们了，好吗？\n\n<他现在似乎在自言自语。>\n\n他们就是不让我死……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60668, '洛克塔奥加尔！\n\n在这个营地里，无论你来自哪个部落，我们都不会互相残杀。我们在这里疗伤休息。\n\n为了迎接即将到来的下一场战斗，与那些粉色皮肤的敌人。\n\n经历血、火和死亡！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60670, '很高兴你能加入我们！在夏兰蒂斯岛上，我们无法预测会有什么等待着我们，但我们不能辜负我们的新盟友。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60700, '在上一场战争的创伤之后，我找到了自己的使命，就是准备我所能提供的最美味的餐食。\n\n在返回工作之前，来享用一顿丰盛的餐点吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60702, '每个人都想知道我的酿造秘诀，但这是我无法教授的东西。\n\n几年前，我从一个骑在海龟上的古怪人那里学到的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60703, '每天都来这里吃饭真的很不方便，但我就是无法抵挡萨恩的酿酒技艺。\n\n你见过南泰工作吗？我可以整天都看他做那些。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60704, '<她兴奋地拍了拍你的脸，然后狂笑起来。>\n\n在这个庄园周围小心行走！ 周围有很多可疑的类型，连花都害怕了！\n\n你能听到他们的声音吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60710, '邪恶的黑暗侵蚀着这片土地，并且变得越来越强大。 我们有责任阻止恶魔的污染。\n\n你有能力追踪恶魔并将其从世界上赶走吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60727, '欢迎来到塞拉摩，让自己轻松自在。 我是布林上校，塞拉摩防御指挥官。\n\n我们一直在寻找一双勇敢的手。 如果您正在找工作，也许您可以为塞拉摩卫队提供帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60728, '总得有人来维护这座灯塔的运转，而我想那个人就是我。\n\n我有很多工作要做，你需要什么吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60749, '那么，你来自部落，对吗？\n\n我叫塔扎戈，曾经作为乌克兹·沙顶的冠军而战斗过，但那些时光早已过去，朋友。\n\n沙怒部族已经四分五裂，我感到失望。在我们离开之前，还有其他人离开了。在我们离开后不久，祖尔法拉克就变成了一座被遗弃的废墟，充满了邪恶和诅咒。\n\n也许你能帮助我们，因为我们需要帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60753, '欢迎来到沙月村，这个地方由塔扎戈领导，他是这里的领袖，我会毫不犹豫地跟随他到地球的尽头，朋友。\n\n如果有人能够恢复我们失去的荣誉，那就是他。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60754, '在塔纳利斯要小心，对外来者来说，那是一个严酷的地方，缺乏水源。\n\n太阳本身已经让我们中最强大的人枯萎，不要认为自己对于高温是不死之身。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60759, '我们在这里的使命极为重要。黑暗之门充满了邪能能量，谁知道它是否还在运作。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60760, '我讨厌食人魔。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60761, '我是贾伊穆，泰伊穆之子。朋友，你需要什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60762, '我精通古老的制作方法，也许你需要修理一下，让我可以提升我的技艺。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60763, '黑暗魔法在战斗中助我们一臂之力，赋予我们力量。流淌在我们血脉中的血之狂怒是一种资源，可以通过我所召唤的力量来激发和增强。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60764, '总是有更黑暗的力量在发挥作用，千万不要认为自己足够聪明以避开它们的诡计，要保持警惕，因为你永远不知道是谁，或者什么可能在观察着你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60765, '我曾跨越许多战场，击败过许多敌人，但现在我才感到对前方的情况要保持谨慎。我对卡芳毫不保留地信任，但我不确定我们是否与世界各地的这个"新部落"拥有相同的价值观。\n\n也许这真的是最好的选择，也许这可能导致我们的崩溃，只有时间会告诉我们。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60766, '外来者，你在寻找什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60769, '你想要什么，难道你看不出我正在忙着照顾幼龙吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60770, '我叫卡芳，我是这里的领袖。\n\n我的人民不会对你造成伤害，除非你侮辱了他们，或者过于打扰他们。有许多事情需要讨论，许多事情需要我们去做，以在这个世界上确保我们的地位。\n\n黑石部落发现自己受到更强大的力量操纵。旧部落已经变成了曾经的一片残影，我不会允许我的人民跟随他们走向疯狂。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60772, '我是卡芳的议员，我就所有事务向他提供建议，无论是内部事务还是对外事务。\n\n也许你从这片焦土山谷之外带来了消息？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60773, '如果你需要，我们有啤酒，或者如果你需要食物，它会是什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60774, '你很幸运，我们在外人关系很好，管好你的嘴，别说坏话，我习惯于杀死部落之外的人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60775, '我负责训练座狼进行狩猎、杀戮和游荡。\n\n我负责培养我们最好的样本，以及最有用的盟友。那么，外来者，你想要什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60778, '\n握紧的拳头胜过百言千语。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60780, '嗨，欢迎来到利文斯通农舍，随意自在，只有一件事我要求，就是进屋前请在外面擦净你的脚！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60781, '这里周围有那么多该死的小动物，不断扰乱庄稼，让我们的生活更加艰难，然后......\n\n啊，抱歉，刚才有点发牢骚。有什么我可以为你效劳的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60788, '欢迎来到崇高广场，这是我们城市的一部分。不要放松警惕，尽管我们正在取得很大的进展，但一切都可能在几分钟内被摧毁。\n\n食人魔和辛迪加仍然潜伏在城市的其他地方，给我们造成了很多麻烦，所以在进出途中要保持警惕。\n\n那么，我能为你做些什么呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60791, '欢迎，我希望你能在这个地狱般的地方得到一些休息。\n\n这里是虚空之门要塞，是在黑暗之门打开并开始第一次战争多年前建立的。我们被派来监视它，并在出现魔法异常时进行报告。\n\n如果你看到任何异常的情况，请告诉我们。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60792, '我们在那里看到了各种各样的敌人，从食人魔到兽人，再到恶魔。他们变得足够大胆，最终会向我们发起进攻，只是时间的问题。\n\n当他们采取这样的行动时，我们将会做好充分的准备。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60793, '确保你不要在这里惹麻烦，我们已经有足够的问题要应对荒原中潜伏的恶魔扭曲的野兽。\n\n或者也许你是来这片前线提供帮助的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60794, '如此多的魔法波动，如此多的基因扭曲，这几乎让侏儒的脑袋因其中的可能性而眩晕！\n\n有研究要做，$R，有研究要做！\n\n哦，对了，我叫维格尔斯蒂普，是虚空之门的首席分析员，很高兴认识你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60795, '我在这些的石墙后面感到不安，我已经粉碎了太多的恶魔头骨，不能在这里虚度光阴。\n\n我叫哈古夫，我在这里待了很长时间了，我可以为你做些什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60799, '我们不是为了自豪或荣誉而参战。我们不关心联盟和部落之间的争斗。\n\n每一方都有自己的子孙，每个孩子都应该能够快乐地成长。\n\n他们想要保护这个世界，保护他们的子孙。\n\n所以，现在由你决定。如果你加入我们，拿着这只蝴蝶。它将停留在你的心里，也会在你的外袍上。然后你会开始理解。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60802, '你好，士兵。你是来抵御邪恶的黑龙军团吗？空气中弥漫着紧张感...我能感觉到。我们越接近击败这个龙军团的新领袖，我们就离重新感到安全越近。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60806, '在你的心中消除愤怒之前，你的成长将永远停滞不前。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60813, '愿你的旅途带你到有趣的地方，我可以为你做些什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60816, '欢迎来到红云高地，我们在这里为许多新的年轻飞龙做准备，让它们成为部落的忠诚伙伴。如果它们没有得到适当的训练，它们可能会变得难以控制和野蛮。\n\n如果你想看看它们可能变得多么凶猛，你可以在石爪山脉找到许多未被驯服的飞龙。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60817, '我已经在这里训练飞龙有一段时间了，确保它们保持原始本能的控制。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60818, '在这里是新手确实有其优势和劣势，至少我能向最优秀的人学习。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60822, '这些的刺背野猪人总是比我预料的强大，永远不要低估敌人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60823, '我们有责任确保这些灵魂过渡到彼岸世界。我们要看守着它们，将它们的记忆和经历代代相传。在某种程度上，我们是过去和现在的守护者。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60824, '无论你身在何处，你总是能感受到灵魂的存在，要知道你的祖先将引导前方的道路。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60825, '亲眼所见，才会相信。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60826, '不要害怕接下来会发生的事情，要为能与周围的人分享这个经历而欢欣鼓舞。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60827, '阿拉索长期以来一直与巨魔战斗，我们将成为结束这一切的人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60832, '我在影牙要塞里做了很多工作，想想这一切都毫无意义。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60833, '被放逐，你竟然相信这个？\n\n我曾经是影牙矿工工会的工头。多年来，我开凿了这座城市的隧道，结果这就是我得到的回报？他们说我能够在失败中幸存是幸运的。毫无疑问，他们期望我和我的团队会死在黑石那些混蛋手里。\n\n他们会为此付出代价的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60850, '有许多东西需要学习，还有很多智慧需要传承。\n\n我们这些被放逐者有很多东西可以教给这个世界的其他种族。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60851, '你好奇的表情告诉我你想知道我们是谁，或者我们在做什么...\n\n<魔网技师沃萨尔疲倦地叹了口气。>\n\n我们是萨拉斯联盟，一个崇高的组织，目标是帮助难民，我的族人，高等精灵，当然还有支持我们新的联盟盟友的一切。\n\n现在，请原谅我，我需要修复这个的水晶球，所以，除非你恰好是关于魔网或法力流的专家，去别的地方找点娱乐，不要浪费我的时间！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60854, '滚出我的小屋。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60855, '小心点，要塞军械库已经被攻陷了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60856, '塔纳利斯的呼啸风声对我低语，而我无法回应...这种迷失感真是奇怪。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60857, '随意自在地逗留在这里，这里有很多事情要做！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60858, '西部荒野，曾经是繁荣之地。如今，不过是一片荒芜之地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60859, '\n我很忙，朋友。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60860, '“你好，同志。我很高兴看到有人像你一样充满活力和热情。我曾经觉得自己还活着，现在我只不过是瓦砾，我不知道如何继续在这里。我有一种感觉，我在这个世界上已经转世了好几次。$B$B模糊的记忆来到我身边...一个箱子？小心！它充满了陷阱，这是自杀...我快溺水了，我想下辈子我会学会游泳......$B$B呵呵，我不知道那是什么，但我记得它，它让我不寒而栗。最好暂时把它留在那里......”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60862, '<尸体静止不动。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60863, '<你能感觉到你的祖先在凝视着你。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60864, '<你能感觉到你的祖先在凝视着你。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60865, '<你能感觉到你的祖先在凝视着你。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60869, '被安排在这里几乎是一种侮辱，你做错一件事情，然后就被送到边缘地带去处理问题...\n\n我猜总得有人去弄脏手。\n\n你是来找工作的吗？因为我们可以用一些帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60870, '各种各样的事情都在山脊线附近发生，保持警惕，你会看到黑铁矮人在周围活动。\n\n我在这里是为了找出他们在干什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60872, '铁炉堡很不错，但我有点怀念诺莫瑞根，它公正、舒适，并且在许多领域提供了各种进步，你知道吗？\n\n好吧，也许不是，但无论如何，也不全是坏事，仍然有一些事情需要弄清楚，还有一些谜团需要解决。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60873, '狼用害怕的眼神看着你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60874, '我希望你一切都好，你有什么需要吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60875, '两加三乘以四...你想要什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60877, '圣光守护着一切，不要忘记这一点。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60880, '自从格罗玛什·地狱咆哮死后，我们的部族就分散在卡利姆多各处，从灰谷一直到千针谷。\n\n如今，只有战歌突击队中最勇猛的领袖们还在被倾听。但总有一天，迟早……新的大酋长将会出现!是我们在几天内建造了奥格瑞玛。所有的公民都见证了部落真正的儿子们所做的一切!\n\n我们绝不会让那些肮脏的暗夜精灵继续他们无耻的破坏。\n\n战争没有尽头。只要永恒的游牧能统治整个卡利姆多。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60884, '看看是谁偶然发现了墙上的这个洞！ 你找到了我们的藏身处，那些想要致富或死去的人。 你有金币吗？ 我们会接受它。 你渴吗？ 里面有很多小桶。\n锻炼一下你的技能，或者只是无精打采地盯着墙壁，我们在这里不在乎。 凑合着，保持低调，直到他们停止寻找你，然后回到那里，找到你的财富！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60888, '啊!欢迎来到魔爪的基地!名字是希罗德华图。我是公会的历史学家。我知道它的所有历史!魔爪的目的是猎杀所有忠于天灾军团和燃烧军团的人。他们所有的领袖都遵循这个目标，从尼古拉斯·奥斯玛，一直到最后的已故的拉格纳·马格努斯。\n\n但是，让我告诉你们，堕落的领袖不会阻止魔爪猎杀艾泽拉斯所有的天灾兽和恶魔!现在魔爪由阿内斯特领导。他很笨，但他会学会的!你们将会看到。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60893, '你想加入银色十字军吗?那就出去做个有用的人吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60903, '欢迎来到壳牌贸易公司!\n\n我是个天才!我发明了一种全新的货币它将席卷艾泽拉斯!神奇的艾泽拉斯将永远改变我们交换商品的方式，每一枚硬币都是独一无二的，不可替代的。\n\n运气不好?现在是时候投资贝壳币了!关注市场，大赚一笔!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60916, '已经很久没有人敢来这个地方了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60917, '我的王国已化为尘埃，我的臣民早已不复存在，我的记忆也在消逝。 但我仍然留在这里，令人难以忘怀地提醒我曾经的伟大。 是什么让你来到了我被遗忘的国度？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60924, '很久以前，我们红标在三锤之战中与国王并肩作战。 我们拥有令人自豪的遗产，不应该被轻视。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60926, '我的工作是了解敌人并找到他们的弱点。\n\n我可以评论暴风城的许多缺陷，但这不是我来这里的原因。\n\n我能为你做什么，$R？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60927, '暴风城很友善地为我们提供了住宿和大使馆所在地。 我觉得这两个王国需要相当长的时间才能达成一致并站在一起。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60929, '控制水手和他们与海军之间的敌意可以很困难。\n\n这就是像我这样的下士要发挥作用的地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60930, '库尔提拉斯国家对其忠诚的臣民和那些宣誓效忠的人非常慷慨。\n\n我们的忠诚和奉献属于洛丹伦王国和旧联盟。\n\n你的忠诚在哪里？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60934, '我代表海军上将前来与我们的南方邻居进行外交接触。\n\n我一直很好奇这里的贵族是否忠于古老的传统，以及他们对北方已经倒下的姐妹王国的尊重。\n\n如果库尔提拉斯和暴风城要并肩而立，那么残酷的真相必须摆在所有人面前，以便直截了当地理解。\n\n与黑血部落不可能有停火，与那些摧毁了曾经的东西的人站在一起也不会有荣耀。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60935, '我很少有机会与外地人交谈。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60936, '海洋是严酷的，充满了秘密。我们还有更多的地方要探索，更多的远征需要在地图上标注出来。\n\n你们可以相信我们会找到这个世界上未揭示的地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60938, '你站在库尔提拉斯的古老潮汐号船上，我是这里的船长。\n\n不要在船上给我惹麻烦，$C。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60939, '选择你想要兑换的任务奖励。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Select the quest reward you want to swap.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60945, '<幼龙好奇地看着你。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60946, '嗯嗯嗯？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60949, '我们守望。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60950, '哦，我愿意为一瓶达拉然红酒做任何事情...') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60951, '我讨厌这片沼泽。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60955, '这片沙漠充满了机会，有机会赚点钱。我代表一些海外的利益，他们正在寻找稀有和独特的商品。\n\n也许我们可以互相帮助，是吧？\n\n哦，还有，如果你想找点芝士，我有很多，他们把我的信字面理解得太严重了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60956, '您好，欢迎来到热砂艺术博物馆，让您宾至如归，欣赏来自社区的一些精美作品。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60960, '你能相信这运气吗，我们在这片树林里只有两台割碎机在工作，结果竟然都坏了！\n\n现在我被困在这里修理，几乎没有什么零件可言。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60961, '我从火花港被派到这里来照看这个地方，我们这里有很多项目正在进行中，我们技术人员确保所有零件保持正常工作。\n\n不管怎样，我可以为你做些什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60962, '哇哦，你见过这么壮丽、这么美丽的东西吗？只要我们点燃导火线，这家伙就能在火花港大小的地方炸出一个大坑，而我的工作就是确保我们不会炸成碎片！\n\n哦，我迫不及待地期待着纳兹点头批准使用这个东西的那一天，这将是艾泽拉斯上最壮观的爆炸！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60964, '相信我，这是我最不希望来的地方，但是地精付钱很多，而且我在这里有生意。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60967, '走开，伙计，别让我生气。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60970, '你好，我有些问题需要解决，你看起来像是有能力解决问题的人。\n\n也许我们可以互相帮助，怎么样？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60972, '你帮助我们，是吗？泥爪看到你帮助我们解决了许多问题！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60973, '不要惹麻烦，不然我会砍你！\n\n我砍得好，我砍得最好！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60976, '你在那里，是的是的，我来自一个叫做湿地的沼泽地，你听说过是吗是吗？\n\n大领袖高尔弗朗曾经在这里待过，寻求帮助，但现在他正在争夺莫什德部落的领袖地位！\n\n我在这里是来帮助引导人们去找他的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60990, '总是有冒险可寻，尤其是在遥远的前沿地区。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60991, '欢迎！随意安逸。如果你需要休息，我们有充足的啤酒和住宿。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60993, '我从在铁炉堡服役的时候就认识怀特峰了。\n\n我相信他需要我的经验和专业知识，尤其是在离家这么远的地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60994, '\n我们处在敌对领土深处，几乎被敌人包围。最好保持警惕，随时准备战斗。\n\n你打算在巴尔哈杜尔这里帮助我们吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60997, '欢迎来到贝尔哈杜尔，这个地方是第三次战争时期留下的。\n\n在那段时间里，我们矮人为帮助联盟做出了贡献，与兽人和恶魔作战，直到统一和海加尔山之战。\n\n这个地方被遗弃了，我们最近才到达，为我们未来的探险称之为家。\n\n如果您愿意提供帮助，我们当然可以使用该帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (60998, '我是来自石爪峰的使者，也是一名向导，帮助白峰和他的亲属在不扰乱自然秩序的情况下穿越这些土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61000, '工程师的生活，我以为我会从事发明创造，但我大多数时间只是一个被吹嘘的机械师，帮助修复损坏的装置和机械。\n\n哦，不过至少我在使用工具。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61001, '你知道那块农田花了多长时间来施肥吗？！\n\n<矮人显然很生气。>\n\n所有的准备工作只是为了一些秃鹫来破坏一切。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61006, '天空在呼唤我的名字，但我却无法回应！\n\n该死的飞行器失事了，现在我和其他农民一样被禁足了。\n\n你知道旋翼式嘶嘶声发动机吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61008, '你好。有什么我可以帮助你的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61013, '南方其实还不错。好酒，还有机会伸展一下长途旅行中疲惫的海腿。\n\n我能为你做些什么，外地人？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61014, '<水手卡普温德好奇地看着你。>\n\n有什么你需要的，还是你只是对外域人的战袍感兴趣？\n\n以前没见过外域人吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61015, '这些钱都是我存起来的； 没有比现在更好的时间了，是吗？”\n\n<水手布鲁文笑了。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61016, '你最好退后，免得我们出现问题，明白吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61017, '库尔提拉斯的抱负和愿望是一件复杂的事情。我们在这里的目标是确定这些南方人的真正价值，看看外域人是否值得信任。\n\n如果暴风城的贵族能够证明自己忠于古老的方式和古老的目标，也许合作的未来是可能的。\n\n我们将看看暴风城的心在何处。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61019, '我在现实和虚幻之间游离，我害怕我不能久留，你必须在我彻底离开之前帮助我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61024, '懒鬼！全都是懒鬼！在我年轻的时候，有机会使用那种火力是一种特权。现在的小孩们...\n\n<纳兹将注意力转向了你。>\n\n嘿，小伙子。欢迎来到火药镇！是来休息的吗？那就留下来感受一下刺激吧！这些白痴“工程师”尼尔特提供的家伙随时可能让我们爆炸！\n\n不过，如果你愿意为了金币弄脏手的话，我这里有些工作可以做。你还有其他理由来火药镇吗？\n\n哦，别担心要发挥作用，只是留下来逛逛。你也不会是第一个。\n\n现在走开！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61026, '海浪冲击着岸边，战斗即将来临，你能感受到空气中的氛围吗，年轻人？\n\n我们的敌人竟然有胆量拒绝他们的力量，直接挑战部落的威严。\n\n战争在召唤我们，每个部落成员都需要回应，你会拿起战斧，捍卫家园吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61040, '<那名半人马女子威胁地盯着你，双臂交叉，尾巴摇摆。>\n\n你算什么东西，居然敢跟我说话？是瓦鲁格派你来的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61041, '<德克夏用狂野的目光盯着你。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61044, '<那位年迈的半人马抬起头与你交谈。>\n\n你并非我们部落的人，却在我们中间行走。你来这里有何事？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61045, '我们始终面临战争的威胁，我们必须为冲突做好准备，否则我们将像之前的许多部落一样被践踏。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61050, '<达隆对你的出现感到有些困惑。>\n\n我们很少有外来者，实际上已经很多年了。\n\n无论如何，欢迎你。你需要什么吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61051, '我能为您做些什么，$R？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61052, '\n小心点，伙计。\n\n你想要什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61053, '你用着睁开的双眼行走，$r，但你真正看到了吗？最近你是否花时间欣赏周围的世界？\n\n风中飘动的树叶，汹涌的海浪，城市里的繁忙节奏。你周围都是壮丽的景色，即使在战争时期也是如此，总有值得欣赏的事物。\n\n那么...要来一杯喝的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61064, '你好，肯瑞托欢迎所有愿意增长我们关于奥术知识的人。\n\n有什么我可以为你做的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61065, '工作总是不会断的，我们希望有一天达拉然能够完全恢复。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61070, '嗨，亲爱的，你看起来今天过得很艰难？来块薄荷糖怎么样？ 因为你的呼吸在为你歌唱！\n\n来吧，呆一会儿，把一切都告诉多萝西娅。\n\n嘿，亲爱的，你看起来今天过得很艰难。 薄荷怎么样？ 因为你的呼吸很臭！\n\n来吧，呆一会儿，告诉多萝西娅一切') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61100, '嗯，多一点残留物与根部混合可能会......也许会改变树本身的生长-\n\n你没看到我有点忙吗？我即将取得重大突破，你没看到吗？\n\n巨型香蕉的秘密就在我的指尖，除非你是来帮忙的，否则请让我继续。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61101, 'Y您肯定在很远的地方，如果您被派到这里，我们深表歉意；如果您自愿来到这里，欢迎您！\n\n我叫比克斯，管理这个仓库已经有一段时间了。 不久前这里曾经是香蕉采集的主要地点之一，但现在一切都变了。\n\n猿、猴子和蛇造成了各种各样的问题，但我不需要告诉你，你现在已经见过它们了！\n\n也许你可以帮助我们解决这里的一些问题，我们当然需要帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61102, '你是那些冒险家之一吗？如果是的话，你正是我在找的人。我们遇到了很多问题，一切都崩溃了。 我死去的员工比香蕉还多，你明白吗？！\n\n<巴隆·特拉兹稍作停顿，清了清嗓子。>\n\n抱歉，一个地精在失去这么多资本和金子的时候会感到非常沮丧，时间就是金钱，但在特尔阿比姆，时间等于是在亏钱。\n\n这样的灾难必须被扭转，否则这里所有的投资都会化为乌有，我告诉你，地精的价值如同他的黄金，我可不打算带着几个香蕉回到科赞。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61106, '嗯，伙计，你离营地确实有些远了，现在不是每个人都会走到仓库这里来。\n\n我希望你不是被派来处理这个堆积如山的粪坑的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61108, '地精机械，错综复杂的零件和杂乱的设计。这无疑会导致严重的故障，正是这些故障让像我这样的工程师有了生意。\n\n那么，你要办点什么事？\n\n你最好不是来修理粉碎机的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61109, '太阳真的很热，不是吗？我负责这里的水和饮料，所以你应该表现得很好，明白吗？\n\n否则的话，你就只能喝海水了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61110, '欢迎来到特尔公司营地的旅馆，我们没有猴子，价格非常实惠，请放心入住。\n\n另外，我想澄清一些流传的谣言。这里没有发生过猴子袭击事件，完全没有。一群流浪的猴子并没有在深夜闯入，制造骚动并袭击无辜的顾客。\n\n但如果真的发生了，我们提供一晚免费住宿。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61112, '听着，伙计，有时候你需要跳出固定思维。我在棘齿城的日子大多都在处理乏味的陆行鸟肉，如果我想在科赞成为一个大人物，我就得用点创新。\n\n一个地精最好的特质就是狡猾和思考，你懂吗？一个聪明的大脑需要伟大的创意，而什么比泰阿毕姆更适合突破传统思维呢？香蕉才是关键，我告诉你，只需恰到好处的调味，适宜的配料，就会大受欢迎。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61121, '欢迎来到冰爪村。在这片土地上，其他人会以友善的态度对待你。\n\n让我们一起享受这个冬幕节，并可能分享一些外来的食物，好吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61122, '雪是新鲜的，空气很凉爽。对于我们冰爪部落来说，现在是开始庆祝活动，庆祝又一年的结束的时候了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61125, '我希望其他人会喜欢我的礼物！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61126, '你是猴子的朋友，也是伊布的朋友？伊布喜欢朋友，你帮忙，对吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61137, '我必须承认，我没有预料到有客人来访。事实上，我就是为了这个原因才决定在这里生活的，我喜欢现在一个人呆着，因为我见过很多。已经有很长一段时间没有人来打扰我了，你是怎么来到我这个隐藏在山里的孤寂住所的呢？\n\n如果你是为了要钱而来，我提前向你道歉，我没有。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61142, '森林之歌的紧张局势正在加剧，我感觉事情只是时间问题，很快就会失控。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61143, '嗨，外来者，欢迎来到森林之歌。\n\n这个地方曾经是我们过去宁静的林地，不过现在只剩下废墟了。我们在这里努力维护这片地区，抵制战歌氏族在我们神圣的森林中扩大势力。他们有很强的韧性和活力，特别是对于绿皮族，必须结束他们。\n\n也许你可以帮助我们，因为我们内外都有许多问题。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61145, '这片神圣的森林渴望远离那些不断侵蚀它根基的外部力量。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61146, '卡多雷为我提供了庇护，我在这里生活了很长时间，来自大自然的额外保护是一种热烈的欢迎。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61147, '外来者，你好。\n\n在第三次战争之前，这片林地曾受到许多德鲁伊的崇敬，我们在这里与大自然以及森林本身的精灵交流。最近，兽人扰乱了这片避难之地，现在我们肩负起恢复这个地方的重担。\n\n毫无疑问，你肯定看到了哨兵在周围，他们也在最近加剧了森林之歌这个越来越令人头疼的问题。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61149, '朋友，你站在一位伟大的森林英雄面前，请不要不尊重你所踏足的土地。在我们面前的树人艾思维尔为费伍德的伟大利益而献身。你可以看到周围的绿意和生机，这真是一个奇迹，特别是在这些受诅咒的土地上。\n\n也许我们可以更多地了解他的秘密，并解锁森林本身的净化，这就是我来到这里的原因。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61150, '这片土地并不总是这个样子，过去森林周围有许多区域和城镇。\n\n看到这个地方变成了什么样子真是可惜，不久前恶魔入侵的腐败已经让这片土地伤痕累累，我们必须竭尽全力与之抗争。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61151, '荒野是不是很迷人？大自然一直是一个神秘的守护者，有许多秘密等待我们去揭示和保护。\n\n我叫卡拉兰，朋友，你在这里寻找什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61157, '尼布好奇地看着你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61170, '父熊转过身来，看了你一会儿，然后开口说道：\n\n年轻人，这是可怕的时代，但要记住，在黑暗中总是有希望的。我已经给许多熊带来了帮助，然而还有很多被腐化所摧毁。在这片土地上要小心自己。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61171, '冬天老人用欣赏的目光凝视着你，但他的思绪显然集中在其他事情上。他以慈父般的目光催促你继续前行。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61172, '巨大的科多兽看着你片刻，然后用一种慈父般的语调说道：\n\n冬天即将来临，年轻人，你最好去找一个温暖的地方。我已经引导了几代部落，必须继续这么做。我现在必须离开，希望你能在黑暗中找到帮助，愿大地之母引导你走向更美好的草原。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61173, '洛克塔！祝你度过一个愉快的冬幕节，小朋友！\n\n这里有免费的食物和许多欢乐，都是由烟木牧场提供的！\n\n确保你玩得愉快……但你不能坐在我膝盖上。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61174, '不要惊慌，朋友。并不是所有霜鬃部族的人都在为战而来，我们是来这里庆祝的。\n\n我们中的一些人寻求和平。我们的部落遭受了很多苦难，我们只是来这里庆祝冬天伟大精神的丰收。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61175, '不要惊慌，朋友。并不是所有霜鬃部族的人都在为战而来，我们是来这里庆祝的。\n\n我们中的一些人寻求和平。我们的部落遭受了很多苦难，我们只是来这里庆祝冬天伟大精神的丰收。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61177, '亲爱的，朋友。你想听关于冬季伟大精神的故事吗？他引导着季节的到来，带来我们的时节。狩猎的时节，收获的时节。\n\n一旦时节来临，我们会举行庆祝活动。祭品、舞蹈、仪式和盛宴。我们庆祝生存，庆祝季节的更替，庆祝这个世界上又一年的结束，朋友。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61178, '你想了解冬天老人吗？ 啊，抱歉，也许你应该和说书人泰莉基娜谈谈。 这些都是我的人民已经过去的传说，而我对与这一传统相关的祖先信仰的了解却来自于她。 我来这里只是为了欢乐和分享故事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61179, '“冬幕节”一词据说源自一个古老的人物，他被称为冬天老人。当他在季节末期走遍大地时，冬天本身就成了他飘逸的斗篷。在他的脚步之后，大地被雪覆盖，因此据说冬天老人会在大地上投下他的冬季面纱。\n\n据说，当冬天老人行走在大地上时，他会为那些欢迎他到来的人提供丰富的恩赐。尽管艾泽拉斯的部分地区可能被雪覆盖，但这给了大地重新诞生和更新的时间。因此，在冬幕节期间举行盛宴会让社区团结在一起，共享他们所拥有的一切。通常，在一个愉快和宴会的日子里欢迎这个变化，都是为了期待大地的更新。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61180, '你想了解我们对冬天老人传说的解读吗？\n\n嗯，没什么好说的，我们相信他是一位慈祥的老绅士，会送礼物。这在我们部族中从未成为一种文化传统，但我们确实会一起庆祝。此外，我在军队时有一些有趣的故事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61181, '嗯，你想了解关于冬天老人的事情吗？嗯，在我们的文化中……并没有类似的传说。你可能知道，我们兽人来自另一个世界，我们没有自己类似的故事。\n\n我们所知道的只是那个娱乐儿童的冬天老人。格雷克洛尔已经完全扮演了这个角色。啊，但永远不要在他面前提他的名字，所有的孩子都相信他是冬天老人，事情应该是这样的。不过，我在德拉诺有一些有趣的故事可以交换。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61182, '啊，你想听听关于冬天之神的事情吗？我来自位于冬泉谷的星辰村。那里异常寒冷，我们与外界隔绝。我们的责任是照顾那些必须与大地的精灵交流的沉睡德鲁伊，即使在如此寒冷的地方。在冬天，这片土地变得异常寒冷和恶劣，即使对于我们来说也是如此。\n\n就在那个时候，我们会被伟大的冬天之神所拜访。冬天之神在德鲁伊的梦境中与他们交谈，帮助他们找到我们生存所需的东西。作为回报，我们用庆祝和盛宴来向冬天之神表示敬意。正是因为有了冬天之神，德鲁伊们才能保持安全，寒冷的冬季过后将是伟大的更新时期。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61183, '你想知道冰雪之神吗？是的，是巫毒巨魔参与的原因？那你应该去问问霜鬃。我们来自温暖的土地，有着不同的神祇，每个部落都有自己的传统。\n\n我们尊重所有的神祇，所以我在这里来表示敬意，享受盛宴和故事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61184, '我们最古老的故事之一讲述了大地之母的最年长的儿子，冬季族长。随着叶子的飘落和白昼的缩短，他将到来。他带来了大批的野生动物，但同时也带来了寒冷和漫长的夜晚。\n\n我们的部族在这段时间里聚集在篝火旁，一边用餐一边讲述我们的祖先故事。在这段时间里，狩猎野生动物很困难，所以我们总是祈祷族长赐福，以便我们能够生存下来。当寒冷和阴暗让位于春天时，族长就会离开，当土地能够供养我们时，他就会回到沉睡中。只有在需要时再次苏醒。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61185, '我没有任何会吸引你兴趣的故事。去问问布兰登吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61186, '当天气变冷时，孤单和空腹真的很糟糕，对吧？不如与朋友们共度时光！\n\n冬天老人有解决办法。与烟木牧场合作，以微不足道的费用，他会带来美妙的礼物和食品，对吧？所以这是一年中愉快的时光。在雪地里玩耍后，用异国情调的玩具、礼物和美味食物彼此宠爱和惊喜吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61187, '嗯… 当寒冷笼罩大地时，据说熊爸爸将会到来，迎来酣睡。 食物变得稀缺，夜晚漫长，寒冷笼罩。\n\n熊爸爸的到来在一个巨大的盛宴中达到高潮，之后我们中的许多人会进入深度的沉睡，直到冬天结束，据说父熊离开。森林和大地充满了生机，食物丰富，新的更新来临。因此，在我们入睡之前，我们庆祝这个季节，举行盛宴。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61622, '你，想不想在人群里出头？我这儿有腰带扣的图纸。有了它，你比谁都显眼。$B$B<塔诺万叹了口气。>$B$B听着，帮帮我，我手头缺些银子，行吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61623, '卡利姆多的天空与大地一样桀骜不驯。你想飞往何处？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The skies of Kalimdor are as untamed as its lands. Where would you like to fly to?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61907, '我们家族的手艺在暴风城名声很好。全国最精美的一些珠宝，就是贵族委托我们做的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61908, '有什么我能帮上忙的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Is there anything that I can help you with?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61910, '我的曾祖父曾是格瑞姆巴托城里的珠宝匠。我的志向就是在这一行上达到他那样的造诣。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61911, '你知道大家怎么说好的珠宝加工吗！手要稳、心要定，才能做出真正的艺术。$B$B<托瓦格开始放声大笑。>$B$B我叫托瓦格！要是在附近碰见我，尽管来打个招呼。说不定我们能一起做点什么真正漂亮的东西出来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61912, '别太在意托瓦格。他热情过头，还有点古怪，但对活儿是真的上心。$B$B你要是想学珠宝加工的高深法门，找我这个侏儒就对了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61913, '金的特性似乎与星红宝石相得益彰，能做出华美夺目、令人惊艳的首饰。只要在形状和比例上稍作调整，就能……$B$B<凡兹被拽回了现实。>$B$B嘿，你在这儿干什么？没看见我正专心研究吗？$B$B哦，你是想学高级珠宝加工？那我告诉你，在我哪怕动一个教你的念头之前，你最好已经对珠宝加工这门广博而复杂的学问有相当深的领会。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61916, '珠宝加工的精巧特质，与精灵的品味倒是颇为相称。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The intricate nature of jewelcrafting is quite well suited to elvish tastes.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61917, '奥术的专注之处有很多。我在自己的技艺里找到了慰藉——打造精致的美的展现。它们多半以金银的形态戴在人身上。$B$B这其中自有一种优雅，不是吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61918, '欢迎光临阿索兰珠宝……是啊我知道，我以前在这儿开的店做的是别的生意，不过现在改行了。$B$B想学点什么吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61919, '我们与人类的战争结束后，我就该把心思放在别的事情上了。我一向对闪亮的东西和璀璨的水晶很有眼光。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61921, '我冰冷麻木的手指应付不来这么精细的活儿！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- My cold, numb fingers are having trouble with such delicate work!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61923, '珠宝向来是最抢眼的饰物。如今我们的躯壳正在腐朽，或许就更离不开它了。就算死了，也得保持最好看的样子。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61924, '我们家族世世代代都是珠宝匠。他们曾在斯坦索姆开过店铺，打造过全艾泽拉斯最精美的项链。$B$B我至今还记得自己怀着敬畏端详父亲作品的样子。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61925, '人人都需要珠宝，在地精的世界里更是如此。不然你拿什么在同僚面前显摆身家？$B$B它还能抬高你的社会地位。几枚银戒指就够你招来所有姑娘的目光。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61927, '听好了老兄，想赚大钱的话，我有诀窍告诉你。你觉得金子值钱？试试把它变成精美的珠宝！$B$B我有些作品在拍卖行卖出了荒唐的高价，你也一样能做到。只要照着我这套简单步骤来，你也能在珠宝加工这一行里赚个大的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61930, '向你问好，疲惫的旅行者。你是来……做些正当买卖的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Greetings, weary traveler. Are you here for some... good and honest trade?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61931, '＜他的目光令人望而生畏。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <His gaze is intimidating.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61973, '唉，要是你珍惜自己的小命，最好别去打听别人的闲事……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Eh, if you value your life, you’d better not stick your nose into the business of others..
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61977, '我连口气都喘不上来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I just can’t catch a break.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61979, '你以为你是谁？就不能别管别人的闲事吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Who do you think you are? Can you not meddle in other people’s affairs?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61988, '这个幽灵幻影似乎在两个不同的位面之间若隐若现。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The ghostly apparition seems to be fading in and out of two different planes of existence.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61990, '你看见大蜡烛了吗？我在找大蜡烛！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Have you seen big candle? Me look for big candle!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61991, '滚开，蠢货。别打扰我喝酒。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Get lost, idiot. Leave me to my booze.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61992, '灰尘这么多，同伴又这么糟糕。这地方也曾风光过。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- So much dust and the company is horrible, too. This place has seen better days.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61997, '这地方一团糟。什么都乱得不成样子。供上的吃食少得可怜，座上宾客更是大有问题，而且东西还会莫名其妙地不见！我那枚戒指已经找了好几个钟头了！我真想不通麦迪文是怎么回事，但待客绝不是这么个待法。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61998, '＜这位年轻女子正在生闷气，看起来很沮丧。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The young woman is sulking and looks depressed.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (61999, '主人希望这些能量水晶时刻保持运转，可自从有人偷走了点火钥匙，我就没法启动它们了。我得在主人回来前把它修好！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62000, '哦，这儿乱成这样，我都没瞧见你。主人马上就要回来了，可他最爱的香蕉一个果盘里都没有！这下糟了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62001, '谁能想到守护者的文献字写得这么小？看得我头都快炸了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62002, '不管我在这火堆边站多久，都暖不起来！做鬼有时候真是麻烦。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62003, '你好啊！这景色是不是非同一般？我觉得再没有哪座塔能跟麦迪文这座宏伟的高塔相比。你知道吗，它建在魔网的一个交汇点上？了不起吧？为这个喝一杯，朋友！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62007, '让月亮指引你度过黑夜，让太阳在白日温暖你的筋骨。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Let the Moon guide through the night, and let the sun warm your bones during the day.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62030, '这里精妙的魔法正等着被人利用……你要是把这塔探索得够透，把潜藏其中的邪恶清理干净，我就能用裂隙行走之术送你过去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62031, '我在艾泽拉斯的这些年里，一直致力于成为一名武器大师。既然已从各个种族身上学到了能学的一切，如今我便回望过去，寻找那些或许已随时光湮没的技艺。如果你能帮我找到这些稀有的器物，我愿意把所学倾囊相授。$B$B你可以在艾泽拉斯最危险的角落找到上古战争文献。这些文献记载了昔日战争、战役与决斗的打法，有可能解锁未知的战斗技巧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- In my years upon Azeroth I have dedicated myself to becoming a master of arms. Now that I 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62032, '马蒂亚斯为他的事业倾注了全部心血，这也激励我追随他的脚步。或许有朝一日，我会接替他的位置，把他的事业一直延续下去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Mathias has put his heart and soul into his work. It has inspired me to follow in his foot
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62033, '这岛上打打杀杀的，肯定饿得快。要吃点什么尽管说。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62034, '哎呀你好，我叫诺拉，是作为马蒂亚斯的好友过来的。我在这儿的工作就是解读一些古旧文献！有些是用古老的符文或字形写的，没有相应的学识根本译不出来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62063, '沙子残酷无情，毫不妥协。正是训练的绝佳场地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- De sands be cruel and without compromise. Perfect ground for training.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (62994, '这些畜生到处都是。真希望酋长能早点拿个办法出来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (65026, '在我给予祝福之前，必须先杀死拉兰尼库斯。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (65027, '伊瑟拉女士，他们正在逼近。 我们必须走了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (65028, '拉拉休斯，我忠实的仆人。 翡翠梦境的命运掌握在你的手中。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (65029, '不好了…') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (65030, '%s中断了施法。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66100, '哦，天哪，卡拉赞的新到访者。啊，欢迎新的灵魂来到这里是多么高兴。我会尽我所能满足您的需求。但是，我正在全神贯注于为主人的到来做预先的准备。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66101, '你去死吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66102, '看来所有的准备工作都井井有条，我相信是时候进行适当的介绍了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66103, '快走吧，我不喜欢再和这样的人交谈了。$B$B继续前进。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66104, '出了什么事，这里怎么会有凡人？是的，你可以。我相信没有什么能阻挡你的路，是么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66105, '嗷！我讨厌小东西！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66106, '我砸死你！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66107, '伟大的我会砸死渺小的你！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66108, '为什么……老板……背叛了……我们……？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66109, '如意所愿……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66110, '你比大多数人走得更远。现在您将加入我们这个墓穴！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66111, '另一具……尸体……堆起了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66112, '他不再抓着我了...找到符文，让我们自由……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66113, '嘎吱的巨响在地下室里回荡…………') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66114, '堕落者的灵魂呼喊着复仇。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66124, '呸!呸!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66125, '呸!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66128, '萨拉斯关卡最近有大批亡灵向南推进，我们的法师感受到了该地区邪能的污染。我和游骑兵霍克斯比尔勋爵一起派了一支侦察队进入那个地区。侦察队十二个游侠中，只有两个回来了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66129, '然而，这两个人目睹的事情震惊了我们。天灾军团正在集结军队准备入侵南方，而奎尔萨拉斯的北部地区则到处都是恶魔。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66130, '即使是不熟悉魔法的游侠，也能感觉到空气中邪能的激荡。我们怀疑太阳井已经被邪能污染，甚至可能成为召唤恶魔的入口。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66131, '那些恶魔却没有攻击天灾军团。我们推测他们要么是盟友，要么是恶魔在准备进攻。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66132, '什么？！你确定吗？！你的行为又给这个世界带来了毁灭！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66133, '冷静点大祭司，奎尔多雷人应该对此负责。但恶魔又回来了，我们不能忽视它。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66134, '我们意见一致。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66135, '很好。我在奎尔萨拉斯的人民告诉我，你们尊重我们的习俗，有些人甚至已经开始追随艾露恩，所以我不会怀疑你。但是，我要求你和你的人民清理你们烂摊子。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66136, '我很乐意，大祭司，然而，我们缺乏足够的力量。我们只有很少的几艘船。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66137, '不足以击败在海上巡逻的天灾船只。毕竟我们刚刚加入联盟。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66138, '所以你想让我们再帮你收拾烂摊子？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66139, '大祭司，我请求您，我们毕竟是联盟。他们的烂摊子就是我们的烂摊子。我建议我们共同面对。这确实是一个我们不能忽视的问题。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66140, '我将与高层们会面，让我们的军队和舰队做好出击准备。一个月后，我们就能准备好出发了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66141, '一个月？这个月要有多少恶魔涌入这个世界!你疯了吗?') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66142, '动员军队需要时间，就连我们也得参与领袖会议。我们缺少登陆的舰队，所以我建议我们穿过陆地阻止任何东西进入瘟疫之地。代理商会感激你的努力。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66143, '我们的装备不多，但我们会把我们的飞行器、攻城坦克和飞行员投入到战场中。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66144, '他们需要时间抵达，但他们希望能确保没有任何东西能通过萨拉斯关卡。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66145, '没有人比我更清楚恶魔的威胁，塞拉摩的舰队将尽快做好准备。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66146, '好吧，大家都有各自的理由和方式，但我不能忽视这个威胁。我们越早行动，就能更好的解决此事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66608, '卡拉赞, selama am\'oronor! Fala\'andu, fallah.') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66839, '冬幕节快乐，小霜!把我传送到冬幕谷!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66840, '鲨鱼看起来害怕得要死，它渴望离开这个充满了像你这样的人的可怕地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66841, '桑德火箭正在举办海滩派对，去拜访她吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66842, '丽莎·桑德火箭要办一个海滩派对，请去看看她!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66843, '男爵送给你的礼物。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66844, '跟我来，如果你想活命的话!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66845, '试着收集一些羊毛。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66846, '羊把松露叼了下来，然后它跳到你的袋子里去找更多的松露!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66849, '是的……我想要一些私人空间，你能隐藏我的军衔吗?我给你金币。警告:这将花费你5个金币!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66850, '以50铜币租用这匹马。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66851, '以50铜币租用这只狼。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66852, '以50铜币租用这匹马。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66853, '以50铜币租用这匹山羊。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66854, '以50铜币租用这匹山羊。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66855, '以50铜币租用这匹科多兽。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66856, '以50铜币租用这匹科多兽。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66857, '喂一下狮鹫，看看会发生什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66858, '带我离开这里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66859, '请指引我穿越时间之穴。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66860, '喂一下双足飞龙，看看会发生什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66861, '告知我的命运。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66862, '血环之战(3v3单人模式)') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66863, '血环之战(3v3组队模式)') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66965, '上次我参观修道院时，我记得你们的人使用这个工具。\r\n\r\n<你抓起一根滚烫的拨火棍，将它放在弗拉迪乌斯的脖子上。>\r\n\r\n现在说吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66966, '我不会对杀害我同伴的人说什么！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66967, '你的同伴滥杀无辜。。\r\n\r\n<准备刺他。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (66969, '此时此刻，你的命不在他手里，而在我手里。<你把烙铁棍贴在他的脸上>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (67029, '你摧毁了我们的敌人，向他们展示了真正的力量。我为你的荣耀折腰，Lok\'tar！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80100, '第一天上班，是吗，小子？\n\n是的，我曾经也像你这样年轻有朝气，青涩。现在我只是绿色而已！你知道吗？\n\n不管怎样，别再偷懒了。继续工作，否则我会从你的工资里扣钱的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80101, '你怎么样，孩子？ 来给老妈妈斯普拉特一个拥抱吧。 别害羞！\n\n我在这里拥有最好的烹饪技巧，我可以将手头的任何东西都变成可食用的。\n\n我会把你喂饱的，就像你妈妈以前那样。 除非她不...那就把我当作你的新妈妈吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80104, '嘿，伙计，想学点如何打斗的本领吗？\n\n这里有点建议：首先，你要攻击对方的膝盖。一旦他们和你在一个高度，他们就不会再看不起你了。明白我的意思吗？\n\n这是实用的建议。为了这个建议，你欠我几个铜币。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80105, '枪支。哥们，我喜欢枪支。你呢，$N？\n\n每次我听到那震耳欲聋的轰鸣声，我的血液都会涌动起来。需要一些火器训练吗？只要你有银币，我就有技能。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80106, '有什么比一袋硬币更好，$N？一袋硬币是你从某个笨蛋的口袋里偷走的。比这更好？是你从他们冰冷的死手中掰下来的。\n\n我听说你可以把整具尸体卖个好价钱，所以别来考验我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80107, '没人会怀疑地精，$N。绝对没有！所以谁会对涉足黑暗的艺术多想一下？\n\n我打赌你已经迫不及待地想学如何召唤魅魔了……或者也许你的兴趣倾向于男性恶魔？先做生意，再谈享乐，伙计。先付钱，然后再学召唤咒语！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80108, '嘿，最好的伙伴！你想尝试一下魔法吗？巫术？你看起来脑子很聪明，就像我一样。你可以用这些法术赚很多钱。\n\n变出一些水，一些食物，开个传送门。所有这些便利意味着一件事：咔嚓！当然了，如果你想赚点钱，就得给我滑些硬币，明白我的意思吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80121, '杜隆塔尔可不像什么度假胜地。满地沙漠、蝎子和鹰身女妖，而且显然在我上次来的时候，还增加了某种恶魔教派。不过，这还总比让自己落入风险投资公司暴徒队伍的错误一端要好。\n\n<纳特 叹了口气。>\n\n我以前也是那个暴徒队伍的一员。\n\n无论如何，一个好的商人总是向前看的。在稀缺之处，就有机会。部落似乎擅长在艾泽拉斯上最恶劣的荒原上定居，所以只要掌握足够的技巧，我打赌我能赚足够的钱，在南海度过我选择的岛屿假期。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80130, '你居然还想学会如何使用武器？！\n\n当然，当然，朋友，别误会，只是这些其他家伙大多都是懦夫，你明白吧？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80136, '我可不会随便教任何人，朋友。 当我们关系好一点的时候再来找我吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80200, '感谢太阳之井，让你一路平安抵达这里，$N。 我们有很多事情要做。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80217, '我们的种族以智慧和魔法为傲，但你和我知道，有时候需要更加粗暴的方法。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80451, '你好你好吗？\n\n我是酷尼，来这里是为了确保我们处理好这件事，请彼此友好，没有时间争吵！\n\n当你进入内部时，就会有足够的暴力。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80452, '我只教导银月城遗迹的精灵和他们的盟友。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80460, '我希望我能认识一棵年长、智慧的树。树应该有着美丽的叶子，但我却枯萎且快要死了。\n\n我会存活下来吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80602, '嘿，亲爱的。 来这里进行长期投资？\n\n也许你想赌博，小$c？ 告诉我多少钱，我就掷骰子。 如果掷骰数超过 50，我将加倍赌注。 如果低于 50，它就永远消失了。\n\n如果您使用相同金额连续获胜三次，奖励将增加三倍，但前提是第 3 次掷骰高于 75。如果第 3 次掷骰低于 75，您的金币也会消失。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80603, '<地精暴徒站在那里，嘴里嘟囔着，胸口还鼓鼓的。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (80943, '你是想要在守望者中获得声望吗，凡人？你是想要在时间的纽带中保持和谐吗？\n\n那就别再寻找了，我们每天的闲置都是混乱开始撕裂秩序的一天。\n\n那些试图破坏我们工作的力量不会停止。总有更多可以做的事情，你不正是为了这个原因而来吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (81030, '嗯，嗯... 你改变主意了，嗯？突然间，你决定与我有事情要办？好吧，我与你无关。\n\n滚开！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (81050, '我真的很荣幸黑暗女士委托我分享她的知识。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (81055, '我们的民族坚强无比！我所做的是必要之举。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90001, '感谢您一如既往的支持。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90002, '这……这是什么地方？ 我还活着吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90003, '嘘... 如果你给我5金币，我可以帮你弄一些假文件，让你隐藏你的真实身份。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90004, '即使是最好的刀剑，如果不加护理，也会生锈变钝。你已经选择了你的武器，所以战斗吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90100, '您好，$大人：女士； 海龟$N!\n我们需要您的帮助来保卫我们的土地免受入侵者的侵害！\n牵着我的手，我带你去战场。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90101, '前往战场的传送即将到来！稳重和从容才能获胜。请耐心等待！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90150, '嗯，年轻人，我感觉不到你身上有风之精灵的祝福。\n\n你和乔恩·天眼谈过吗？还是你在贫瘠之地追逐风之精灵的踪迹？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90151, '想象一下你自己在平原、森林和山脉上奔跑，风吹在你的脸上......\n\n穿越未知的领域； 前方道路的奇迹，你的命运就在地平线的那边等待着。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90201, '那么，你来看看兔子洞有多深…\n\n-拿出两颗石头，一颗红色的，一颗蓝色的-\n\n选蓝色的石头，你可以回到船夫艾克那里，搭乘船回到银松森林，忘记在这里发生的一切。\n\n选红色的石头…你会进入营地，揭示有关黑暗女王的真相。不过要注意，我们就不会轻易让你离开，你将不得不永远背弃被遗忘者。\n\n谨慎选择。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90202, '见鬼，我们成功了！现在赶紧从我船上滚下去，别让你们把老船沉了！\n\n喝点东西吗？如果你们的胆量够大，我有一些东西给你们，不过要是你们失明了可别怪我！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90203, '<卫兵紧紧地盯着你，一言不发。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90255, '我们正在等待有人加入地精队。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- We are currently waiting for somebody to join the Goblin team.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90256, '我们正在等待有人加入侏儒队。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- We are currently waiting for somebody to join the Gnome team.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90257, '比赛正在进行中。请等待它结束。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- A race is currently in progress. Please wait for it to finish.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90301, '凡人！ 你的时间还没到！\n\n离开并成为……什么？\n\n关于迅捷？ 你引起了我的注意，年轻人……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90326, '<雪人唱歌。>\n\n正值大冬节，大地各地，所有的赛跑都手握雪球。\n\n冬幕节为大家带来了礼物和奇迹！ 哈哈哈！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90328, '每个人都喜欢一个愉快的雪球大战。你用冰凉的蓝色手掌捧起雪花，把它揉成一个球，然后全力以赴地朝你的朋友扔出去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90335, '我是金属丝丢失的手套，我最喜欢的手套被偷了，哦，为什么我不能哭？！\n\n对于盗贼，我有一份长长的名单，用冰冷的愤怒惩罚他们，因为他们做错了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90336, '战争！ 冬幕节的欢乐时光在无情冒险者的攻击下崩溃了！\n\n到处都是英雄，到处都是雪球！\n\n加入战斗，向众多职业释放这些冰冻的投射物，获得一盒冬季糖果的奖励！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90338, '人们喜欢砍木头。在这个活动中，人们会立即看到结果。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90341, '红水辛迪加是一个正在寻找人们加入其行列的公会，') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90342, '只要看一眼，你就能看出矮人的手工技艺和侏儒的工程技术。 它是一种能够将人运送到广阔的蓝天很远的距离的装置。 这架飞机似乎专门飞往北方的守望。\n\n这台机器只需花费 50 银币就能将你运送到北方的瘟疫之地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90345, '呃，你管这叫时尚吗？ 什么样的人会允许自己穿着如此尴尬的衣服被人看到。\n\n对你来说幸运的是，只要几块时尚币，我就可以给你换一套这些令人惊叹的服装。 您将成为镇上穿着最好的 $C。 当你脑子里有了一些时尚感时，就跟我说话吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90350, '1. 双手握住这个装置。\n\n2. 将其置于头顶上方。\n\n3. 放手。\n\n4. 享受一尘不染的心灵的阳光。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90351, '精心制作的种植器，配有肥沃的土壤和充足的水分。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90352, '如果你有一个花园和一个图书馆，你就拥有了一切所需。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90353, '我的宏伟梦想是种出世界上最大的南瓜！\n\n你的梦想是什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90354, '啊，$N，我已经等候你了。\n\n是来学习如何培育种子和照料土壤的吗？\n\n你来得正是时候。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90355, '我来这里是为了在莫什弗部族最聪明的长老科恩的指导下学习生存的艺术。\n\n我的姐姐疗伤，教授急救知识，我相信治愈远比任何绷带能治愈的东西都来自大地之母的恩赐。\n\n种植食物是我渴望掌握的一门艺术，就像我自己的蹄子一样。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90357, '泥土。如今我只剩下这个。\n\n我宁愿继续培育新的菌丝体，种植新种类的……什么？\n\n哦，你也喜欢蘑菇吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90358, '当你看到我独自一人在这里挖掘泥土堆时，难道你不会和其他人一样想吗？\n\n别担心，那是很自然的事情。\n\n毕竟，你离真菌生活还差得远呢。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90360, '在我还活着的一小段时间里，我的一张脸上体现了大胆、勇敢和愚蠢，如果你认为自己能够独自应对，你可以亲眼目睹。\n\n那个可怕的怪物是你从未见过的。\n\n只有一半是蜘蛛状的……<咳嗽着流血>亡灵……至少十个人……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90361, '那些蜘蛛不是我杀死的任何东西。\n\n整个小组，不……甚至需要三个人才能抓伤那只野兽。\n\n永远不要独自去这些地方！永远不要！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90362, '嘿，你！ 我们需要您的帮助！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90365, '<这匹马似乎很喜欢你。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90366, '狮鹫的懒洋洋的举止表明他还没有做好飞行的准备。\n\n毫无疑问，昏昏欲睡和饥饿。 一些多余的矮人温和会让他立刻振作起来，并可能为你赢得一张航班。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90500, '伊什努-阿拉，欢迎来到影叶步兵前哨站，我们来自菲拉斯，我们正在帮助泰兰德和她的人民，以将这片土地从腐败中解放出来，并确保部落不会破坏我们的森林！\n\n哦，抱歉，如果我因为我们的问题打扰您，既然您在这里，请随意买一些食物，如果您愿意的话，甚至可以在这里过夜。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90501, '我是一名自由骑士！我没有领主。你对此有意见吗？\n\n<她瞪了你一会儿，然后神情变得愉快。>\n\n啊，不管了... 欢迎来到我们的教堂！我可以给你提供一个睡袋，或者给你一些口粮。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90561, '明天你会发现一些美好的事情。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90562, '你过去的敌人很快就会成为盟友。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90563, '你无论做什么事情，都将会幸运。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90564, '有人在赞美你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90565, '在陌生的地方着陆时要小心。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90566, '避免进行不必要的赌博。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90567, '你将会获得一笔财富。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90568, '你最初的爱和最后的爱都是自爱。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90569, '休息是一件好事，但无聊是它的兄弟。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90570, '那些品味简单的人总是对最好的感到满意。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90571, '不要让战争的浪潮把你冲走。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90572, '你让你的对手哑口无言。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90573, '你有一双善于发现虚伪的眼睛。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90574, '一个人在教导别人时学到的东西最多。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90575, '很快你就要在紧迫的事情上做出选择了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90576, '没有充分的理由不要踢侏儒。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90578, '被遗忘者正在图谋不轨。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90579, '许多错误的步骤是因为停滞不前造成的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90580, '神圣之盾和炉石并不能让英雄变得英勇。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90581, '蓝色的答案总是正确的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90582, '你的财富在熔火之心等待着你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90583, '专精生存的猎人并不能保证生存下来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (90653, '如果我是你，今天就不会穿蓝色。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- If I were you, I wouldn’t wear blue today.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91200, '这都是关于地精的精确，你认为兽人能处理这么精细的零件吗？\n\n需要什么，伙计？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91201, '砍木头可不是容易的工作，尤其是有这么多懒汉！\n\n这就是像我这样的优秀工头存在的原因，提高生产力！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91205, '如果你在找来自南海的杂七杂八的东西，那你运气不错！\n\n除了在泽特这里，没有其他地方能买到这些东西！\n\n哦，还有，不退货！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91216, '乌兹古特确保没有人偷木材，你买？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91220, '把喷嘴对准这里!你看起来非常口渴，汗从你的脸上滚下来，炎热的太阳照在人身上，这正是你想要的!\n\n你为什么不喝点我的水呢，它是冰凉的，可以解渴，价格刚刚好!\n\n你在城里找不到别的店了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91221, '你在找你的"解药"，伙计？我有好货，便宜，而且是自家制作！\n\n它会比那些愚蠢的达拉然酒让你更快地喝醉，这是肯定的。这就展示了一个专心于任务的地精能做到什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91225, '欢迎来到星火！\n\n我从零开始设计并建造了这个地方，从第一块石头和岩石开始，把它建成了现在的样子。\n\n所以，如果你有任何建筑项目，告诉我一声。可能会花不少钱，但值得这个金子，我可以告诉你这一点！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91227, '萨玛尔卡，朋友。地精们肯定对美味的肉食有着品味，看起来他们确实吃了相当丰盛的一顿。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91231, '失火 失火！ 我们被命令在看到目标时把这家伙塞满火药！\n我们可能会袭击东部王国！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91238, '嘿！欢迎来到星火酒馆！\n\n随意找个座位，把自己当作在家一样！如果你需要喝的，就来找我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91242, '你是来了解我的著名的瓦兹火箭吗？\n\n你怎么会从未听说过它呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91243, '是的是的吗?$R想要高方做什么?\n\n高方回归湿地，高方是这里的大佬大佬，将和莫斯德重聚，是的，是的!\n\n高方组建强大的人奴部落，你来帮忙!\n\n我们做得很好，是的!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91244, '没有什么比在愉快的钓鱼日后放松身心更好的了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91245, '地精是有趣的族群，但可能需要更多的灵性。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91253, '因为在那个愚蠢的砍木工作中偷懒被解雇，这实际上是最好的事情！\n\n没有人找到我，我有了我想要的所有时间，让他们见鬼去吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91256, '欢迎来到拉兹尔！ 别理会巷子里那个混蛋泽特，他的货只不过是廉价的桌子划痕而已！\n\n我在这里得到的是来自艾泽拉斯的正宗稀有物品！ 它们数量有限，先到先得，应该为这个世界上的任何冒险家提供良好的服务！\n\n所以，站起来，在拉兹尔的一些罕见珍宝消失并被另一个更渴望、而且……嘿，比你更精明的人抢走之前获取它们！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91266, '我们在杜罗塔尔的木刻工作取得了良好的进展！\n\n这里可能没有太多的树木，但这些树木很大，而且很大。他们提供了相当多的木材！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91267, '这的炎热让所有的粉碎机损坏得比我以往经历的还要快！\n\n即使我有这么多使用这些东西的经验，我也没有遇到过这么多问题！\n\n都怪那的太阳，告诉瑞克斯赶紧修理吧！我最不想做的事情就是浪费这么多经验，然后变得只能用手臂砍，效率太低了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91274, '工作永远没有做完的时候，而且要靠我确保它们得以完成！我们有货物要发运，还有人要把所有的石头和矿石运送过来！\n\n如果没有我，你在这里看到的一半甚至不存在！嘿，你在找工作吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91289, '元素之间的力量平衡不断变化。\n\n大地领域内有一种干扰，我不知道裂缝从哪里产生，或者是如何开始的，但我感觉到随着时间的推移，断裂越来越严重。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91290, '马族人长期隐藏在这些高地内，直到现在我们才被流放出故土，被打回阴影中。\n\n我部落的物资已经大大减少了，但我能给你的一点点，野牙能为你做些什么吗？\n\n或者，您能为我们做些什么吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91292, '你听说过星火港的消息吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91296, '一个张贴着各种通缉个人信息的布告板。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91297, '风在我的背后，现在我可以做任何我想做的事情！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91303, '你好，$r，沙丘夺走了许多强大的冒险家。 轻轻地走，小心前面的路。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91350, '达拉然可能已经支离破碎，但我们仍在为加深魔法知识而努力。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91400, '我是为宴会准备肉的人，为战争准备皮革的人，你需要什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91401, '嘿，欢迎来到野牙村，别给你惹麻烦，不然我就得对付你了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91402, '尽管我们被赶出了家园，但灵魂仍然守护着我们，巫毒在我们这边，伙计！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91403, '欢迎你，$r，需要什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91415, '追逐猎物的刺激是这个世界上最好的事情之一，伙计。\n\n在古老的时代，巨魔是所有事物的主宰！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91710, '我曾经是一位伟大的巫师，把一切都抛在身后，只是简简单单地照顾苹果，感觉很好。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91730, '我不会去打扰纳格拉斯男爵。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I would not disturb Duke Nargelas.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91768, '亚麻胡须的前哨是为了调查艾萨拉，代表侏儒进行继续研究而设立的！\n\n虽然我们离许多族人很远，但我们正在取得巨大的进展！\n\n你是来帮助弗拉克斯惠斯卫的前线吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91781, '欢迎来到避难所，外来者，我是桑弗克拉，这个地方的领袖。\n\n我引导我的人民走向更好的命运，远离我们曾经称之为家园的地狱般的景象。\n\n也许这现在是我们的家，而且是更好的家。\n\n这里的德莱尼会友好，尊重对待你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91782, '你在这里平安吗？ 你是来和我战斗的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91783, '你必须拥有强大的魔法才能到这里来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91798, '哞。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (91799, '你在我的领域中想要什么，凡人？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92002, '在这里看到一张新面孔真是令人惊讶。 我们不久前遭遇了海难，但在这里过得还不错。\n\n这是凯兰之息，以领导我们舰队并在我们遭到袭击时牺牲的海军上将的名字命名。 如果您是来帮忙的，我们当然需要它。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92003, '我是破水号的甲板长，你站在她身上！\n\n当你在我的甲板上时要注意脚下，明白吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92005, '这个岛很危险。 如果您没有荒野经验，请留在凯兰之息。\n\n各种各样的邪恶潜伏在我们城镇的边界之外，考验着我们的弱点。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92006, '小心越过这些木桩，走路时要把头转过来。\n\n如果你猝不及防，你可能会死。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92007, '水手们过于傲慢，可能是一群吵闹的人。\n\n它们在船上可能表现很好，但如果单独留在凯兰之息，它们就会像野生动物一样令人讨厌。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92009, '你在看什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92010, '海军陆战队通常会获得所有的功劳，但我们承担了所有的艰苦工作。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92011, '你知道你在跟谁说话吗？ 我是瓦尔达里安之击！ 是的，就是那个！\n\n我是世界著名的拳击手，事实上是库尔提拉斯的冠军！ 我已经大约四年没回家了，但上次回家时我获得了冠军！\n\n就这样被选中真是可惜了，呵呵。 尤其是被困在这里真是太可惜了。\n\n哦，好吧，这里的小伙子们和姑娘们对我来说已经足够好了，尤其是考虑到我在家乡的名气。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92012, '我希望我的手下善待你，自从离开暴风城以来，我们有些衣衫褴褛。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92013, '新鲜血液?你想在这里出名吗?成为那些传说中所说的英雄?\n\n很抱歉告诉你，你在这里只会发现臭烘烘的沼泽水。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92014, '你有暴风城的消息吗?那些混蛋把我们丢在了这里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92017, '你好，欢迎来到悲伤要塞，我是圣骑士贾纳索斯，我会守护着这个地方\n\n这个要塞是在第一次战争之前建造的，目的是监视向西进入艾泽拉斯王国的入口。\n\n自第一次战争期间沦陷以来，它已陷入年久失修的状态。\n\n它被毁后，我被派到这里试图夺回它。 虽然我们已经做了一些修复并占据了这个地方，但总有更多的事情可以做。 尤其是我们旁边是黑暗的沼泽，而兽人则潜伏在斯托纳德。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92021, '我把这里所有的靴子都收拾得井井有条，你要找一双吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92022, '我不再被允许进去了，但他们让我保留我的小屋！\n\n想买一些蘑菇吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92023, '嘿，大家都在哪儿？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92024, '我参加过许多战争，杀死过许多敌人。 从德拉诺一路来到这里的前哨站，我将带着极大的荣幸领导它。\n\n奥格瑞玛最伟大的人物委托我领导部落的荣耀，而我将……\n\n你是来帮忙，为自己扬名立万的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92133, '世界已经发生了很大的变化，似乎与我离开时截然不同。\n\n空气中弥漫着某种东西，但我看不到它，有什么不对劲，但我的思绪却很混乱，几乎失去了自己。\n\n但我可以看到你，你在一个我曾经称之为家的地方，我的许多人称之为家，但已经在时间的流逝中消失了。\n\n我不知道我为什么又来这里，但你会帮助我的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92137, '拜托，别杀我！\n\n我是为著名的南海保护区创造食谱的走私者！\n\n你……如果你愿意的话，可以买一些！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92168, '欢迎来到卡尔科尔角，我想您对为什么吉尔吉姆会有半人马有很多疑问。\n\n很久以前，差不多六年了，我们从卡利姆多起航，加入了南海海盗。 我们被雇佣为雇佣兵和战士，但我们的领袖背叛了我们，并将黄金据为己有。\n\n由于他的残暴以及对战友缺乏关心和同情，他获得了“掠夺者”的称号。 卡尔科尔这个名字来自我们雇佣兵团的名字，我们把它当作一个奖章佩戴。\n\n我们希望有一天能回到亲人身边，但这一天似乎还很遥远。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92171, '悲剧发生后，需要一颗勇敢的心继续前行，并以良好的面貌面对世界。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92173, '不要在这里惹麻烦，我不想和你战斗。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92174, '莱库戈斯会为他的所作所为付出代价。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92176, '小家伙来帮忙吗？ 你确定你能帮忙吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92177, '需要食物吗？ 需要东西吗？ 我有东西，你买得起吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92178, '你需要盔甲吗？ 盔甲适合在野外外出，武器也不错，但我不会制造武器！ 让我看看我能为像你这样的小家伙做些什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92180, '我是克鲁克佐格大人，我领导着这里。 我们曾经是伟大的戈多什部落的一部分，但现在我们是孤独的。\n\n你将帮助我重现摩尔奥格的荣耀！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92181, '部落在艾泽拉斯各地建立了联系，希望能够将力量平衡转向对我们有利的方向。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92182, '如果没有你我这样的探险家，世界上将会有许多未知的地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (92938, '我是魔法师瓦尔贡，库提拉斯的公民，一个致力于水术和奥术研究的巫师。\n\n这个岛上隐藏着许多巨大的谜团，我致力于揭开它们。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100002, '这种健康的鞭根植物与费伍德森林中盛行的腐败腐败截然相反。 柔嫩健康的根部会长出美味的块茎，长在植物旁边的地上。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100100, '当你更仔细地检查飞机时，你会注意到飞机侧面潦草地写着“纳特·布拉斯滕托姆的财产”。\n\n飞机上装饰有小贴纸。 其中有一枚小硬币、一只黄鹦鹉和一把锤子。\n\n底部刻有“FM Acquisition”字样。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100201, '啊，如果不是 $N 的话！ 你在这附近肯定已经出名了。\n\n你需要去闪金镇吗？ 好吧，在你为我们所做的一切之后，我不能拒绝你。 这次我可以把你传送到那里，作为一个特殊的恩惠。\n\n你准备好出发了吗？ 离开这里之后，需要一段时间才能回到这里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100205, '好吧,好吧!带我回洞里去，只要别杀我!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100402, '“灵魂总是在呼唤，人们只需要倾听就能听到它们。”') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100403, '叫医生来!') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100404, '但不适合我！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (100500, '寻找休息的地方，$c？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (195007, '杀人不露面的战士是没有荣誉的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (249901, '那些地精人呢？！按说他们把金子看得比什么都重才对。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (649101, '现在还不是让你长眠的时候。我会帮你起死回生……但你也要为此付出一些代价。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1000000, '看来阿比迪斯大人在选择新血的时候太草率了，如果你在入口处面对我的话你就不会走到这一步了。$B\n看看你，怪物，可憎的。 你的行动方式，你的战斗方式，你说话的方式，这一切都由你的黑暗大师的控制。 如果你还剩下一点道德，就向你曾经认为是强大的存在祈祷。$B\n我已经在你身上浪费了口气，卑鄙的生物，来见你的下场吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1000001, '多年来，我一直在研究奥术。 我在订单中的角色不同，但很有意义。 我在学习中见过死灵法师的作品。 我从来没想过要对抗像你这样强大的可憎之物。$B\n我认为这是一种嘲讽——你站在我面前却还没有攻击。 背负着黑暗主子的耻辱的你，竟然这么高估自己了吗？ 唉，我会给你你想要的满足。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1000002, '我喜欢记住修道院以前的样子。$B\n一个崇拜和欢乐的地方，一个年轻人寻求更大目标的地方。 在这些大厅里，有很多人是我教他们如何保护自己以及他们所代表的东西的。$B\n许多人被圣光带走，被这个不合理的世界屠杀、残害。 对于像你这样的人来说，什么都不是，这些人在正义的好人的痛苦和悲伤中挥霍无度。 我诅咒你们，你们所有人。 你相信我们如此弱小以至于会被天灾军团的一小撮可怜的爪牙打败吗？$B\n数数你的脚步，这将是你的最后一步。 当我们处理完你之后，我们的造船工人就会准备好，我们会用我们自己的方式伸张正义。$B\n你的垮台来了，傻瓜，我会保护秩序！$B\n为了血色十字军！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1000050, '我们即将见证圣光的奇迹。 亚历山德罗斯·莫格莱尼很快就会出现在我们面前。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (1000051, '我无法休息。 直到我看到血色十字军失败，直到我的儿子因杀害他的父亲而面临正义。$B\n不过不用担心，会有其他人来完成这个任务。 即使在愤怒中，我也希望最后一次将我的孩子抱在怀里。 我准备在另一边休息了，$N。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2010824, '<谷物储存在一个小袋子里。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2593001, '我来报到执行战地任务。需要有人签收我的文件。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I’m reporting for Field Duty. I need someone to sign my papers.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2593003, '我准备好了。（开始事件）') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I’m ready. (Start Event)
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2593004, '所以你帮我们打退了那次进攻，是吧？别以为我会对你刮目相看。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- So ye helped us fend off that attack, eh? Don’t think I’m impressed.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947901, '征兆已经很清楚了，旅行者。日月更替之间，大地母亲的双目与泪水仍在庇佑我们的天空。可它们彼此已渐渐远离，正如我们族人。一个手足相争的时代已经来临，那曾让我们血脉相连的血，将洒在我们海岸的蓝草之上。代价沉重，负担更沉。这个未来我们本不必知晓，却终将知晓。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947902, '长者，我们必须谈谈。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Elder, we must speak.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947904, '那么也许是你的眼力越来越不济了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Then perhaps your sight is growing dim.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947906, '以安舍与姆莎之名，那洛修呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- By An’she and Mu’sha, yet what of Lo’sho?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947908, '所以追随洛修，就是让月蹄族赐予你死亡。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- So to follow Lo’sho is to be granted death by the Moonhoofs.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947910, '那就说吧。再寻求我一次相助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Speak then. Seek my aid once more.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947912, '继续讲呀。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Go on.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947914, '继续。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Continue.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947916, '那是什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What was it?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947918, '继续讲呀。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Go on.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947920, '事情不可能就到此为止。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- It can’t end there.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947922, '这几乎改变不了你所做的事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- This barely changes what you did.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947924, '那你打算怎么付账，长者？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- And how will you be paying, Elder?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947925, '用我自己的命。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- With my own death.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (2947926, '那是否由你说了算，我们走着瞧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- We will see if that is for you to decide.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4184501, '取走法拉克的火焰。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Take the Flame of Farrak.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4184502, '＜火焰炽热发光，迸裂着古老的魔法。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The flame glows hot, crackling with ancient magic.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4188101, '＜一颗破碎的珍珠躺在祭坛上，表面布满裂痕。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <A broken pearl lies atop the altar, several cracks running along its surface.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4188102, '＜进一步检视祭坛。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Inspect the altar further.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4188104, '＜把嗡鸣的水晶放到珍珠旁。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Place the humming crystal next to the pearl.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4190401, '＜火焰不祥地燃烧着。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The fire burns ominously.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4190402, '把咒法之尘撒到火焰上。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Throw the Dust of Conjuration on the fire.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (4292007, '啊！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6210701, '＜这个矮人一言不发地盯着你。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The dwarf stares silently at you.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6210801, '你不属于这里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- You do not belong here.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6210901, '你不属于这里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- You do not belong here.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214101, '快来看看我的货物！它们可是我直接从大海彼岸进口来的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Come see my wares! I’ve imported them straight from beyond the Great Sea!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214201, '这鬼天气热死我了！真想灌下一大杯冰镇琥珀麦酒。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- This heat is killing me! What I would give for an ice cold mug of Amberale.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214301, '我那个没出息的儿子整天做当骑士的白日梦，还整日围着女人转。他要是把这份劲头用在继承我的手艺上该多好……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214401, '想钓好鱼，最好的办法就是变老。老到不怎么动得了，鱼就不怕你了，哈哈！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214501, '我想要看看你出售的物品，卡兰德拉斯。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I wish to browse your wares, Calandrath.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214502, '欢迎来到蜜滴旅店！找个位子坐下，享用北风镇最上等的菜肴吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Welcome to the Honey Drop Inn! Grab a seat and enjoy Northwind’s finest cuisine!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214601, '埃勒里安小姐派我来取一篮苹果。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Miss Ellerian sent me to grab bundle of apples.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214602, '你好！住店有什么需要吗？我们还有几张空床，很乐意留你过夜！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214603, '给你，这些我一直替她留着呢。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Here you go, I had these saved just for her.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6214701, '我健壮的狮鹫能载你去哪里？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Anywhere my sturdy gryphons can take you?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215001, '你去向蒂芬王后致过敬了吗？还没有的话，何不买一束我的花，到那边的蒂芬公园献上呢？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215101, '只有最上等的面粉才能做出这些绝妙的点心！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Only the finest flour is used to make these marvelous treats!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215201, '整个暴风城也找不到比这更好的货色；只有铁炉堡的宗师铁匠才配跟我的武器比一比！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215302, '你找我有什么事？我实在没那个工夫、也没那个兴致去管一个冒险者的鸡毛蒜皮。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215304, '法警兰卡斯特，琥珀木领主派我来取你给普瑞斯托女士的报告。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Bailiff Lancaster, Lord Amberwood sends me to get your report for Lady Prestor.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215402, '这些叶子总也落不完。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- These leaves just never stop falling.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215501, '前路是黑暗的日子，冒险者。北风仅剩的安宁与平静，正随着每一个时辰的流逝而消散。这片土地正在崩坏，可似乎没人在意——领主大人不在意，国王也不在意。收拾这场落到我们头上的惨剧，就只能靠我——靠百姓自己。失踪的人、入侵的迪菲亚、黑石与黑铁、四处横行的豺狼人、整个比尔克哈文镇成了一片废墟。我满手都是问题，却腾不出一只手去抓解决办法。我以你的善念与道义相求：请帮帮北风的百姓。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215601, '你听过埃德林·维拉斯爵士的故事吗？一个普通农民，后来成了暴风城最伟大的骑士之一。他是本地的传奇，没人不知道他的名字和事迹。我希望有朝一日也能像他那样——做一个真正的骑士，走遍世界，追寻冒险，保护无辜的人！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215701, '亨利真是个会讨人喜欢的。他还带我来胖南瓜这儿吃饭呢，尽管他正忙得脚不沾地，要像他父亲那样当个铁匠。我很感激他为我抽出时间；他父亲并不反对我们俩见面，只是更希望亨利多待在锻炉边。$B$B<瑟雷萨轻笑。>$B$B马丁确实已经尽力了，可我怀疑他管不住儿子那副爱冒险的性子。连我都管不住。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215801, '真够乱的。胖南瓜酒馆平时挤满了客人，可自打东边那些入侵者来了之后，我这儿就只剩那边那个闷头闷脑的老家伙，问题问得没完。不管怎么说——欢迎来到胖南瓜！请问是饿了还是渴了？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6215901, '索普先生今天忙得脚不沾地，想喝什么好酒尽管叫我，我给你端过去！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6216201, '该死的下等人！我绝不容忍在我的领地上如此放肆。这场闹剧般的比武大会一结束，我就要立刻对他们施以裁决！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Accursed low-lifes! I will not stand for such exorbitance in my lands. The moment this far
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6216301, '好心的女士，这片土地究竟遭遇了什么浩劫？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Good lady, just what chaos has befallen these lands?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6216302, '国王的荣耀，朋友。走过这些厅堂时请务必守规矩。我们实在经不起更多麻烦了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6216401, '琥珀木爵士，你的兄弟让我把你的报告交给卡特拉娜·普瑞斯托女士。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Sir Amberwood, your brother asked me to deliver your report to Lady Katrana Prestor.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6216402, '别考验我的耐心，乡巴佬。我可不像我兄弟那么好说话。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Don’t test my patience, peasant. I am not as complacent as my brother.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6216501, '欢迎来到北风。让你看到它这副凄惨模样，我很抱歉。这些麻烦好像一股脑儿全砸到了我头上。更糟的是，我连足够的士兵都没有，护不住我的子民。百姓或许觉得我和我兄弟都不怎么上心，可事实恰恰相反。然而我剩下用来收拾这场乱局的力量，全都被国王的命令捆住了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6218301, '我们家族侍奉米尔登霍尔家已经好几代了。我们精心照料的马匹体格上乘、速度出众，耐力也配得上这份本事。你要是有钱，我可以教你在北风这边怎么骑马。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6218401, '我和丈夫忙着照看路那头比武用的马，实在脱不开身。它们当中有许多需要特别的照料和饲料，而额外帮手只有乔格一个，这儿常常忙得团团转。不过还是请看看我们这边其他的马；它们是整个王国最上等的坐骑！米尔登霍尔女士的马在首都那些最显赫的骑士与贵族中间都很有名。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6218402, '我想从你这里买点东西。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I would like to buy from you.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6218501, '这可不是我想象中的假期。因为比武大会，格林特家缺人手，这儿又没有别人，眼下清理马厩的只有我一个。老实跟你说……我一个人在这儿一点都不觉得安全。格林特先生让我值最后一班，可外面到处都在传有人被掳走之类的，我宁愿缩在家里不出来！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6218601, '来一盒美味的琥珀釉甜甜圈吧，用的是当地琥珀汁做的！趁还酥脆热乎，赶紧买！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6218701, '别被我旁边这个大嗓门分了神；你需要的是来一杯冰镇饮料，一边补水一边欣赏选手们的运动精神！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6219701, '空气中回荡着怨怼之气。不管是什么惹恼了风之领主，都不是好兆头。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6219801, '祖灵在低语，说有大乱。元素在哭泣，我们看到的就是它结出的果。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6219901, '哦，这不可能发生！我到底做了什么才遭此报应？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Oh, this can’t be happening! What have I done to deserve this?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6227301, '嗯？你不是卫葛斯——那该死的食尸鬼偏偏在我最需要他的时候跑掉了。卫葛斯，回来，小子！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6227501, '我其实不太适合干这种行伍的活儿，但只要能保住家园，让我做什么都行。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6227601, '北风内部有腐坏的东西。内里的病症，起初哪怕再小，也会很快滋长蔓延。绝不能让这种事发生。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6227701, '狮望岗以前作为商贾大道的一环，守备森严，如今只有我们这些民兵还守在这儿。真让人琢磨贵族们到底在打什么主意。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6227801, '我做了这么多年商人，还没见过这么糟糕的场面。真是丢尽了暴风城的脸。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6227901, '哀悼是所有人共通的事。无论我们年少年长，最终都要为逝者哀悼。不管他们是不是走得太早，这都无关紧要。我们的心就是承受不住那份痛。我从没想过自己会活得比女儿还久——可如今我就在这里，盯着一尊几乎不像她的雕像。$B$B我的蒂芬不是战士，可她心地善良、性情温柔。还有人记得他们那位命短的皇后，会来致意。为此我感激，也知足。我多想再看一眼她的脸，她那傻气的笑容，她那一头金发。$B$B<伊恩格维尔德眼圈红了。>$B$B我本来还能见到她——只要他们肯放我进暴风城。我本可以在孙儿的脸上看到我的蒂芬，那个我天天都想见的孩子。可他们不让我进。那可怜的孩子，孤零零地活在世上，母亲死了，父亲不知所踪。他要是知道我爱他有多深就好了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6228001, '参观教堂时请保持安静，尊重逝者永恒的安息。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Please stay quiet while you visit the church and respect the departed’s eternal rest.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6228301, '要做的事太多，时间却太少。拜托，在这里别弄乱东西！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- So much to do, so little time. Please, don’t make a mess while you are here!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6228501, '注意礼数，排队等候。插队可不会让你更快见到琥珀木领主！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6228601, '哎呀，有访客……！请在这附近保持安静，别打扰这些花……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Oh my, a visitor...! Please be quiet around here and don’t disturb the flowers...
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6228801, '你能感受到这片山谷的精魂吗？绯红的树木、起伏的青翠原野，还有清透如水晶的微风在空气里穿行？只要深吸一口气，我的灵魂就被灵感灌满，哪个缪斯都做不到！我跟你说，整个东部王国再没有第二个像北风这样的地方。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229001, '那个蠢丫头！这已经是第十一场我不得不替她收拾的烂摊子了。她再这么下去，我早晚被这些事愁成个老太婆！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229101, '我又搞砸了。师傅起码得念叨我一个月。谁让我不自量力，自己跑去试那些难的咒语……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229201, '琥珀木爵士是北风卫队的耻辱。他的前任绝不会让北风变成这副破败样子。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229301, '如此残忍。这一定是圣光降下的试炼。越是艰难，我们的信仰越要坚定。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229401, '爸爸怎么去了这么久？他答应给我买比武场那边好吃的甜甜圈呢！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229501, '对东部王国各地的最新出版物感兴趣吗？从侏儒工程学论文到关于人类贵族世家的详尽研究，你一定能找到合自己口味的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229601, '孩子们今天格外活泼，他们最好在课上专心些。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The children are especially lively today, they better keep attention during class.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229701, '我本该专心帮阿尔金特修女处理教务，可那座被烧毁的修道院的样子总在我脑子里挥之不去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229801, '把暴风城送来的捐赠木箱交出来！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Hand over the crate with donations from Stormwind!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229802, '别碰我的战利品，小子！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Hands off my haul bub!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229803, '想得美！今天就是你的死期！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- As if! Today you’ll draw your last breath!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229805, '拿走它，滚出北风镇！＜支付20银币。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Take it and get out of Northwind! <Pay 20 Silver.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6229901, '迷路了，亲爱的？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Lost your way, darling?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230001, '等我长大了，我要当守卫；保护大家，就像我哥哥一样！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- When I am all grown up, I’ll be a guard; protecting people, just like my big brother!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230002, '我记不清当初是谁跟海盗打的了……希望阿尔金特修女没生我的气……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230003, '弗洛里安·巴罗。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Florien Balor.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230004, '普莉希拉·巴罗。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Priscilla Balor.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230005, '达莉亚·巴罗。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Daria Balor.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230006, '没错，就是巴罗公爵的女儿！太感谢你了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Yes, it was Duke Balor’s daughter! Thank you very much!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230099, '嗯，我不确定是不是那样……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Hm, I’m not sure that’s what it was...
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230101, '你知道吗，我爷爷以前是镇长。我很爱他，每个星期三我都跟妈妈去看他！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230102, '打扰一下，你知道他们在那座岛上找到了什么吗？跟那个……呃，叫什么来着？比洛尔？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230103, '金矿脉。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Gold veins.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230104, '宝藏。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Treasures.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230105, '成堆的糖果。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Heaps of candy.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230106, '哦！那些闪闪发亮的黄色石头，我在铁匠铺见过一块！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Oh! The shiny yellow stones, I saw one of those at the blacksmith once!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230107, '嘿嘿，你真逗！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Hehe, you’re funny!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230201, '上学太无聊了。我宁可跟布里克去练几拳，至少他知道怎么玩！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230202, '别人总笑我记不住暴风城第二任国王的名字。越来越丢人了……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230203, '塞奥登·乌瑞恩。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Theoden Wrynn.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230204, '巴拉森·乌瑞恩。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Barathen Wrynn.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230205, '莱恩·乌瑞恩。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Llane Wrynn.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230206, '当然！我真该记住他的名字。谢谢你！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Of course! I should really memorize his name. Thank you!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230301, '神父说我该多和教堂里的其他人说话，但我有点害羞……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Father said I should speak more with the others here at the church, but I am a bit shy...
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230302, '上周上课时我打了个小盹，错过了讲谁跟巴罗公爵和暴风城关系密切——你能提醒我吗？我不想让阿尔金特修女失望。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230303, '阿诺尔家族。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Arnor family.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230304, '格拉汉家族。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Grahan family.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230305, '普瑞斯托家族。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Prestor family.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230306, '谢谢你！阿金特修女是位非常好的女士，所以我想尽力让她微笑！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Thank you! Sister Argent is a very nice woman, so I want to do my best to make her smile!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230401, '妈妈躺在这里。爸爸说她现在去了一个更好的地方，可我不懂。最好的地方不就是跟我们在一起吗？我希望她快点回来，好再跟我和约书亚一起玩！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230501, '＜男孩一言不发，表情相当呆滞。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The boy isn’t saying anything and has a rather barren expression.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230601, '我的妻子莉娜就长眠在这里。她走得太早了，而我对主上的职责又让我抽不出足够的时间陪伴孩子——埃斯特尔和约书亚。等这片土地恢复常态、和平重归，我就辞去职务，好好尽一个父亲的本分。这是他们最起码该得的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230701, '准备好测试你的箭术了吗？我的箭可是全北风镇最好的。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Ready to test your aim? My arrows are the best in all of Northwind.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230801, '这里的酒气和苦难让我觉得自己都被玷污了。暴风城的人就是这样敬奉圣光的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6230901, '那些可恶的兽人就是一群害虫。他们竟敢那样毁了我家的房子和地？还有我那几个没出息的儿子，怎么就这么窝囊？！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6231001, '为了交足贵族的产量指标，父亲早就被压垮了。家又被这些肮脏的兽人占据，对他而言实在太重了——我看他这回是彻底撑不住了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6231101, '母亲尽力维系着这个家，可在我们失去家园之前，这份亲情就已经在散了。我能做的就是帮着她。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6231201, '出了这种事，我们全家都很悲痛，父母肯定比我们更甚。几百年的家业刚立起来，就这么被人洗劫一空？我几乎无法想象那种痛苦。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6231301, '我丈夫的状态糟透了，孩子们也为我们的处境心神不宁。但我不会再让这种沉闷压着我们。这地方是我们用自己的双手和血汗建起来的，我们就要用这双手把它夺回来！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6236701, '我们从洛克莫丹带着货物来的。带着货从湿地坐船到暴风城，真是件苦差事。幸好矮人区的一个朋友借了这辆吉普赛大车给我，好把货运到琥珀郡。可惜他没告诉我这车破成这样，如今我只能等加尔迪姆把它修好，一边还得提防路上的危险。看来做买卖就是这么起起落落吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6236801, '哎哟！给索姆利当保镖还不够——现在还得兼他的杂役。这混账最好一到琥珀郡就请我喝一杯！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6236901, '<这头可怜的牲口不习惯这里的土地；它大汗淋漓，显得又累又沉重。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237001, '我和妹妹刚帮完黑海岸的族人，就遇上了这位云游女祭司。自从搭上前往暴风城的船，我们三人就一直同行。她挺爱冒险的，在我们那场命中注定的相遇之前刚去过阿拉萨拉斯。可惜她跟不上我们的脚力——这也可以理解。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237101, '奥尔加是我见过最有趣的人——跟我那个乏味的双胞胎哥哥完全不同。旅途中遇到她是艾露恩的恩赐。我觉得自己交到了一位一生的朋友。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237201, '唉，圣光在上，这些精灵还有他们那两条长腿！唉，我得站起来活动活动——我是来看那家酒庄的！我得亲眼瞧瞧，究竟是什么让阿拉萨拉斯的那些精灵那么高兴。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237301, '这些信可不会自己送出去！这些守卫最好早点放我去办事，对吧？我答应过我亲爱的妻子蒂娜，要在纪念日之前赶回家。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237401, '要是我能打开这把该死的锁就好了！这简直就是我父亲的作风——唉！他把他的「奥特兰克遗产」藏在这口破箱子里，我的耐心快磨光了。一个老顽固能犟到什么地步，连唯一的传家宝都不肯留给自己的儿子……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237501, '这些书架上几乎没什么值得读的。要是我没把每一本都至少读过两遍，它们本来或许还值得一看……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237601, '我本以为这里是养老最好的去处，可我又一次得不到安宁。你看，我特别容易忧心——一定是因为当年我们只能把自己锁在铁炉堡里，祈祷兽人别来洗劫我们的家。我是个普通的人，这辈子从没举起过武器，我害怕接下来的日子会带来什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237701, '新来的吧？希望你别惹麻烦。不然你就得对上我。大家都叫我布里克——我瞧着一副不起眼的样子，可我这脑袋跟黑曜石一样硬。所以除非你的下巴想会会我的额头，我劝你别沾麻烦。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237801, '＜大声打着呼噜。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Snores loudly.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6237901, '我喜欢坐在椅子上看这座镇子。从前每天都能看见孩子们在落叶堆里玩耍，高高兴兴地围着转。如今这样的安宁被人夺走了。孩子不是失踪，就是被疑神疑鬼的父母关在家里。要是我年轻五岁，我就提上剑，让这一代人看看这种时候该做什么！可我偏偏腿脚不中用，还养了个懒骨头儿子——这会儿多半还在睡。好在圣光给了我几个更争气的女儿。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238001, '我父亲以前常在这小池塘里钓鱼，可他从不把鱼带回家。我想他是为那些鱼感到难过——说到底，它们是在囚禁中被养大的，能游的范围就那么小。我有时想，他决定加入迪菲亚的时候，是不是也这样看待我们的家。嗯，结果他在监狱里得到了跟期望相反的东西。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238101, '我这辈子注定要堆干草，而我哥哥却离家出走，躲在暴风城安全的城墙后面当起了了不起的猎人。我倒想知道他到底在猎什么——老鼠，还是下水道里爬的那些东西？我还真想念那个傻瓜。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238201, '抱歉，比武期间，旅店、酒馆和比武场之外的地方一律停售酒类——琥珀木领主不想让醉汉四处游荡，在这类场合惹出争执。你要是想买我酿的酒，只能改天再来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238301, 'Anu belore dela\'na。王国之内，气氛日益紧张。人们恐惧、不安、疑虑重重。这些疑虑蒙住了他们的心，也为不信任敞开了大门。在这样的时刻，昔日的英雄能给我们慰藉——不正是他们对世人的信念，为我们族人的兴旺打下了根基？$B$B守护这座祭坛、向那些堪为众人楷模的英雄致敬，是我庄严的职责。无论付出什么代价，我都不会背弃它。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238401, '嘘！小声点！我正躲着布里克呢，你跟一堆树叶说话可帮不上我藏好的忙。快走开，别等他那核桃脑袋想明白！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238601, '守住道路畅通一天比一天难。龙喉兽人眼下或许是被打退了，可他们卷土重来只是时间问题。$B$B我祈祷到时候我们还有力气再把他们打回去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238801, '什么风把你吹到阴森之地来了？要是来看风景的，那我有个坏消息。你唯一能看到的，就是遍布乡野的龙喉兽人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6238901, '我的职责就是留意治下的人口，稳稳当当记清我们地界内住着多少人。谁住在这儿、住在哪儿，我都一一登记。$B$B作为丹基塔斯的书记官，我也负责记录并整理针对议会本身的陈情。你要是对丹基塔斯有什么顾虑或建议，告诉我，我可以转呈议会。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239001, '这一带的历史浸透着传统、冲突与繁荣。阴森之地曾是肥沃宜居的土地，许多家族与贵族就住在格瑞姆巴托本身的宏伟厅堂之中！$B$B我们的故事饱经风霜，满是艰辛。我们挺了过来，也学会了应变，去面对那些一再想要毁灭我们的威胁。其中许多威胁早已消失，而我们还在这里——这正是阴森之地矮人意志力的明证。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239101, '再跟我说说斯托尔加兹要塞陷落的经过。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Tell me more about the fall of Stolgaz Keep.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239102, '再多告诉我一些关于巴戈斯的事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Tell me more about Baggoth.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239103, '或许也是位同行史家？你是来了解伟大的巴戈斯·铁袍的吗？阴森之地那位声名显赫的将军与缔造者？你知道正是巴戈斯亲自筹划了对龙喉第一次入侵的防御吗？$B$B……还是说，你对几年前斯托尔加兹要塞的陷落更感兴趣？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239201, '欢迎，请随意些。丹基萨斯向来以好客闻名！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Welcome, and make yourself at home. Dun Kithas is known for its hospitality!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239301, '我是黑炉看守，负责保管丹基塔斯的档案。记录何人、何时、何地发生了何事，是我的职责。谁要是偷窃、或是说别人坏话，都会由我记下来……$B$B我劝你安分些，你最不想要的就是自己的名字出现在丹基塔斯的档案里。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239401, '你有什么事？没看见我们正忙要紧事吗？我可没工夫应付从境外跑来的多事冒险者。还有更急的事等着处理。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239501, '欢迎来到丹基塔斯，我是地方法官胡尔达姆·硬手。我在此地被选为执政之长，与同僚议员们一同裁定哪些事该做、哪些事不该做。这些决断分量极重，从琐碎小事到要紧大事都涉及。你若有待办的事宜，或有该呈给议会的顾虑，请上楼去找书记官砾冠。他会给你相应的文书，好把任何陈情、顾虑或建议提交到我们下次会议上。$B$B哦，还有，别在意丹德格，他脾气有点急，也不太待见外人的看法。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239601, '要想让我们的人民得到和平，行动就必须果断！兽人在阴森之地盘踞得太久了，是时候把他们赶出去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239701, '黑暗正悄然渗入阴森之地。我的守军已捉襟见肘，四面受敌。我在指挥巴戈斯之墙的防御时，这片土地本身也开始被鬼魂与杂种占据。我很希望你是来相助的——什么样的援手我们都用得着。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6239901, '有什么我能帮上忙的吗，外乡人？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Is there something that I can assist you with outsider?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6240001, '你好，欢迎你，冒险者！我的职责就是把世上最新的消息带给丹基塔斯的市民，并宣告我们伟大议会的意旨。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6240501, '那些该死的……那么多心血，一瞬间就没了$B$B<格罗尔丹还在含糊不清地嘟囔着。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6240601, '我们本已快要发掘出某些了不起的奇观。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- We were on track to uncovering some great marvels up at the excavation.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6240701, '我来这儿是为了发掘古代遗物，结果现在困在这儿，等着探险者协会的消息。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241101, '我早就警告过他们，穴居人迟早是个麻烦，可就是没人愿意听老克格这套疯话。$B$B<克格发出一阵癫狂的大笑。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241201, '我大老远从铁炉堡赶来，家族对丹基塔斯这边的一些地方习俗很感兴趣。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241401, '阴森之地是艾泽拉斯资源最丰富的地方之一。我大半辈子都在寻找一种稀有的宝石，我想它也许就埋在这儿这些丘陵底下。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241601, '这世上还有太多谜团等着揭开。不把每一块石头都翻过来，我们决不罢休。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241701, '如果你需要锻造的活儿，可以去找玛格拉……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- If you need any blacksmithing work, you can talk to Margella...
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241801, '如果你需要锻造的活儿，可以去找拉格丹……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- If you need any blacksmithing work, you can talk to Ragdan...
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6241901, '如果你需要锻造的活儿，可以去找法利格……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- If you need any blacksmithing work, you can talk to Farleg...
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242101, '一个凡人？在这里，在阴森谷？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- A mortal? Here, in Grim Hollow?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242102, '跟我说说斯卡丁的事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Tell me about the Skardyn.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242109, '＜继续＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Continue>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242201, '哎呀你好啊，冒险者。我们俩挺像的，都在外头忙着把世界从那些黑暗、邪恶又吓人的东西手里救出来，对吧？也许我是在自作猜测，可你看着就像那种会向需要帮助的人伸手的人。$B$B我得承认，这是种令人敬佩的品质——我们俩都有。我们可真是好人啊。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242301, '多萨斯出了名的爱唠叨，我只要点头直到他说到重点就行。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Dorthas is known to ramble on, I just nod my head until he gets to the point.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242501, '在这里小心点，我可不容忍任何人惹是生非。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Watch yourself here, I won’t tolerate anyone causing trouble.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242601, '这片土地被战火蹂躏，因纷争而虚弱。或许现在正是部落宣示主权的时候。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242801, '一个强壮的兽人能扭转任何一场战斗的胜负，而一位强大战士的武力足以改写历史。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6242901, '想找块好肉？眼下我只有这些，但包你满意。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6243101, '该死，这活儿做得太糙了。我们的攻城器械又笨又过时，这种投石机的设计还有很大的改进余地。要想在阴森之地站稳脚跟，我们需要好得多的装备和机械，才能支撑起像样的攻势。$B$B他们要是指望我干出点名堂，我就得加班。我看没法再回到老部落那套口诀了——「往问题上再扔几个兽人」。我们的兵力本来就不够。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6243201, '你能感受到这里的力量吗？它飘荡在空气中，等待被人攫取。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Can you feel the power here, it drifts upon the air, waiting to be seized.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6243301, '欢迎你，冒险者。很高兴看到又有一个热血的人远赴边陲来寻荣耀。我是这座基地的指挥官，在这片土地上执行酋长的意志。若真要把这儿变成我们的土地，就必须为眼前的冲突做好准备。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6243401, '我是拉娜格，阿格娜什的顾问。能有人相助总是好事，哪怕是在这样的异乡。$B$B你带来了奥格瑞玛的消息吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6243501, '就算在这种陌生的地方，战士也得有个地方歇脚、恢复力气。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244301, '抚摸乳酪巫师。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Pet Cheese Wizard.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244302, '＜乳酪巫师茫然地盯着玛姬露，审视着她的一举一动。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Cheese Wizard stares blankly at Magilou, judging her every move.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244401, '＜抚摸鲍比·乔。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Pet Bobby Joe.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244402, '＜鲍比·乔在树荫下舒服地睡着。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Bobby Joe sleeps comfortably under the shade of the tree.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244501, '抚摸米丝蒂。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Pet Misty.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244502, '＜米丝蒂深深地凝视着你的双眼。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Misty stares deeply into your eyes.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244503, '＜米丝蒂发出呼噜声，嬉闹地轻咬你的手指。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Misty purrs and playfully bites at your fingers.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244601, '抚摸猴子。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Pet Monkey.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244602, '＜猴子绕着一堆堆东西飞快地转圈。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Monkey zooms around in a circle from pile to pile.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244701, '我是辅祭！格雷厄姆修士说这可是份重大的责任。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I am the altar boy! Brother Graham said that is a huge responsibility.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244801, '我和贝蒂在玩捉迷藏。不过她从来赶不上晚饭前来找我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Me and Betty are playing hide and seek. She never finds me in time for dinner though.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6244901, '杰瑞米是个大坏蛋。他那个破藏身点我永远也找不到，可他还老要玩这个。我只想玩过家家……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6245501, '对我而言，巴罗不过是父母用来开玩笑吓唬我的一头母马——好让我对暴风城外的凶险有个准备。后来我还照着讲给我孩子听，我丈夫对此很是不以为然。如今我到了这儿，反倒希望那些吓人的故事才是现实。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6245601, '＜这位暗夜精灵用近乎轻蔑的目光打量着你。真是令人心寒的性情。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The Night Elf eyes you with an almost condescending look. What a chilling disposition.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6245701, '新来的？这地方独一份，就算对我这种见多识广的人来说也一样。机灵点，别放松警惕——你永远不知道下一个转角等着什么！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6245801, '你好！我叫诺普西·斯皮克斯潘，负责归档这次行动期间发生的一切。巴罗的历史十分丰厚，自从第一次大战中暴风城失去它之后，还有许多谜团悬而未决。你要是发现什么文件或类似的记录，尽管拿来给我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6245901, '<矮人从酒杯里啜了一口。>$B$B啊！跟你说，要是没带上我心爱的雷酒陈酿，我就只能跟诺普西和他那套无聊的研究，或者他别的什么勾当混在一块儿了。这酒给我提劲，没别的东西能比；我能放倒任何一个兽人！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246001, '我来自戴文堡，那是设在暴风城港口的库尔提拉斯使馆。包括我在内的同胞们，正竭力与联盟重修旧好。因此协助军情七处完成这次任务是我的本分。再者，这座岛上肆虐的风暴极为反常，本身就值得一查。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246201, '这么邪门的地方我很少见到。这座岛上处处是死亡与痛苦的气息。最好什么都多做点准备。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246301, '这潮湿的空气对我的宝贝武器来说简直是毒药！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- This humid air is like poison to my beautiful weapons!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246401, '我们的床也许不算舒适，但足以让你恢复体力。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Our beds may not be comfortable, but they will offer enough rest to regain your strength.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246501, '这座岛把我的狮鹫都吓着了，我很难让它们安静下来。你要是想飞回暴风城，知道上哪儿找我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246601, '仆人都跑哪儿去了？我的草莓芭菲已经等了三个多小时。谁要是敢在我的甜点上磨磨蹭蹭，那就是他在我哥哥手下干的最后一天！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246701, '废墟。毁灭。死亡。这座昔日葱郁的岛上，再也找不到别的了。我记得那些青翠的树木与丘陵，记得夹着甜咸味的微风越过山峦，记得阳光温暖地落在皮肤上。这些全都消失了。你能看到的只有悔恨与苦难。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246801, '这些姑娘到底在想什么？在这种只有地精桑拿房里才有的连绵阴雨和湿气里修飞艇？我不知道这算是对我本事的信任，还是她们脑子坏掉了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6246901, '想来块泡软的牛排？还是来点湿透的弹药？保证几乎有一半的时候能管用！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247001, '没错，这地方遍地都是历史，等着人去挖！等我带着惊天发现回去，探险者协会那帮老家伙的表情一定精彩极了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247101, '这座岛在生病，病灶在里面滋长，急着要破出来。我的萨恩多到底在这鬼地方找什么？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247201, '我和哥哥上次待在暴风城已是许久以前。自从离开洛丹伦，我们就没离开过塞拉摩，所以这次重聚让我又喜又涩。不过我不能让这些影响我在比武中的表现。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247301, '阿勒萨努力装出坚强的样子，可我看得出她撑得很吃力。我们家族出身暴风城，第一次大战后逃到洛丹伦，所以我只能想象她心里翻涌着什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247401, '普罗德摩尔女士选了我与远风兄妹作为我们这座港口城的代表。她希望不仅与暴风城、也与其他人类王国增进往来。这目标令人敬佩，我绝不会让她的抱负落空。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247501, '这种时候还要办比武大会，实在让人费解。这些暴风城人到底在想什么？难道他们看不见自家门前的光景吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247601, '我家在激流堡郊外有个不起眼的小农场，可我如今站在了这里。能被选为王国的代表，我深感荣幸；无论如何，我都要让他们以我为傲！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247701, '光是站在这儿我就直打哆嗦。我宁可回激流堡帮我的弟兄们，可外交事务要我参与……这个。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247801, '被迫参加这种白痴比武大会，对任何一个正直的库尔提拉斯人都是耻辱。那些叛徒混账以为这样能成什么事？！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6247901, '请务必原谅马勒维勒的态度。他在第二次大战中失去了许多好友和战友，也亲身经历过其中的种种惨状。我保证会管着他，别让他失礼，也别让他伤到人，这话我给你担保。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248001, '听说海军部为我们库尔提拉斯人参加这场比武争论得很激烈。看来在对暴风城的关系上，他们分歧不小。就暴风城跟部落的外交走向来说，我也不好怪他们这么想。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248101, '这些小年轻太容易小看我这把年纪的人了。等着瞧，我让他们看看达拉尼人的脑子是怎么长的！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248201, '我主人是个热血的人，我很少见到谁像他这样以达拉然为傲！有他参加比武，我们绝不可能输掉比赛！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248301, '你看见那边那个从激流堡来的银发帅哥了吗？他是不是很迷人？$B$B<莫德拉一看到勒德尔指挥官，眼睛就亮了起来。她显然被他的相貌迷住了，一时忘了自己说到哪儿，随即又赶紧镇定下来。>$B$B哦，抱歉。真失礼。我是凯特琳·莫德拉，达拉然六人议会、大法师莫德拉的女儿。你可能已经听说了，母亲正忙着重建我们的伟大城市，所以由我代她前来代表达拉然。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248401, '先是赤脊山，现在又是北风镇？这些兽人难道不知道自己的分寸吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- First Redridge and now Northwind? Do these orcs not know their place?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248501, '＜你迎上一道冰冷的目光，清楚地感到自己不受欢迎。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <You are met with an icecold glare, and feel definitely not welcome here.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248801, '派我一个人来这儿，我拿不准肖尔大师是信任我的能力，还是在变着法儿罚我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6248903, '＜这位女子浑身颤抖，痛苦不堪。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The woman is shaking and distressed.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249001, '年轻女子一动不动地躺在地上。她的皮肤摸上去冰凉，生命早已离开这具躯体。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249002, '＜检视尸体。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Inspect the body.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249201, '＜检视遗体。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Inspect the corpse.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249202, '这具男尸伤得极重。刺伤和扭曲的四肢让他几乎面目全非。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249301, '这只鸭子呼吸沉重，左翼似乎受了伤。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The duck is breathing heavily and seems to have injured its left wing.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249401, '听起来你需要一些帮助。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Sounds like you’re in need of some assistance.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249402, '我在这破地方多待的每一分钟，都让我为自己宝贵的时间感到懊悔！我和随从们从暴风城的宅邸一路赶来，穿过林子里那些可怕的凶险。我的目的是在领主大人那里取得影响力，在北风这片富庶之地挣个半正式的名分。可现在，我那只定制手袋连同纹章戒指都被人偷了——明明我一直贴身带着！一想到有人把那双恶心的手伸到我身上，我就恶心得想吐。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249801, '我向你发起挑战。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I challenge you to combat.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6249802, '＜拉兹贾尔投来充满敌意的目光。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Razjal gives you a hostile gaze.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251301, '我和妻子把全部家当凑到一块儿，想在北风这边安家。早知这里的情况糟成这样就好了。我不怀疑琥珀木领主是个心善的人，可万一他不肯收下我们这点微薄的礼、不让我们在他的城堡里暂住，我真不敢想后果。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251401, '我们族人中有许多加入了前往阿拉萨拉斯的远征，把那座古老遗存重建了起来。我们不是。我们没法忍受活在过去的阴影里，像拖着鼻涕的孩子求母亲原谅那样抓着不放。对我们来说，前方是一条新路……离我们不得不忍受的那些惨剧越远越好。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251501, '圣光在上，我的耐心快耗光了。这王国是突然被一群彻头彻尾的蠢货给占了吗？！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251601, '真是好极了。先是要我们一路穿过这些几乎没人看护的街道，现在还得等着领主接见？我们往北风跑了这么多年，从来没碰上这种事。简直不像话！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251701, '从来没人来看望主人，你出现在这里已经够让人心烦了。求求你，不管要办什么事，快点办完吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251801, '＜揉揉他圆滚滚的肚子。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Ruffle Bristlebelly over his round tummy.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251802, '＜这头野猪鼾声如雷。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The boar is snoring loudly.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251803, '＜鬃腹十分享受这阵挠痒，在温暖的落叶中打滚。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Bristlebelly enjoys the scratches thoroughly and rolls around in the warm leaves.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6251901, '你要是觉得这儿可怕——哈！那你进安德麦的贫民窟时才有得受。跟那个鬼地方比，这岛算什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6252001, '尤妮为我们困在这儿而自责。她该把力气花在找维里克斯算账、把指南针夺回来上。我更喜欢看她动手办事，而不是闷头生闷气。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6252101, '这本来该是又一次例行的运货，跟以往没什么两样。可不行——那个自以为聪明的地精维里克斯非得改道，说什么「近路」能省下大把燃料。结果这条近路正好从一座被永不停歇的雷暴诅咒的岛上空经过，闪电当即劈中了我们的飞艇，把我们困在这儿！我们已经为活命拼了两星期，士气都开始消磨了。不过你站到我面前，一定是幸运女神对我们这份坚持的奖赏。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255401, '有肉吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Fleshy?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255601, '我还活着简直是奇迹。这些怪物残忍得无法形容！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- It’s a miracle I am still alive. These monsters are ruthless beyond measure!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255701, '＜检视尸体。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Inspect the body.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255702, '这似乎是德瑞尔特工的同袍。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- This seems to be one of Agent Deryl’s compatriots.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255801, '＜检视尸体。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Inspect the body.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255802, '这似乎是德瑞尔特工的同袍。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- This seems to be one of Agent Deryl’s compatriots.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255901, '＜检视尸体。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Inspect the body.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6255902, '你面前是一滩绿色的污泥。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Before you lies a puddle of green sludge.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6256101, '＜这位女子已奄奄一息。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The woman is on the verge of death.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6256801, '在人迹罕至的路上要多留个心眼。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Keep your wits about you on the less traveled roads.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6256901, '复杂的图纸往往要用复杂的材料。有时候，老老实实用更可靠、更简单的做法，反而能推进得更快。除非你想造的是真正开天辟地的东西，否则别浪费时间把一个小玩意儿设计得过分精巧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6257001, '这座岛上的风暴不合常理，透着一股阴冷的诅咒。它们带来的风毫无生气，雨里写着注定败亡的未来。踏足这片水域时务必当心。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6257101, '这是我最后一次欠内尔特人情。把我跟这群兽人凑一块儿，简直是我这门手艺的浪费！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6257201, '在这儿想睡个够大概只能算奢望，不过能睡多少，我尽量让你睡多少。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6257301, '小奥金若想有朝一日继承父业，还有许多要学。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Young O’jin still has much to learn, if he intends to succeed his father one day.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6257401, '想回格罗姆高营地的话不用担心。我的双足飞龙轻轻松松就能穿过这场风暴。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258001, '你和这里的其他贵族不太一样。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- You’re not like the other nobles around here.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258002, '你怎么看这场马上长枪比武大会？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What’s your opinion on the jousting tournament?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258003, '为什么禁止你离开要塞？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Why is it forbidden for you to leave the keep?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258004, '<年轻的贵族懊恼地叹了口气。>$B$B哦，你好啊，善良的平民。守卫居然放你进了琥珀木城堡，真叫人好奇——毕竟北风眼下……就说「岌岌可危」吧。你是塞了钱，还是天生就这么有魅力？唉，既然你都站在这儿了，不如来陪我解闷。约瑟芬姑妈连城墙都不许我上，我一遍遍读着同样几本旧书，快被闷死了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258301, '你想参加我们在巴罗的行动吗？我那匹忠实的狮鹫钢翼可以送你过去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258601, '总有一天，我的肩膀要挑起更重的担子。但今天，我只是个部落之子——为部落而战。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258701, '暗影议会。暴掠氏族。古尔丹的傀儡——我也曾有过同样的命运。别把我和你们那些被遗忘者盟友混为一谈，也别把我看成一个误入歧途的普通术士。我统御着扭曲虚空最深、最冷的角落。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258801, '在这座岛上，我感受不到大地母亲的注视。这里的天色始终阴沉，看不见安舍，看不见穆莎，连洛舍也见不到。有邪恶的魔法在作祟，必须以怒火相迎。最初指引我来到这里的，不过是我们的主母要我来表一份善意这样简单的事。$B$B然而，我离安舍的温暖越久，怒火就越是灌满我全身。我对你、对我们眼下的盟友既无爱也无恨，部落之子。但我不会坐视不理。这些浸透了邪能的跳蚤，不能再让这片闹鬼之地失去太阳。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6258901, '听着。倾盆大雨里夹着天空的轰鸣。就像有位雄伟的存在挥舞着长鞭，把云层抽打得俯首帖耳，好让它们的煎熬永无止境——雨也永不停歇。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6259001, '有个问题一直在我脑后作痛：这个世界真的把我忘了吗？我曾经的种种——不论出于选择还是命运——都失去了。$B$B无论我把目光投向何处，都什么也看不见。什么也看不见。这个新部落，我们族人的未来，抛下了我。可我绝不会抛下它。$B$B许多人唱诵我的死，好把过去就此埋葬。可我仍站在这里，准备终结古尔丹留下的那点残喘的苦难。我感到的是责任，却也有嫉妒。是什么让我与格罗玛什·地狱咆哮不同？难道他最后的举动就那么伟大，足以抹去他的过去？$B$B我记得他的名号被当作英雄来歌颂时，我却被人当作老朽打发。或许我这般心思并不体面，但我不会就此湮灭。我的名字终将立在传奇之中——不是靠死，而是靠赎罪。$B$B暗影议会将面对我的氏族、我的先祖，以及我的力量的怒火。$B$Lok-tar ogar！$B$B为了部落！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262001, '快进来吧，可怜虫；咬一口我们专利的「香肠奶酪面包」，你这辈子就再也看不上别的吃食了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262101, '切罗克斯和我琢磨出了艾泽拉斯前所未见、最具创意的烹饪杰作！这样搭配的口味与口感，从来没人做过。它能把你直接掀个跟头，让你爬着回来再要一份！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262301, '跟你说，风险投资公司那帮蠢货就是会惹麻烦。像我这么个老实本分的地精，在这种条件下还怎么好好偷懒？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262401, '嘿，老兄，我知道你想尽快离开这儿，怪不着你。可你得先掏点钱出来，懂吗？老板给的工钱是不错，可姑娘家总得为自己的将来打算，对吧？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262501, '在滚烫的沙漠里走了一路，想喝点解渴的？那你可来对地方了，$C。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262601, '你闻到了吗？那股刚抽上来的油，浓烈又油腻的味道？啊，睡前狠狠吸上一口，做梦都能做出最离奇的点子。你自己也该试试，老兄！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262701, '在这种沙地里维护机器简直是场噩梦！沙子到处都是，把每个角落缝隙都塞满了这些该死的砂粒。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6262801, '你想要的东西我这儿都有。除了「保证不自燃」这一条。抱歉了，老兄。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6263401, '什么风把你吹到阿祖拉之塔来了？是为求知识，还是为那更宏大的奥术？$B$B不管是哪一样，我想我们都能帮上忙。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6263601, '孤峰才不是苔皮族的首领！从来都不是！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Gowlfang no leader of the Mosshide! Never was!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6263701, '别害怕，凡人。我不会加害于你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Do not be afraid, mortal. No harm will fall upon you by my hands.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6268101, '欢迎来到滑芯石油钻井，小子。拿上你的扳手、油桶和工装裤，地下有大把液体黄金等着我们挖出来！$B$B……当然，得先收拾掉风险投资公司那群蠢货。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6268201, '你要是找老板有事，先跟我谈。她忙得不可开交，任何打扰都可能严重拖累我们的产量。还有，这儿的东西你连碰都别想碰，否则我们就把你扔进火花港的地牢里去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6268301, '我能囫囵个儿走到这儿简直是奇迹，老兄。跟你说，这片沙漠时时刻刻都想要你的命！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6268401, '<一道冰冷的目光让你脊背发凉。>$B$B你最好趁早滚蛋，老兄。我今天不想弄脏手。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6269002, '它来了！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6269701, '生意从前可比现在好，小子。你要是走了一路又饿又没力气，我这儿有整个北风最上等的野味！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6269801, '没有什么比钓鱼这种简单的日子更好了。抛出鱼线，剩下的交给自然。我能想象在另一种人生里，我也许会做些稍微复杂的事……比如用双手雕刻建筑或器物。$B$B<渔夫努德雷瓦顿了一下，然后耸了耸肩。>$B$B算了，别管这些了。有什么我能帮你的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6269901, '喵。$B$B＜这只猫注视着渔夫的一举一动，期待着有鱼上钩。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Meow.$B$B<The cat watches the fisherman’s every move, anticipating a catch.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6270601, '朋友，要不要看看收藏爱好者圈子里最新鲜的玩意儿？宠物石头正是眼下风靡全艾泽拉斯的宝贝，而你呢，善良的$c，正好来到了源头！我这些独一无二、限量发售的宠物石头，能给你带来好运、令人艳羡的情场生活，还有足以轻松击败任何敢挡你去路的蠢货的力量！怎么样，我勾起你的兴趣了吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6271001, '我以前逃离过黑暗。出于羞耻。出于愧疚。出于厌恶。过去的我沉溺于古尔丹那些卑劣的算计，我们膜拜的暗影迷人而强大。在偶遇那位守望者之后，我做出了选择：要么在自己煎熬中死去、被深渊巨口吞噬，要么直面过去，确保自己不再被它那摧毁性的掌控锁住。$B$B说话吧，陌生人。你愿意帮我成为暴掠氏族的最后一人吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6272701, '自然之美必须受到保护，并不惜一切代价加以维护。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The beauty of nature must be protected, and upheld at all costs.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6272901, '哦，风啊，吹过我迷人的鬈发！……迷人的胡须卷。$B$B你飞过吗？那感觉美得很。你要是想体验一回自由落体的优雅，又有只有我这儿才有的保障，那就跟我说一声。这么绝妙的感受，几个铜板就卖你，行吧？！只是落地前记得把伞打开。已经有好几个人因为太心急而摔了个嘴啃泥……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6273001, '厅堂寒冷空旷，毫无生机。只剩下压抑的黑暗。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The halls are cold and barren, devoid of life. Only the oppressive darkness remains.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6273201, '我已经开始想念阿拉萨拉斯了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I miss Alah’Thalas already.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6273301, '阴森之地或许悦目，但别被它的美景迷惑。这片土地之下盘踞着沉睡的黑暗。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6273401, '塞隆领主交给我们一项极其重要的任务。你若没有要紧的事要报告，我建议你别来打扰我们办事。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6273601, '你必须离开这里！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- You have to get out of here!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6273602, '＜这名俘虏浑身发抖，毫无反应。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The captive is shivering and not responsive.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6275201, '这片土地已不复往昔。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- These lands are not what they used to be.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6275501, '走路小心点，朋友。阴影就潜伏在你的弱点旁，别让它们得逞。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Tread careful mon, the shadows linger upon your vulnerabilities, show them none.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6279501, '我已有些时日没从我们的隧道里出来了，很想再看看月语海岸……$B$B如今这片土地上只剩下支离破碎的盟约与敌意……可我仍旧渴望再看一眼它那独特而美丽的土壤。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6279601, '自然之中少有绝对之事。浅薄之人只当火是毁灭之物，可没有它，这世上的生命便无从繁盛。旅途中牢记这一点，否则你真正的潜能便无从舒展。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6279801, '大地之环在艾泽拉斯各处总是需要协助。你若遇到我们教团的成员，不必犹豫，尽管支持他们——我们正致力于修复大地母亲的平衡。作为回报，我们也不会吝于酬谢你的付出。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6279901, '你若为冥想而来，请去请教其中一位灵魂向导。否则，请不要打扰这片圣地的安宁。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6280101, '新来的学徒很有出息，可同时也天真得厉害。这让我想起自己在莫高雷受训的日子。故土的辽阔平原令人神往、令人敬畏。那时我并不知道大地母亲正受着何种病痛折磨。正因如此，把这些年轻人准备好去面对世界的真相，才更加重要。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6280301, '水总是沿着阻力最小的路流。它善于变通，柔韧而多谋。这听着温和，但只要有足够的时间和压力，那道瀑布会连沿途的一切一并侵蚀掉。永远别忘了这一点。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6280401, '与大地交流。听听它的心跳，庄重而沉稳。大地藏着无数秘密等着被倾听——只要你肯听。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6280501, '暗矛部族曾以古老的巫毒法术窥探我们之外的位面。这门传统我们已经失传大半。虽然我们从兽人那里学到了许多萨满之道，但把本族的学识传给后世，对我而言至关重要。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283301, '我大半辈子都在这些山径上游荡，在千针石林的荒野里打猎。直到最近，危险才逼近我的土地。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283401, '风角部族几乎被灭绝，家园被人夺走，我们如今只能流离失所，做难民、做游民。$B$B我回到这熟悉的地方，是为了复仇。可这件事我一个人办不到……你愿意做我怒火的这只手吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283501, '马尔甘心里积了很深的怨。不管我怎么做，他看来都已打定了主意。我不怪他，我们几乎被夺走了一切。我留在这儿，只是别让他把命也搭进去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283601, '我小时候，一伙半人马在我们的商队行进途中杀了我全家。是风角部族救了我，收养了我。我永远欠他们的情，也把风角峡谷当成家。如今得知恐怖图腾盘踞在那里，我心里像烧着一把火。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283701, '长者，为什么恐怖图腾没有像对待其他人那样伤害你？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Elder, why do the Grimtotem not harm you as they have the others?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283702, '<年迈的牛头人站在你面前，目光枯瘦，带着几分惊讶>$B$B嗯，你显然不是恐怖图腾。你能登上这些峰顶，我得说声佩服——如今占据这里那些人，看着可不怎么欢迎外人。$B$B<斯克伊斯特尔伊德长长地呼出一口气，目光掠过风角峡谷的峭壁，眼里闪着微光>$B$B多美啊，不是吗？我的族人在这片崖壁上游荡了许多代，在石头里凿刻留下痕迹。那样的日子看来已经过去了。我这把老骨头，一年比一年更乏。我能感觉到，我的时辰快到了，就像风角一样，我也终将逝去。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283801, '大自然赐予我们丰饶，让我们得以置办货物。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Nature has been plentiful in our bounty to procure goods.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283901, '发生了什么事，让你们沦为难民？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- What happened to make you refugees?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6283902, '我们家族世居千针石林。那是我们祖辈的家园，是我们走过不知多少代人的地方。如今我们的生活被彻底掀翻，落得个难民的下场。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6284001, '这片土地美得动人，也一样危险重重。这些日子就算是走大路，你也得时刻提着心。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6284201, '我来自辽阔的千针石林。我们这支被放逐的部族一直在寻找能称之为家的新地方。我们多半把月蹄的兄弟姐妹视作表亲，所以再没有比这儿更适合重建生活的地方了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6284401, '月蹄部族的名字来自古籍，那里面记载着我们的伟大母亲曾与双月同行。守护这片土地、让它保持神圣，是我们的传承。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6284501, '黑风部族该庆幸他们攻占我家乡时我不在场。得知他们闯进来杀害我的亲友时我却在外面打猎，这口气烧得我五脏俱焚。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6284601, '已经很久没有外人踏足月语海岸了。是什么风把你吹到这儿来的？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6284701, '我在风角峡谷的家里听过许多关于我们月蹄表亲的故事。都是些夸大的传说，说他们能在星辰间起舞，沐浴在蓝色之子的丰厚馈赠里。$B$B<塔加沙轻笑了一声>$B$B有意思的是，这些小小的传闻怎么就这么快变成了神话。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285001, 'Okhal-asha，陌生人。我是摩洛盖·克拉，我族的酋长，欢迎你来到我们这座简陋的村子。我们是个爱好和平的民族，多年前逃离了垂死的故乡世界，只为寻一处安身之所。可危险与不安仍困扰着我族人的心——邪恶的势力已开始侵犯，威胁着我们建立新家的梦想。若你对安宁的渴望与我们相同，那么请你相助，帮我和我的人民度过这些新的劫难。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285002, '莫罗盖的克拉，我和你的儿子有些问题要问你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Moro’gai K’la, your son and I have some questions for you.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285101, '你好，远方来的流浪者。我们德莱尼敬奉神圣的德拉诺水晶——那是由故乡德拉诺的血脉凝成的纯净晶体。当年我们的部族借古老的裂隙行走之术逃到此处，术法残留的能量渗入了你们这个世界的土地。日久天长，这些原本异乡的晶体便开始自行生成。$B$B随着黑暗在平原上蔓延得越来越快，我们已很难再采到多少珍贵的德拉诺水晶。村子全赖这些宝石——无论灵性上还是魔法上，它们都承载着巨大的力量。你在沿海一带游历时若发现了它们，尽管拿来给我。你若这么做，我会以我们最上等的宝物相酬。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285201, '像你这样的小崽子，根本不知道该怎么在我这把年纪的人面前待着！整天东跑西颠，空脑袋里连个念头都没有，再这么胡闹下去早晚把命送掉！我背上这筐里，莽撞年轻人的骨头已经够多了，不缺你这一副！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285301, '走近些，帕拉什卡。我的货精致无瑕，日常制作要用的东西应有尽有。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285401, '我们的鱼鲜嫩够味，香料放得不多不少。进来尝尝吧，帕拉什卡！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285501, '坠落者日日夜夜围攻我们。帕拉什卡，还望你在村里遵守规矩。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285601, '我在照看这片土地上的鸟，据说它们叫平原陆行鸟。这鸟脾气不小，还常常执拗，可对它们有耐心总有回报。它们的力气和韧性都让我想起故乡世界的那些鸟。我们叫它们「纳拉克拉」，用你们的话说就是「星翔者」。那是种难以捉摸的鸟，羽毛油亮，腿肉厚实，翱翔在德拉诺星光下的天空里。$B$B照料这些平原陆行鸟让我想起家乡；那通常是段痛苦的回忆，对我而言却是难得的一种慰藉。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285701, '我的货件件都是手艺精良的杰作，帕拉什卡。就算是你这样的外人也看得出有多上乘。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285801, '你看着就像是个对稀奇玩意儿有眼光的人。走近点，瞧瞧我这些你从没见过的珍禽异兽！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6285901, '今天湖面很平静，没什么鱼咬钩。怎么样，你自己想试试吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6286001, '我摆出的水果不多，但味道无可挑剔。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- My display of fruits is scarce, but their taste is immaculate regardless.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6286101, '德莱尼菜是要慢慢习惯的口味，牛头人可受不了我们厨房里那种典型的辣。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6286201, '交易') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Trade
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6286202, '你好，$C。在这群德莱尼中间看到我，你一定很意外——我是不是显眼得像个肿块。我在世上闯荡多年，学到了不少秘密，最后在这片中了邪的海岸上安下身来。我干的是珠宝加工，师从的是最好的老师。你要是想采买些材料，我非常乐意跟你做笔生意。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6286301, '编织奥术能量需要极高的专注。在它的压力下轻易动摇的人，不是被撕碎，就是被逼疯。我在本族部族的那些天真学徒身上见过无数次。告诉我，你们这种人，承受得住扭曲虚空那种纯粹的能量吗？我好奇得很。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6286401, '德莱尼拥有万古流传的古老制皮技艺，一代代传下来。我们处理兽皮与皮革的精深手法，至今无人能及，哪怕在这个陌生新世界里也一样。你要是对自己的手艺有那份自信，那就让我用我们自己的试炼来考考你。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6289601, 'Ishnu-alah，旅行者。什么风把你吹到这片海岸的月光田野来了？我和同伴们走遍艾泽拉斯，追寻冒险、谜团，偶尔也顺手弄点财宝——至少理查德是这样。就在几个月前，我们在大海彼岸的悲伤沼泽里陷入了一个极其凶险的处境——说「被缠住」一点不夸张。就是在那里，我们结识了那些可敬的德莱尼。你可以想象，我在这儿、在月语海岸又见到他们时有多吃惊。我上次来这里，真可以说是年代久远了……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6289701, '这片土地在低语着神秘的词句。含糊，又蒙着雾。维努里斯把我们带到了这片海岸。那是她族人的故乡，她记忆里的故乡却不是这番模样。这片海岸笼在阴影中，底下沸腾着，急着吞掉粗心的蠢货。走这些路的时候你最好当心。谁知道暗处潜伏着什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6289801, '不得不说，这些德莱尼做起辣菜来真有一套。不过没有我们在避风港喝的那锅炖菜辣，大概是加了沼泽草药的缘故。我的同伴们肯定也这么想。除了奥尔格拉——那女人总想压我一头。可正是这点让她招人喜欢，虽然我绝不会当面跟她说。也希望你别去说。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6289901, '鬼魂！当然得是鬼魂。我居然还想过会是别的东西，而不是亡者的灵魂，真是蠢。我发誓，等这边的事一了，我就要理查德连着守三个晚上的夜哨。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290001, '大地在痛苦中呼号。浸透它的这片混乱，是无数觊觎其力量、又毫不顾及后果的势力滋养出来的。我们卡多雷弃守这片海岸，已经太久了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290101, '这支远征队是代表珊蒂斯·羽月指挥官前来的。我们的斥候报告说，沿海一带出了怪事——原本平和的熊怪在林中横冲直撞，本地的德鲁伊团体也断绝了联络。背叛者夷平南迪斯之后，我们对这片海岸的巡查确实松懈了，这点不假。但这里仍是卡多雷的土地，恢复秩序便是警惕的哨兵们的职责——必要时不惜以铁腕为之。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290201, '一位不速之客。我没什么能招待的，不过请让我尽量尽一尽地主之谊。我叫扎拉扎尔·贤风，来自魔法之都、令人敬重的达拉然。我知道这个名号听着有些夸张，可我们的建筑师正大步推进，要把那座伟大的城市恢复往日的荣光。$B$B我和苏里奥是跟着哨兵远征队一起来的。遗憾的是，一牵扯到精通奥术的人，他们就有些戒心。他们允许我同行，却不许我在他们的营地歇脚。要我说，这是有点短视，不过我自保的本事绰绰有余。$B$B那么，有什么我能帮你的吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290301, '海岸始终危机四伏。在外要保持警觉。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- The coast remains treacherous, through and through. Stay vigilant out there.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290401, '幕天席地也许不太寻常，但这可是个绝好的机会，让你夜里躺着看满天繁星。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290501, '很久以前——甚至在第三次大战之前——我住在南迪斯。从那以后许多事都变了，可有一件事至今让我费解：牛头人那种坚韧。就是很久以前在此定居的那两个部族。说实话，我本以为他们在这儿撑不了这么久，结果被事实打了脸。说来惭愧，我必须承认。如今我明白了，那样的傲慢不适合我。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290601, '跟我们同行的那个人类带着一把很有意思的剑。他也许是个法师，可只要看到那样的美被凝在剑刃的钢里，我就忍不住要赞叹。求你，这事一个字也别跟指挥官提。一牵扯到奥术的使用者，她就很少肯让步——哪怕只是嘴上提到。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290701, '一万两千年前，泰兰达斯岛对艾露恩姐妹会而言曾是一处灵性重地。许多最虔诚、最受敬重的女祭司都在岛上那座高耸的圣殿里完成了宗教修行。$B$B可如今它已成废墟，被姐妹会遗弃。剩下的只有它的秘密、悔恨，以及埋在厚厚阴影之下的谜团。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6290801, '说清楚些。我强壮的角鹰兽能载你去哪里？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Speak clearly. Where can my mighty hippogryphs take you to?
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6291001, '我们剩下的人不多了。这片林地曾满是与荒野和谐共处的德鲁伊，哪怕泰兰达斯早已被弃置。如今同样是这些德鲁伊，却在向自己的同类开战。究竟是什么把他们逼到了这般疯狂？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6291101, '在月语海岸的林地里，我们都是塞纳留斯的门徒，践行他的教诲，一同研习自然的壮美。无论是暗夜精灵还是牛头人，在玛洛恩之子的指引下，我们本为一体。想到这样的日子即将结束，我心里沉重得很。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6291201, '我哥哥阿查克和我在大陆的月之林有很多朋友。想到他们可能就在那些玷污泰兰达斯废墟的入侵者当中，既令人厌恶，也令人悲伤。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6291301, '可怕的日子来了。光是保住这片圣地不被恶徒侵扰，就要耗尽我们所有力气。你愿意帮我们吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6291401, '班达拉尔正倾尽全力守护每一个人。我们荒野姐妹完全信得过他——第三次大战时，不正是他护住了我们、挡下燃烧军团吗。树妖们会尽全力助他！自然的守护者们会团结一心，坚定地对抗这世间的邪恶。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6291701, '我们的同胞正在偏离正道。他们被艾露恩之子的月光蒙蔽，被一个虚假的预兆引着走。如果我们不尽快干预，恐怕就要永远失去他们了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6292001, '在德莱尼中间，再没有比裂隙行走这门古老技艺更神圣的了。它曾广为流传，如今可悲地只剩下一具空壳——往昔我们这些裂隙行者能施展出的那份壮丽，已随万古之前的岁月散去，那时德拉诺的夜空还能旋舞出星河。看你一脸茫然，我担心你这样的族类根本无法领会这门法术的份量。你不必费神去琢磨那些蠢念头。裂隙行走是神圣的仪式，就算落魄成如今这副样子，也不会被你们这些下等种族玷污。编织奥术之网本身、从神圣的德拉诺水晶中汲取力量——这份力量只该由我们德莱尼拥有，别人都不配。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6292002, '裂隙大师，酋长之子阿尔利亚有块水晶想请你检视。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Riftmaster, Ar’lia, son of the chieftain, has this crystal he wants you to inspect.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6292101, '我在照看我们定居的这座岛上生长的植物。自从部族从扭曲虚空之外漂流到这里，这些草木便一天天坏下去。我和长者们推测，它们所苦的根源在于渗进土壤的德拉诺水晶残渣。这是个令人遗憾的后果。我们的到来损害了这片海岸，所以反过来照料它，是我们的义务。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6292201, '守住我们唯一这块农场越来越难了。不是本地的野兽，就是那些该死的仆从给我找麻烦！真想回到从前那些日子——安安静静种我的地，而不是时时把命提在手上。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6292301, '说吧，帕拉什卡。我有要事在身，没空闲扯。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295001, '卡多雷在卡利姆多的森林里生活了无数年，也驯服了那里的无情。这条路并不好走，但若你想见到明晚的月光，在荒野中自给自足、护住自己，至关重要。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295101, '林子里很危险，文明又常常远在天边。我可以教你怎么在严酷的荒野中活下来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295201, '如果你旅途需要紧要物资，尽管看看我的货物。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- If you are in need of vital necessities for your journeys, feel free to browse my wares.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295301, '我遇上艾辛是在一场大风雪里，当时我正在高处的山脊上乱走。认定自己快不行了，我缩在一块石头后面想保点暖。没多久我就昏了过去，等醒过来时，这个壮得吓人的姑娘已经把我从藏身处拖到了她的山间小屋。那一刻我就知道：这女人会成为我的妻子，就算要我移开山峦也得办成。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295401, '急着往野外跑，是吧？暖烘烘的炉火和一杯起沫的麦酒固然好，可在山间好好走一遭的畅快是无可替代的。走近些，我讲讲矮人在丹莫罗的严寒里活下来的法子。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295501, '进荒野之前一定要准备周全。别小看周密计划的重要性。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295601, '我们能在杜隆塔尔那要命的高温里活下来，绝不是靠运气。我们族人坚韧，但更重要的是机敏。你该磨炼自己的直觉和本事，否则在外头撑不了多久。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295701, '利用自然为自己所用，方法多得很。只要有点巧思和本事，哪怕最寻常的东西也能变得有用。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295801, '平原的馈赠十分丰厚，足以让我们受用大地母亲的恩泽，又不至于夺去她天生的美。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6295901, '多年来我们走遍卡利姆多的土地，一路被半人马劫掠者追逼。那些年里，我们从这片土地——它的凶险与它的顽固——身上学到了许多。想活下来，就得拼了命去争，因为外头对你没有半分仁慈。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6296301, '日子不好过吧，新手？我跟你说，这岛不是给软弱的人待的。想出人头地，就得往大了闯，也就意味着你得把手里捡到的一切都变成钱。想凑近点、学学我的门道？行啊行啊，不过是有代价的……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6296601, '我还记得自己躲在森林里，躲着那个自称是我母亲的卑劣怪物——那时我还没沦为此般诅咒的奴隶。一躲就是几个钟头，有时甚至好几天。当年练出来的本事我至今还在，那段凄惨日子里的经验，我也可以教给你——当然，得付钱。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6297301, '在双月的光辉下垂钓，说不定哪天就能钓上传闻中的白鳞鳗。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6297501, '歇息吧，疲惫的灵魂——你被冒险压着，必要时肩上还扛得起山峦的重量。让我旅店里点的熏香填满你的鼻腔，舒缓你僵硬紧绷的身体。让每一块肌肉都松开，让每一根骨头都舒坦得咔哒作响。歇息吧。明天又是新的一天。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6297601, '月语海岸上盘踞着好几个鬼魂，年轻人。我们有些先祖确实受到了惊扰，可这些饥饿、冰冷、满怀恨意的鬼魂，是精灵的魂灵。我感谢大地母亲取走了我的双眼——若非如此，我就不得不望着夜空，把视线从穆莎身上移开，正如她把视线从我们对援助的渴求上移开一样。她为何容许这些邪恶的鬼魂折磨我们，我不知道，因为她选择不作答。$B$B所幸，我倚靠的不止她一个。当苍白者把光移开时，蓝色者便越靠越近。你在我们的土地上遇到麻烦时，就抬头在天上找洛舍，年轻人。别人不肯听的时候，他会听。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6297701, '部族正处于极大的危难之中，可我父亲却视而不见。他变得固执，甚至可以说是执迷。他眼里只有安舍。他只看天上——不管是白日里光芒灼人的时候，还是夜里光芒透过穆莎洒下的时候。他信念太深，根本听不进道理。族人，我们的族人，那些离开村子的人，是因为恐惧和被忽视才走的。$B$B说自家亲人的不是，让我心里难受。大地母亲护着我吧，我再也做不到只是站在一旁看着。我不会为了一尊缺席神像的争执，让亲族的血白流。$B$B你在这儿算是外人，所以我求你，别只听我这一肚子怨气。在我需要的时候做我的朋友，这份情我永不会忘。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6297801, '走近些，冒险者。月蹄村的货物独一无二、品质无瑕。你心里想要的，这儿都有；还有更多！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6298001, '大地之环是来调查本地元素为何躁动不安的。它们在这儿实在太不安分了。赞美罗阿，这好歹能让我暂时离沙子和尘土远一些。身为沙地巨魔，自从我们的沙月村加入部落，逃离塔纳利斯就是我最大的愿望。你想不到我到杜隆塔尔时有多意外——不过是把沙子换成了灰土。连大地之环都把法阵设在石爪山。等这一切结束，我甚至可能会求月蹄部族让我留下来。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6298101, '别听那个蠢乌兹图克胡说。他偏爱风元素。哼。一个从前只会在沙子里瑟瑟发抖的软蛋。可真打起来他倒挺能扛，哪怕躲在暗影里也一样。他也许是我加入大地之环以来最好的同伴了——当然，泥偶除外。$B$B看好了，这才是真正的元素。它一动，大地就颤；它走过，岩石就碎。这正是兽人所求的力量与荣耀的化身。再没有哪种元素比你脚下的大地更坚实、更美丽。$B$B<洛特卡清了清嗓子。>$B$B我可能说得有些忘形了。你什么都没看见。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6298301, '这一带有人目击到几块古怪的水晶。一个月蹄部族的人把消息报到了雷霆崖，而皇家药剂师学会似乎对此颇感兴趣。研究这活就落到了我头上——说实话，这大概是能想出的最糟糕的主意。我不是打仗的料。我这辈子从没握过武器。虽说我有的是时间研究这些水晶，可我怕它们在我被练成一个像样的战士之前早就化成灰了。$B$B你看着像是爱冒险的那种人。何不来帮帮我？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6298401, '我还能闻到河角村飘来的烟味。它滞留在空气里，让我想起那场可怕的惨剧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6298601, '欢迎你来到摩洛盖村。我叫阿里亚，是酋长摩洛盖·克拉之子。我们这里少有来客，尤其在这样动荡的时局下；不过你尽可以把这儿当成自己的家。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6298701, '＜这名德莱尼人遭到殴打，一动不动地躺在地上。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The draenei has been beaten and lies motionless on the ground.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6298702, '＜检视猎人的尸体＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Inspect the hunter’s body>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6299301, '这世界满是奇景与惊喜。刚发现一件有趣的东西，转角又冒出一件！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6301601, '玛瓦吉尼和格拉姆为灵魂向导托尼兹说的那番关于大地本质的话，争了一上午。可听他们满嘴胡扯，我怀疑他们压根没听进去人家说了什么。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6301701, '格拉姆是个蠢货。大地是力量之元素！有了它，碾碎敌人易如反掌。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6301801, '玛瓦吉尼没那个本事成为真正的萨满。他以为大地元素是用来击溃敌人的，可它真正的用途是守护弱者。这谁都知道。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6301901, '岩鬃大师交给我解读这些石板的任务。它们属于古老的牛头人遗存，那时大地之环还很年轻。当年教团里的自然学者说的是卡利麦格语，也就是元素的语言。如今关于这门语言的知识早已失传，要把它译成兽人语得花上相当长的时间。但不管要多久，我都决心完成岩鬃大师的托付。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6302101, '学徒必须自己动手准备食物。这能磨炼自律，也让人懂得留意自己的饮食。强健的心智需要强健的体魄，而没有强健的心智，就无从与元素交流。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6304401, '坠落者围着摩洛盖村，像秃鹫盘旋在一头将死的牲口上方。想想他们当中有些人曾经是我们的朋友……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6304501, '我兄弟埃卡加尔跟着布罗比长者一起陷入了妄想。他一向容易轻信，可没想到他会这么轻易就抛下我们所有人……父亲要是还在，一定会深感羞耻。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6304601, '沿海一带打猎越来越难了。如今坠落者四处游荡，真正能狩猎的机会少之又少。可托鲁那个傻瓜偏要出去……那小子身上莽撞和天分一样多，说实话，带他真是件头疼事。我不知道纳尔兰是怎么做到的。对付年轻的托鲁，他好像天生就有一套。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6304701, '坠落者要为他们的亵渎之举付出代价。我绝不会袖手旁观，任由他们踏平摩洛盖村！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6304801, '我们驯服了几只这种大鸟，它们雄壮又令人敬畏，能驮很重的东西。可它们脾气倔，不肯让我们德莱尼骑上去。也许你运气好一些？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6304901, '妈妈说我们该先在旅店里躲着，可我更想跟阿里亚在外面玩。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6305401, '想不到月蹄酋长把我打发了，却肯接见那些愚蠢的风角。主母一定会大为不悦。好在不是所有耳朵都对我们的话充耳不闻。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6305601, '日子一天天过去，我越发想念弟弟。我选了挥舞锤子、为部族锻造的路，他走的是另一条。他离家去了血蹄村，要在那里成为一位伟大的战士。尽管想念他，我也盼着有一天他回来——一个目标得偿的男人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6305701, '警报：有挑战者接近。$B$B处理中。$B$B已确认目标无害。继续执行。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6305901, '又一个外来人。来吧，到我屋檐下歇歇。希望你不介意有人作伴。这个地精和他那位古怪的同伴被拒之门外，他们也需要休息。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6306001, '我从火花港一路赶来，想给这个部族帮点忙，可他们就是不许我进村。幸好这位长者让我在他的小屋里歇脚。也许他是可怜我，毕竟他自己也觉得在这些族人中间像个外人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6306901, '我的工具既实用又耐用！来见识一下德莱尼的工艺吧！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- My tools are both practical and durable! Come and be impressed by Draenei craftsmanship!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6307001, '这可不太像我想象中的退休之旅结局……') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- This isn’t exactly how I imagined my retirement voyage to end like...
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6307101, '沼泽从不留情。一步失足、一根断枝，甚至沼泽的瘴气，都足以让身经百战的战士跪倒在地。你要是肯听、也肯付钱，我可以教更高级的生存技巧——说不定哪天能救你一命。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6307201, '凄凉之地的其他地方，原本也像你在尼耶尔前哨站看到的这片绿意。可到最后，土壤里的生机被抽干，只剩下荒芜的死寂。你要是肯听、也肯付钱，我可以教你更高级的生存技巧——说不定哪天能救你一命。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6307501, '小精灵在树间飘荡，洒下一串美妙的旋律，在森林里回荡。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6307601, '这匹雄壮的角鹰兽根本不理你。你连让它斜眼一瞧的资格都没有。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6307701, '耐普图隆领主正派我们作为使者前往你们的世界，压制火元素的日益猖狂。凡人，这警告你也该听进去；他的智慧既不会出错，也无穷无尽。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6307801, '<克拉尔特看着你，似乎来了兴致>$B$B外来者，我是克拉尔特，曾是木喉的一员，如今不幸是仍走在月语海岸上的最后一个同族。黑根让我们的人陷入疯狂之后，他们便弃守了这里。$B$B那已经是很久以前的事了，我习惯独来独往。你要是路过，尽可来坐坐。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6308301, '哎呀，你好啊，年轻人。我是星行者长者，负责照看我们最神圣的仪式与典礼，也受托守护我们的传统。$B$B已经有许多人迁居到这里，只为等待「蓝色之子」归来的庆典。据说蓝色之子的回归，将为我们部族引以为傲的历史揭开新的篇章。$B$B无论蓝色之子的归来意味着什么，这都是一个特别的时刻——值得庆祝，也值得以仪式向我们祖先致敬。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Why hello there young one, I am Elder Starstrider. I am the one who looks after our most s
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6308401, '自然本身的力量是一种令人振奋的伟力。在这样的黑暗时期，照看自然、弥合邪恶留下的伤痕，正是德鲁伊的责任。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6308601, '我敢说夜空中每过一天就会多出一颗新星。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I swear there is a new star in the night sky with each passing day.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6308701, '啊，又有一只羊要来加入我们的羊群了？为了即将到来的庆典，许多人已经聚集到这里，还有不少人是为了躲避门口那些恶狼而来寻个庇护。$B$B看来「蓝色之子」的归来，来得正是时候。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6309401, '看好了，我是布尔罗克，云蹄的一员。$B$B<布尔罗克注视着你，仿佛这个名字本该赢得敬意>$B$B哼，你竟没听过这个名字？你跟其他人一样，无知，对我们的历史视而不见。我的部族在很久以前曾掌控千针石林，对牛头人也颇有影响。$B$B<布尔罗克傲慢地嗤了一声，为这番冒犯抬起了下巴。>') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6309501, '愿大地母亲善待你，并看顾你前行的路。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Earthmother be kind to you, and watch your path.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6309601, '静下心来，年轻人。让各部族重归和睦、在这世间的邪恶中寻得正道，是我们的职责。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6309701, '我们必须做黑暗中的光，为找不到救赎之路的人指路。维系牛头人的团结，正是我们这些虔诚牧师的责任。$B$B这世上有许多凶险，投向黑暗的堕落往往来自最意想不到的地方。许多人指望我们指引方向，我们就得把他们引上那条熟悉的、我们先祖走过的路。$B$B灵性与传统，一对手挽手，紧紧相连。少了其一我们便无法存续，正如我们彼此之间也无法分离。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6309801, '你是来寻求指引、寻求智慧的？这些东西要在内省与认清自我中找到。你会惊讶于自己心底埋着多少坚韧与勇气。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6310601, '纳迦悄悄爬上陆地，四处扩张势力。他们的图谋一定阴险，我能感觉到。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6311801, '我受命保卫月蹄村，抵御那些逼近我们边境的威胁。可最近看来，我倒成了个维持和睦的保姆。$B$B已经出过几场争执，都得我去调解，所以请别再火上浇油了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6311901, '真是场灾难——我那个蠢表亲把我派到这儿来。那么多能去的地方，偏偏是这个——这么远，这么古怪。$B$B这片土地确实奇怪，但别把我的不悦当成软弱。我大老远跑来不是为了失败。不管前面有什么考验，我都会扛过去，把任务办成。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6311902, '把你的故事告诉我，安达尼尔') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Tell me your story, Andanil
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6311904, '＜继续＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <continue>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6311906, '＜继续＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <continue>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6312001, '我就是伟大的皮桑！$B$B在盟友口中，我远近闻名，人称「正义者」；在敌人嘴里，我是「复仇者」！我曾在山巅与巨龙搏斗，从高耸而险峻的塔楼里救出少女，斩杀的恶徒多到数不清！$B$B我曾面对可怕的多头蛇特里奥克，活下来把这段经历讲给人听；我深入过玛拉顿最幽暗的深处，把潜伏在剃刀高地里的恶人绳之以法！$B$B我的事迹传遍四方，每个酒馆和厅堂里的吟游诗人都在唱！$B$B然而……咳咳……尽管有这般荣耀，我还是得问一句——你有没有碰巧在哪儿见过我的剑？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6312101, '啊……在这么不友善的地方还能见到一张友善的脸。$B$B<泰萨妮娅笑了，笑意边缘却卷起一抹阴影。>$B$B你当真千里迢迢赶来，是为了协助我们那桩……事业？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6312201, '别信沼泽里潜伏的那些……东西。它们在雾中窥视，耐心而无声。$B$B它们只在你放松警惕时才动手。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6312501, '替我哥哥道歉……他还没能接受……这件事。饥饿啃噬着他，也啃噬着我们许多人。其实我们到这儿来正是为此。在阿拉萨拉斯，许多人相信这些水晶——对，就是那些水晶——或许能扭转枯萎，或许还能救我们所有人。$B$B<卡利昂歇斯底里地笑了起来>$B$B一个字都别信。他们不在乎像我们这样的枯萎同族。他们给的只是一线希望，刚好够让我们继续往前爬。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6312601, '怎么？没见过枯瘦者？哈……再盯着看，你会后悔的。$B$B快滚开——趁饥饿还没吞掉我，趁我还没决定拿你来当下一个补品。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6312701, '我从未感受过这样的魔法，如此陌生，却又如此强大。连空气都在为它嗡鸣。还有这些水晶……它们绝非寻常玩物。$B$B我不禁要想——它们会不会正是拯救我们族人的关键？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6316301, '我们的先祖受到了惊扰。这片墓地已经不再是能安心悼念逝者的地方了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6316801, '小心，霜鬃族似乎在侵入我们的边境，试探我们的耐心。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Be wary, the Frostmane seem to be encroaching on our borders, and testing our patience.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6317101, '德莱尼的历史被刻在石板上，把它们永远铸入时间的编年。我们的家园德拉诺毁灭后，许多故事与传说都失传了，所以把族人的历史刻录在这些石板上，对我而言就更加要紧。这副担子，我扛得无比自豪。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6317401, '月蹄部族曾在这片海岸举行神圣的狩猎。科多兽的皮用来制作典礼用的鼓，肉则能供我们果腹多日。可如今这些外来的寄生虫肆意横行，我们的传统再也维持不下去了。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6317501, '我很担忧，$C。幼血们是在动荡与不安中长大的。我们曾在这座简陋的村子里和睦相处了许多个月，不惹事、也多半不与人来往。可看着墙外游荡的危险，看着它们以如此惊人的速度蔓延整片海岸，我为部族的存续感到害怕。这样的命运，我们该怎么理解？大地母亲一定是在考验我们的意志，一定是。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6317601, '我从恶齿村一路赶来，那地方在遥远的东方，辛特兰深处。像你这样爱聊的冒险者告诉我，这片湛蓝的海岸上，鱼既漂亮又肥美。我自然急着向族人证明，伟大的格乌贾比什么鱼都能钓到——不管是在家乡，还是在天涯海角。等我回去，他们准会为我写歌！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6317701, '＜这名守卫痛苦地哼了一声。＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <The defender grunts in pain.>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6317901, '朝圣之旅让你疲惫了吗？来歇一歇，让你的心神与自然合一。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Weary from your pilgrimage? Come rest a bit and let your mind become one with nature.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6318001, '我和敏法在玩「塔哈姆·图拉」！你要一起来吗？这是我最爱玩的游戏，你只要拿上这张小网，尽量多捞些小鱼就行！想赢就得特别有耐心、还得沉得住气。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6318101, '泰瑞姆·卡兰给塔哈姆·图拉编了网，可我觉得他在使坏——他给自己编的网比我的结实多了！这不是很过分吗？') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6318301, '在这片海岸游荡的鬼魂，并没意识到自己已是不死之身。在他们破碎的头脑里，他们仍在侍奉艾萨拉女王，就像一万两千年前那样。听着像悲惨的命运，其实更像个麻烦——至少对我来说是。你想象不到他们有多烦人，日复一日讲着同样的事。能把人逼疯。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6318901, '哎，走路看着点。我见过不止一个脚步沉重的矮人撞翻补给箱，我可不需要你也来这么一出。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6319001, '哎哎，我们之间没必要敌对。保持冷静和平吧。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Woah now, there is no need for any hostilities between us. Let’s keep it cool and calm.
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6319801, '洛卡塔尔。洒龙血的好日子，不是吗？你看上去有些犹豫、也不怎么起劲。别担心。我虽出身龙喉，但我打着部落的旗号，隶属裂鳞战团。捣乱与混乱也许看着像是我们的本性，可我告诉你，流浪者：到了该动手的时候，我们正是那些向艾泽拉斯更强的居者举起武器的人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (6320602, '卑鄙的联盟矮人已经侵入了我们在荆棘峡谷的圣地！快来参军，把这些害虫从大地母亲的土地上赶出去！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- 
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8016301, '＜看来狮鹫心里有事……＞') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- <Seems like Gryphon’s got something on his mind...>
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8016302, '带我去巴罗！') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- Take me to Balor!
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8045202, '我是来取附魔马蹄铁的') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I am here to collect the enchanted horseshoes
INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc4`) VALUES (8900001, '我只能训练已经掌握本行技艺的人。') ON DUPLICATE KEY UPDATE `male_text_loc4` = VALUES(`male_text_loc4`);  -- I can only train those who already know the trade.
